#!/usr/bin/env python3
"""Convert current Vice City VR saves between Win64 and Quest ARM64 layouts.

The game keeps the original fixed 201,828-byte save container on both
platforms.  The only ABI-dependent block in the current Win64/Quest builds is
CGarages: MSVC stores CStoredCar in 40 bytes, while Android Clang stores it in
36 bytes.  This tool reshapes that block and updates the additive checksum.

It intentionally rejects files that do not match the current save signature;
old retail/32-bit saves can contain additional ABI differences and must not be
silently converted as if they came from the current PC VR build.
"""

from __future__ import annotations

import argparse
import struct
import sys
from pathlib import Path


SAVE_SIZE = 201_828
GARAGE_PAYLOAD_SIZE = 7_876
FIXED_GARAGE_PREFIX = 44
STORED_CAR_COUNT = 48
GARAGE_COUNT = 32
GARAGE_SIZE = 184
GARAGE_STORED_CAR_OFFSET = 144

# The current Win64 build writes these fixed-size inner blocks.  Older x86
# saves use different ABI-dependent sizes while retaining the same 201,828-byte
# container and a valid checksum, so size/checksum checks alone are not enough
# to make an import safe.
CURRENT_WIN64_INNER_BLOCKS = (
    (7, "Cranes", 1_160),
    (8, "Pickups", 21_588),
    (9, "Phone", 4_408),
    (18, "PlayerInfo", 416),
)


class SaveConversionError(RuntimeError):
    pass


def align4(value: int) -> int:
    return (value + 3) & ~3


def outer_blocks(data: bytes) -> list[tuple[int, int, int]]:
    """Return (header offset, declared size, payload offset) save blocks."""
    result: list[tuple[int, int, int]] = []
    offset = 0
    checksum_offset = len(data) - 4
    while offset + 4 <= checksum_offset and len(result) < 40:
        declared_size = struct.unpack_from("<I", data, offset)[0]
        payload_offset = offset + 4
        end = payload_offset + align4(declared_size)
        if end > checksum_offset:
            raise SaveConversionError(
                f"block {len(result)} overruns save: offset={offset}, "
                f"size={declared_size}"
            )
        result.append((offset, declared_size, payload_offset))
        offset = end
        if offset == checksum_offset:
            break
    if offset != checksum_offset:
        raise SaveConversionError(
            f"save block stream ends at {offset}, checksum starts at "
            f"{checksum_offset}"
        )
    return result


def find_garage_payload(data: bytes) -> tuple[int, int]:
    matches: list[tuple[int, int]] = []
    for _header, outer_size, payload_offset in outer_blocks(data):
        if outer_size < 4:
            continue
        inner_size = struct.unpack_from("<I", data, payload_offset)[0]
        if inner_size == GARAGE_PAYLOAD_SIZE:
            matches.append((payload_offset + 4, inner_size))
    if len(matches) != 1:
        raise SaveConversionError(
            f"expected exactly one {GARAGE_PAYLOAD_SIZE}-byte garages block, "
            f"found {len(matches)}"
        )
    return matches[0]


def validate_current_win64_layout(data: bytes) -> None:
    """Reject retail/legacy x86 saves before attempting a Quest import."""
    blocks = outer_blocks(data)
    mismatches: list[str] = []
    for block_index, block_name, expected_inner_size in CURRENT_WIN64_INNER_BLOCKS:
        if block_index >= len(blocks):
            mismatches.append(
                f"{block_name} block {block_index}: missing "
                f"(expected inner size {expected_inner_size})"
            )
            continue
        _header, declared_size, payload_offset = blocks[block_index]
        if declared_size < 4:
            observed = f"outer size {declared_size}"
        else:
            observed = str(struct.unpack_from("<I", data, payload_offset)[0])
        if observed != str(expected_inner_size):
            mismatches.append(
                f"{block_name} block {block_index}: expected inner size "
                f"{expected_inner_size}, got {observed}"
            )
    if mismatches:
        raise SaveConversionError(
            "not a current Win64 Vice City VR save; original retail and "
            "legacy x86 saves cannot be imported safely (" + "; ".join(mismatches) + ")"
        )


def pc_car_to_quest(car: bytes) -> bytes:
    if len(car) != 40:
        raise SaveConversionError("invalid Win64 CStoredCar size")
    # Common data through the bitfield's first byte, then six int8 fields.
    return car[:29] + car[32:38] + b"\0"


def quest_car_to_pc(car: bytes) -> bytes:
    if len(car) != 36:
        raise SaveConversionError("invalid Quest CStoredCar size")
    return car[:29] + b"\0\0\0" + car[29:35] + b"\0\0"


def pc_payload_to_quest(payload: bytes) -> bytes:
    if len(payload) != GARAGE_PAYLOAD_SIZE:
        raise SaveConversionError("invalid garages payload size")
    cursor = FIXED_GARAGE_PREFIX
    output = bytearray(payload[:cursor])
    for _ in range(STORED_CAR_COUNT):
        output += pc_car_to_quest(payload[cursor : cursor + 40])
        cursor += 40
    for _ in range(GARAGE_COUNT):
        garage = payload[cursor : cursor + GARAGE_SIZE]
        if len(garage) != GARAGE_SIZE:
            raise SaveConversionError("truncated Win64 CGarage array")
        converted = bytearray(GARAGE_SIZE)
        converted[:GARAGE_STORED_CAR_OFFSET] = garage[:GARAGE_STORED_CAR_OFFSET]
        converted[
            GARAGE_STORED_CAR_OFFSET : GARAGE_STORED_CAR_OFFSET + 36
        ] = pc_car_to_quest(garage[GARAGE_STORED_CAR_OFFSET : GARAGE_SIZE])
        output += converted
        cursor += GARAGE_SIZE
    if cursor + 24 != GARAGE_PAYLOAD_SIZE:
        raise SaveConversionError("unexpected Win64 garages layout")
    output += bytes(GARAGE_PAYLOAD_SIZE - len(output))
    return bytes(output)


def quest_payload_to_pc(payload: bytes) -> bytes:
    if len(payload) != GARAGE_PAYLOAD_SIZE:
        raise SaveConversionError("invalid garages payload size")
    cursor = FIXED_GARAGE_PREFIX
    output = bytearray(payload[:cursor])
    for _ in range(STORED_CAR_COUNT):
        output += quest_car_to_pc(payload[cursor : cursor + 36])
        cursor += 36
    for _ in range(GARAGE_COUNT):
        garage = payload[cursor : cursor + GARAGE_SIZE]
        if len(garage) != GARAGE_SIZE:
            raise SaveConversionError("truncated Quest CGarage array")
        converted = bytearray(GARAGE_SIZE)
        converted[:GARAGE_STORED_CAR_OFFSET] = garage[:GARAGE_STORED_CAR_OFFSET]
        converted[GARAGE_STORED_CAR_OFFSET:GARAGE_SIZE] = quest_car_to_pc(
            garage[
                GARAGE_STORED_CAR_OFFSET : GARAGE_STORED_CAR_OFFSET + 36
            ]
        )
        output += converted
        cursor += GARAGE_SIZE
    if cursor + 216 != GARAGE_PAYLOAD_SIZE:
        raise SaveConversionError("unexpected Quest garages layout")
    output += bytes(GARAGE_PAYLOAD_SIZE - len(output))
    return bytes(output)


def validate_checksum(data: bytes) -> None:
    expected = struct.unpack_from("<I", data, len(data) - 4)[0]
    actual = sum(data[:-4]) & 0xFFFFFFFF
    if expected != actual:
        raise SaveConversionError(
            f"checksum mismatch: file={expected:#010x}, calculated={actual:#010x}"
        )


def convert(data: bytes, direction: str) -> bytes:
    if len(data) != SAVE_SIZE:
        raise SaveConversionError(
            f"unsupported save size {len(data)}; expected {SAVE_SIZE}"
        )
    validate_checksum(data)
    if direction == "pc-to-quest":
        validate_current_win64_layout(data)
    payload_offset, payload_size = find_garage_payload(data)
    payload = data[payload_offset : payload_offset + payload_size]
    if direction == "pc-to-quest":
        converted_payload = pc_payload_to_quest(payload)
    else:
        converted_payload = quest_payload_to_pc(payload)
    result = bytearray(data)
    result[payload_offset : payload_offset + payload_size] = converted_payload
    struct.pack_into("<I", result, len(result) - 4, sum(result[:-4]) & 0xFFFFFFFF)
    validate_checksum(result)
    return bytes(result)


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("direction", choices=("pc-to-quest", "quest-to-pc"))
    parser.add_argument("source", type=Path)
    parser.add_argument("destination", type=Path)
    args = parser.parse_args()
    try:
        source_data = args.source.read_bytes()
        converted = convert(source_data, args.direction)
        args.destination.parent.mkdir(parents=True, exist_ok=True)
        args.destination.write_bytes(converted)
    except (OSError, SaveConversionError) as exc:
        print(f"save conversion failed: {exc}", file=sys.stderr)
        return 1
    print(
        f"converted {args.source} -> {args.destination} "
        f"({args.direction}, {len(converted)} bytes)"
    )
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

[CmdletBinding()]
param(
    [ValidateSet("Import", "Export")]
    [string]$Mode,

    [ValidateRange(1, 8)]
    [int]$Slot,

    [string]$PcSaveDirectory,

    [string]$AdbPath,

    [string]$Serial,

    [switch]$Help
)

$ErrorActionPreference = "Stop"

trap {
    Write-Host ("Error: " + $_.Exception.Message) -ForegroundColor Red
    exit 1
}

$packageId = "com.libertyvr.quest"
$providerRoot = "content://$packageId.saves/slot"

function Show-Usage {
    Write-Host @"
Transfer Liberty City VR saves between the PC and Quest builds.

Usage:
  .\transfer-vr-save.ps1 -Mode Import -Slot 1 [-PcSaveDirectory PATH]
  .\transfer-vr-save.ps1 -Mode Export -Slot 1 [-PcSaveDirectory PATH]

Modes:
  Import  Transfer GTA3sfN.b from PC format and write it to Quest slot N.
  Export  Read Quest slot N, and write PC file GTA3sfN.b.

Options:
  -Slot 1..8             Save slot to transfer.
  -PcSaveDirectory PATH  Directory containing the PC GTA3sfN.b files.
  -AdbPath PATH          Optional explicit path to adb.exe.
  -Serial SERIAL         Select a Quest when multiple devices are connected.

If the slot or PC save directory is omitted, the script tries common local
locations and then asks for the missing value. Existing saves are backed up
under LibertyVR-save-backups before they are overwritten.
"@
}

function Resolve-AdbExecutable {
    param([string]$RequestedPath)

    $candidates = [System.Collections.Generic.List[string]]::new()
    if (-not [string]::IsNullOrWhiteSpace($RequestedPath)) {
        $candidates.Add($RequestedPath)
    }

    $candidates.Add((Join-Path $PSScriptRoot "platform-tools\adb.exe"))
    if (-not [string]::IsNullOrWhiteSpace($env:APPDATA)) {
        $candidates.Add((Join-Path $env:APPDATA "SideQuest\platform-tools\adb.exe"))
    }
    if (-not [string]::IsNullOrWhiteSpace($env:LOCALAPPDATA)) {
        $candidates.Add((Join-Path $env:LOCALAPPDATA "Programs\SideQuest\resources\app.asar.unpacked\build\platform-tools\adb.exe"))
        $candidates.Add((Join-Path $env:LOCALAPPDATA "Programs\SideQuest\resources\app.asar.unpacked\resources\app\platform-tools\adb.exe"))
    }
    if (-not [string]::IsNullOrWhiteSpace($env:ANDROID_SDK_ROOT)) {
        $candidates.Add((Join-Path $env:ANDROID_SDK_ROOT "platform-tools\adb.exe"))
    }
    if (-not [string]::IsNullOrWhiteSpace($env:ANDROID_HOME)) {
        $candidates.Add((Join-Path $env:ANDROID_HOME "platform-tools\adb.exe"))
    }

    $adbCommand = Get-Command "adb.exe" -ErrorAction SilentlyContinue
    if ($null -ne $adbCommand) {
        $candidates.Add($adbCommand.Source)
    }

    foreach ($candidate in $candidates) {
        if (-not [string]::IsNullOrWhiteSpace($candidate) -and
            (Test-Path -LiteralPath $candidate -PathType Leaf)) {
            return (Resolve-Path -LiteralPath $candidate).Path
        }
    }

    throw "adb.exe was not found. Install Android platform-tools or SideQuest, put adb.exe on PATH, or pass -AdbPath."
}

function Invoke-Adb {
    param(
        [Parameter(Mandatory = $true)]
        [string[]]$Arguments,

        [switch]$CaptureOutput
    )

    $fullArguments = [System.Collections.Generic.List[string]]::new()
    if (-not [string]::IsNullOrWhiteSpace($Serial)) {
        $fullArguments.Add("-s")
        $fullArguments.Add($Serial)
    }
    foreach ($argument in $Arguments) {
        $fullArguments.Add($argument)
    }

    if ($CaptureOutput) {
        $output = & $script:adbExecutable @fullArguments 2>&1
        if ($LASTEXITCODE -ne 0) {
            throw "adb failed: adb $($fullArguments -join ' ')`n$($output -join [Environment]::NewLine)"
        }
        return $output
    }

    & $script:adbExecutable @fullArguments
    if ($LASTEXITCODE -ne 0) {
        throw "adb failed: adb $($fullArguments -join ' ')"
    }
}

function Read-QuestSlotToFile {
    param(
        [Parameter(Mandatory = $true)]
        [string]$Uri,

        [Parameter(Mandatory = $true)]
        [string]$Destination
    )

    Invoke-Adb -Arguments @(
        "shell",
        "content read --uri '$Uri' > '$script:remoteTemporarySave'"
    )
    Invoke-Adb -Arguments @("pull", $script:remoteTemporarySave, $Destination)
    if (-not (Test-Path -LiteralPath $Destination -PathType Leaf) -or
        (Get-Item -LiteralPath $Destination).Length -eq 0) {
        throw "Quest returned an empty save for $Uri."
    }
}

function Write-QuestSlotFromFile {
    param(
        [Parameter(Mandatory = $true)]
        [string]$Uri,

        [Parameter(Mandatory = $true)]
        [string]$Source
    )

    Invoke-Adb -Arguments @("push", $Source, $script:remoteTemporarySave)
    Invoke-Adb -Arguments @(
        "shell",
        "content write --uri '$Uri' < '$script:remoteTemporarySave'"
    )
}

function Convert-Save {
    param(
        [Parameter(Mandatory = $true)]
        [ValidateSet("pc-to-quest", "quest-to-pc")]
        [string]$Direction,

        [Parameter(Mandatory = $true)]
        [string]$Source,

        [Parameter(Mandatory = $true)]
        [string]$Destination
    )

    [byte[]]$data = [IO.File]::ReadAllBytes($Source)
    if ($data.Length -lt 1024) {
        throw "Invalid save size $($data.Length); expected a valid GTA3 save file."
    }

    [uint64]$calculatedChecksum = 0
    for ($index = 0; $index -lt $data.Length - 4; $index++) {
        $calculatedChecksum = ($calculatedChecksum + $data[$index]) -band [uint64]4294967295
    }
    [uint32]$storedChecksum = [BitConverter]::ToUInt32($data, $data.Length - 4)
    if ([uint32]$calculatedChecksum -ne $storedChecksum) {
        Write-Warning ("Save checksum mismatch: file={0:X8}, calculated={1:X8}." -f
            $storedChecksum, [uint32]$calculatedChecksum)
    }

    $destinationDirectory = Split-Path -Parent $Destination
    if (-not [string]::IsNullOrWhiteSpace($destinationDirectory)) {
        New-Item -ItemType Directory -Path $destinationDirectory -Force | Out-Null
    }
    [IO.File]::Copy($Source, $Destination, $true)
    Write-Host "Transferred $Source -> $Destination ($Direction, $($data.Length) bytes)"
}

function Resolve-PcDirectory {
    param(
        [string]$RequestedPath,
        [string]$TransferMode,
        [int]$SaveSlot
    )

    if (-not [string]::IsNullOrWhiteSpace($RequestedPath)) {
        if (-not (Test-Path -LiteralPath $RequestedPath -PathType Container)) {
            throw "PC save directory does not exist: $RequestedPath"
        }
        return (Resolve-Path -LiteralPath $RequestedPath).Path
    }

    $candidates = [System.Collections.Generic.List[string]]::new()
    $candidates.Add((Join-Path $PSScriptRoot "..\userfiles"))
    $candidates.Add((Join-Path $PSScriptRoot "..\..\userfiles"))
    $candidates.Add((Join-Path $PSScriptRoot "..\..\..\userfiles"))
    $candidates.Add((Join-Path (Get-Location).Path "userfiles"))
    $candidates.Add((Get-Location).Path)
    $documents = [Environment]::GetFolderPath("MyDocuments")
    if (-not [string]::IsNullOrWhiteSpace($documents)) {
        $candidates.Add((Join-Path $documents "GTA3 User Files"))
    }

    foreach ($candidate in $candidates) {
        if (-not (Test-Path -LiteralPath $candidate -PathType Container)) {
            continue
        }
        $resolved = (Resolve-Path -LiteralPath $candidate).Path
        $requestedSaveExists = Test-Path -LiteralPath (Join-Path $resolved "GTA3sf$SaveSlot.b") -PathType Leaf
        $looksLikePcSaveDirectory =
            (Split-Path -Leaf $resolved).Equals("userfiles", [StringComparison]::OrdinalIgnoreCase) -or
            $null -ne (Get-ChildItem -LiteralPath $resolved -Filter "GTA3sf*.b" -File -ErrorAction SilentlyContinue | Select-Object -First 1)
        if (($TransferMode -eq "Import" -and $requestedSaveExists) -or
            ($TransferMode -eq "Export" -and $looksLikePcSaveDirectory)) {
            return $resolved
        }
    }

    $entered = Read-Host "Enter the PC save directory containing GTA3sfN.b"
    if ([string]::IsNullOrWhiteSpace($entered) -or
        -not (Test-Path -LiteralPath $entered -PathType Container)) {
        throw "PC save directory does not exist: $entered"
    }
    return (Resolve-Path -LiteralPath $entered).Path
}

function Get-QuestSlotSize {
    param([string]$Uri)

    $output = @(Invoke-Adb -Arguments @(
        "shell", "content", "query", "--uri", $Uri,
        "--projection", "_size"
    ) -CaptureOutput)
    $text = $output -join "`n"
    if ($text -match "_size=(\d+)") {
        return [int64]$Matches[1]
    }
    return 0L
}

function New-BackupDirectory {
    $timestamp = Get-Date -Format "yyyyMMdd-HHmmss"
    $path = Join-Path $script:pcDirectory "LibertyVR-save-backups\$timestamp-$($Mode.ToLowerInvariant())-slot$Slot"
    New-Item -ItemType Directory -Path $path -Force | Out-Null
    return $path
}

if ($Help) {
    Show-Usage
    exit 0
}
if ([string]::IsNullOrWhiteSpace($Mode)) {
    Show-Usage
    throw "-Mode Import or -Mode Export is required."
}
if ($Slot -eq 0) {
    $enteredSlot = Read-Host "Enter the save slot to transfer (1-8)"
    $parsedSlot = 0
    if (-not [int]::TryParse($enteredSlot, [ref]$parsedSlot) -or
        $parsedSlot -lt 1 -or $parsedSlot -gt 8) {
        throw "Save slot must be between 1 and 8."
    }
    $Slot = $parsedSlot
}
$script:pcDirectory = Resolve-PcDirectory -RequestedPath $PcSaveDirectory -TransferMode $Mode -SaveSlot $Slot
$pcSaveName = "GTA3sf$Slot.b"
$pcSavePath = Join-Path $script:pcDirectory $pcSaveName
$slotUri = "$providerRoot/$Slot"
$script:adbExecutable = Resolve-AdbExecutable -RequestedPath $AdbPath
$script:temporaryRoot = Join-Path ([IO.Path]::GetTempPath()) ("LibertyVR-save-transfer-" + [Guid]::NewGuid().ToString("N"))
New-Item -ItemType Directory -Path $script:temporaryRoot | Out-Null
$script:remoteTemporarySave = "/data/local/tmp/libertyvr-save-$Slot-$([Guid]::NewGuid().ToString('N')).b"

try {
    Write-Host "Using adb: $script:adbExecutable"
    Write-Host "PC saves: $script:pcDirectory"
    Write-Host "Quest URI: $slotUri"

    $deviceOutput = @(Invoke-Adb -Arguments @("get-state") -CaptureOutput)
    if (($deviceOutput | Select-Object -Last 1).ToString().Trim() -ne "device") {
        throw "Quest is not ready. Put on the headset, accept USB debugging, and retry."
    }
    $packageOutput = @(Invoke-Adb -Arguments @("shell", "pm", "path", $packageId) -CaptureOutput)
    if (-not ($packageOutput | Where-Object { $_.ToString().Trim().StartsWith("package:") })) {
        throw "Liberty City VR is not installed on the connected Quest."
    }

    Write-Host "Stopping Liberty City VR before save transfer..."
    Invoke-Adb -Arguments @("shell", "am", "force-stop", $packageId)

    if ($Mode -eq "Import") {
        if (-not (Test-Path -LiteralPath $pcSavePath -PathType Leaf)) {
            throw "PC save was not found: $pcSavePath"
        }

        $questInput = Join-Path $script:temporaryRoot "$Slot.quest.b"
        Convert-Save -Direction "pc-to-quest" -Source $pcSavePath -Destination $questInput

        $remoteSize = Get-QuestSlotSize -Uri $slotUri
        if ($remoteSize -gt 0) {
            $backupDirectory = New-BackupDirectory
            $nativeBackup = Join-Path $backupDirectory "$Slot.quest-native.b"
            $pcBackup = Join-Path $backupDirectory $pcSaveName
            Write-Host "Backing up existing Quest slot $Slot to $backupDirectory"
            Read-QuestSlotToFile -Uri $slotUri -Destination $nativeBackup
            Convert-Save -Direction "quest-to-pc" -Source $nativeBackup -Destination $pcBackup
        }

        Write-Host "Writing PC save to Quest slot $Slot..."
        Write-QuestSlotFromFile -Uri $slotUri -Source $questInput

        $verificationCopy = Join-Path $script:temporaryRoot "$Slot.verify.b"
        Read-QuestSlotToFile -Uri $slotUri -Destination $verificationCopy
        $sourceHash = (Get-FileHash -LiteralPath $questInput -Algorithm SHA256).Hash
        $destinationHash = (Get-FileHash -LiteralPath $verificationCopy -Algorithm SHA256).Hash
        if ($sourceHash -ne $destinationHash) {
            throw "Quest save verification failed after writing slot $Slot."
        }

        Write-Host "Import complete: $pcSavePath -> Quest slot $Slot" -ForegroundColor Green
    } else {
        $questOutput = Join-Path $script:temporaryRoot "$Slot.quest.b"
        $convertedOutput = Join-Path $script:temporaryRoot $pcSaveName
        Write-Host "Reading Quest slot $Slot..."
        Read-QuestSlotToFile -Uri $slotUri -Destination $questOutput
        Convert-Save -Direction "quest-to-pc" -Source $questOutput -Destination $convertedOutput

        if (Test-Path -LiteralPath $pcSavePath -PathType Leaf) {
            $backupDirectory = New-BackupDirectory
            Write-Host "Backing up existing PC slot $Slot to $backupDirectory"
            Copy-Item -LiteralPath $pcSavePath -Destination (Join-Path $backupDirectory $pcSaveName)
        }

        Copy-Item -LiteralPath $convertedOutput -Destination $pcSavePath -Force
        Write-Host "Export complete: Quest slot $Slot -> $pcSavePath" -ForegroundColor Green
    }
} finally {
    if (-not [string]::IsNullOrWhiteSpace($script:remoteTemporarySave) -and
        -not [string]::IsNullOrWhiteSpace($script:adbExecutable)) {
        try {
            Invoke-Adb -Arguments @("shell", "rm", "-f", $script:remoteTemporarySave)
        } catch {
            Write-Warning "Could not remove temporary Quest file: $script:remoteTemporarySave"
        }
    }
    if (-not [string]::IsNullOrWhiteSpace($script:temporaryRoot) -and
        (Test-Path -LiteralPath $script:temporaryRoot -PathType Container)) {
        Remove-Item -LiteralPath $script:temporaryRoot -Recurse -Force
    }
}

"""Summarize local per-frame captures; accepts several runs for A/B comparison."""
import argparse
import csv
import json
import math
from collections import Counter
from pathlib import Path

EVENTS = {
    1: "damage", 2: "died", 4: "recovered_after_death", 8: "entered_vehicle",
    16: "left_vehicle", 32: "weapon_used", 64: "player_appeared",
    128: "player_disappeared", 256: "relocated_over_50_units",
    512: "pause_changed", 1024: "cutscene_changed", 2048: "mission_changed",
    4096: "wanted_changed",
}


GPU_PASSES = ["sky", "roads", "reflections", "world", "water", "fading", "weather",
              "effects", "ui", "scope", "wrist", "resolve_postprocess", "other", "scene"]
DRAW_COUNTERS = ["draws", "elements", "triangles", "geometry_known_draws", "mesh_passes",
                 "extra_split_draws", "alpha_requested_draws", "texture_alpha_draws",
                 "vertex_alpha_draws", "material_alpha_draws", "alpha_test_draws",
                 "depth_write_draws", "ps2_split_draws", "vehicle_split_draws",
                 "distance_fade_draws", "skinned_draws"]


ATOMIC_SUBMISSION_COLUMNS = ["vk_static_atomic_calls", "vk_static_atomic_pipeline_requests",
    "vk_static_atomic_pipeline_binds", "vk_static_atomic_texture_requests",
    "vk_static_atomic_texture_binds", "vk_static_atomic_texture_lookups"]


def summarize_static_instances(rows):
    if not rows or "static_instances_enabled" not in rows[0]:
        return None
    keys=["queued_draws", "groups", "instances", "saved_draws", "reject_state", "reject_bounds",
          "reject_order", "reject_spatial", "pipeline_misses", "allocation_failures", "source_indices", "emitted_indices"]
    valid,invalid=[],0
    for row in rows:
        try:
            v={k:int(row["static_instances_"+k]) for k in keys}
            cpu=float(row["static_instances_flush_ms"])
            if (min(v.values())<0 or not math.isfinite(cpu) or cpu<0 or
                    v["source_indices"]!=v["emitted_indices"] or
                    v["instances"]-v["groups"]!=v["saved_draws"] or
                    v["instances"]>v["queued_draws"] or v["instances"]<2*v["groups"]):
                raise ValueError("Inconsistent instancing sample")
            v["flush_ms"]=cpu;valid.append(v)
        except (ValueError,KeyError):
            invalid+=1
    return {"valid_frames":len(valid),"invalid_frames":invalid,
            "per_frame":{k:distribution([v[k] for v in valid]) for k in keys+["flush_ms"]},
            "totals":{k:sum(v[k] for v in valid) for k in keys},
            "note":"Actual instanced submissions; indices include all instances. Flush timer excludes collection/bounds setup."}


def summarize_static_reuse(rows):
    if not rows or "static_reuse_sampled" not in rows[0]:
        return None
    counters = ["candidates", "groups", "geometry_repeats", "compatible_instances",
                "nearby_instances", "adjacent_instances", "reject_state", "reject_owner",
                "reject_transform", "table_overflow", "owner_overflow", "max_instances"]
    valid, invalid, models, seen = [], 0, Counter(), set()
    for row in rows:
        if row["static_reuse_sampled"] == "0":
            continue
        try:
            source = int(row["static_reuse_source_frame_id"])
            values = {key: int(row["static_reuse_"+key]) for key in counters}
            cpu = float(row["static_reuse_cpu_ms"])
            model = int(row["static_reuse_top_model"])
            if (row["static_reuse_sampled"] != "1" or source != int(row["frame_id"]) or source in seen
                    or min(values.values()) < 0 or not math.isfinite(cpu) or cpu < 0
                    or values["groups"] > values["candidates"]
                    or values["nearby_instances"] > values["compatible_instances"]
                    or values["compatible_instances"] > values["candidates"]):
                raise ValueError("Invalid static reuse sample")
            seen.add(source);values["cpu_ms"] = cpu;valid.append(values)
            if model >= 0: models[model] += 1
        except (KeyError, ValueError):
            invalid += 1
    return {"sampled_frames": len(valid), "invalid_frames": invalid,
            "per_sample": {key: distribution([v[key] for v in valid]) for key in counters+["cpu_ms"]},
            "totals": {key: sum(v[key] for v in valid) for key in counters},
            "top_model_frame_counts": dict(models),
            "note": "Opportunity counts, not merged draws or predicted savings. CPU-side source frame; sampled only. "
                    "Geometry repeats are draw-level; compatible instances deduplicate owners per exact-state group. "
                    "Near counts are within 32 m of the first owner. Overflow makes counts lower bounds."}


def summarize_atomic_submission(rows):
    if not rows or any(key not in rows[0] for key in ATOMIC_SUBMISSION_COLUMNS):
        return None
    totals = Counter()
    valid = invalid = 0
    for row in rows:
        if row.get("vk_begin_detail_valid") != "1":
            continue
        values = {key: int(row[key]) for key in ATOMIC_SUBMISSION_COLUMNS}
        p, pb, t, tb, lookups = (values[key] for key in ATOMIC_SUBMISSION_COLUMNS[1:])
        if min(values.values()) < 0 or pb > p or tb > t or lookups > t or p != t:
            invalid += 1
            continue
        valid += 1
        totals.update(values)
    if not valid:
        return {"valid_frames": 0, "invalid_frames": invalid}
    p, pb, t, tb, lookups = (totals[key] for key in ATOMIC_SUBMISSION_COLUMNS[1:])
    return {"valid_frames": valid, "invalid_frames": invalid, "totals": dict(totals),
        "mean_per_frame": {key: value/valid for key, value in totals.items()},
        "pipeline_binds_skipped": p-pb, "texture_binds_skipped": t-tb,
        "texture_lookups_avoided": t-lookups,
        "pipeline_skip_percent": 100*(p-pb)/p if p else None,
        "texture_skip_percent": 100*(t-tb)/t if t else None}


def summarize_alpha_bound(rows):
    keys = ["masked_alpha_bound_candidates", "masked_alpha_bound_solid_passes_skipped",
            "masked_alpha_bound_indices_skipped"]
    if not rows or any(key not in rows[0] for key in keys):
        return None
    valid, invalid = [], 0
    for row in rows:
        values = [int(row[key]) for key in keys]
        if min(values) < 0 or values[1] > values[0]:
            invalid += 1
        else:
            valid.append(values)
    return {"valid_frames": len(valid), "invalid_frames": invalid,
            "frames_with_skips": sum(v[1] > 0 for v in valid),
            "totals": {key: sum(v[i] for v in valid) for i, key in enumerate(keys)},
            "per_frame": {key: distribution([v[i] for v in valid]) for i, key in enumerate(keys)},
            "note": "Conservative empty solid-pass decisions; indices are not multiplied by eye count. Not measured GPU savings."}


def summarize_opaque_order(rows):
    keys = ["opaque_order_candidates", "opaque_order_eligible", "opaque_order_swaps"]
    if not rows or any(key not in rows[0] for key in keys):
        return None
    rejection_keys = [key for key in rows[0] if key.startswith("opaque_order_reject_")]
    totals = {key: sum(int(row[key]) for row in rows) for key in rejection_keys}
    accounted = (all(int(row["opaque_order_candidates"]) == int(row["opaque_order_eligible"]) +
                     sum(int(row[key]) for key in rejection_keys) for row in rows)
                 if rejection_keys else None)
    return {"per_frame": {key: distribution([float(row[key]) for row in rows]) for key in keys},
            "rejection_totals": totals, "candidate_accounting_valid": accounted,
            "frames_with_swaps": sum(int(row["opaque_order_swaps"]) > 0 for row in rows),
            "note": "Swaps are adjacent exchanges within groups of at most 32 visible slots; not draw-call savings."}


def summarize_draw_details(path, rows, selected_ids, metadata):
    companion = path.with_name(path.name.replace(".frames.csv", ".draws.csv"))
    if not companion.is_file():
        return {"available": False, "reason": "Missing .draws.csv companion", "file": str(companion)}
    sources = {int(r["frame_id"]): r for r in rows}
    gpu = {}
    for r in rows:
        source = int(r.get("gpu_pass_frame_id", 0))
        if (r.get("gpu_pass_status") == "1" and source in sources and source <= int(r["frame_id"])
                and r["gpu_pass_start_monotonic_ns"] == sources[source]["start_monotonic_ns"]
                and math.isfinite(float(r["gpu_pass_frame_ms"])) and float(r["gpu_pass_frame_ms"]) >= 0):
            gpu[source] = r
    accepted, seen = set(), set()
    phases, models, windows = {}, {}, {}
    invalid = excluded = unmatched = count_rows = overflow = contexts = unattributed = 0
    peak_models = peak_capacity = growths = allocation_failures = overflow_samples = 0
    omitted_by_phase = Counter()
    start_ns = int(rows[0]["start_monotonic_ns"])

    def accumulate(target, key, values):
        target.setdefault(key, Counter()).update(values)

    def consume(group):
        nonlocal invalid, excluded, unmatched, overflow, contexts, unattributed
        nonlocal peak_models, peak_capacity, growths, allocation_failures, overflow_samples
        try:
            source = int(group[0]["source_frame_id"])
            if source in seen:
                raise ValueError("Repeated source group")
            seen.add(source)
            if source not in sources or source not in gpu:
                unmatched += 1
                return
            if any(int(r["source_start_ns"]) != int(sources[source]["start_monotonic_ns"]) for r in group):
                raise ValueError("Source timestamp mismatch")
            if source not in selected_ids:
                excluded += 1
                return
            totals, detail, keys = {}, [], set()
            lost = int(group[0]["model_overflow_draws"])
            context = int(group[0]["context_overflows"])
            if lost < 0 or context < 0:
                raise ValueError("Negative loss counts")
            for r in group:
                phase = r["phase"]
                values = {k: int(r[k]) for k in DRAW_COUNTERS}
                if phase not in GPU_PASSES or any(v < 0 for v in values.values()):
                    raise ValueError("Invalid counters")
                if int(r["model_overflow_draws"]) != lost or int(r["context_overflows"]) != context:
                    raise ValueError("Inconsistent source loss counts")
                if r["kind"] == "phase":
                    key = ("phase", phase)
                    totals[phase] = values
                elif r["kind"] == "model":
                    key = (phase, int(r["model_id"]), int(r["entity_class"]), r["model_name"])
                    detail.append((key, values))
                else:
                    raise ValueError("Invalid record kind")
                if key in keys:
                    raise ValueError("Repeated source bucket")
                keys.add(key)
            if set(totals) != set(GPU_PASSES):
                raise ValueError("Incomplete phase group")
            sums = {phase: Counter() for phase in GPU_PASSES}
            for key, values in detail:
                sums[key[0]].update(values)
            for phase in GPU_PASSES:
                if totals[phase]["draws"] != int(gpu[source][f"gpu_pass_{phase}_draw_calls"]):
                    raise ValueError("Draw counts disagree with GPU payload")
                if any(sums[phase][k] > totals[phase][k] for k in DRAW_COUNTERS):
                    raise ValueError("Model counters exceed phase totals")
                if not lost and any(sums[phase][k] != totals[phase][k] for k in DRAW_COUNTERS):
                    raise ValueError("Unaccounted model counters")
            if sum(v["draws"] for v in totals.values())-sum(v["draws"] for _, v in detail) != lost:
                raise ValueError("Overflow does not reconcile")
            capacity_fields = ["model_buckets", "model_capacity", "model_table_growths", "model_allocation_failures"]
            capacity_info = None
            if any(k in group[0] for k in capacity_fields):
                capacity_info = tuple(int(group[0][k]) for k in capacity_fields)
                buckets, capacity, expanded, failures = capacity_info
                if min(capacity_info) < 0 or buckets != len(detail) or capacity < buckets:
                    raise ValueError("Invalid model capacity accounting")
                if any(tuple(int(r[k]) for k in capacity_fields) != capacity_info for r in group):
                    raise ValueError("Inconsistent capacity accounting")
            second = int(((int(sources[source]["start_monotonic_ns"])-start_ns)/1e9)//5)*5
            window = windows.setdefault(second, {"samples": 0, "gpu_sum": 0, "phases": {}, "models": {},
                                                "model_overflow_draws": 0, "peak_model_buckets": 0})
            window["samples"] += 1
            window["gpu_sum"] += float(gpu[source]["gpu_pass_frame_ms"])
            window["model_overflow_draws"] += lost
            window["peak_model_buckets"] = max(window["peak_model_buckets"], len(detail))
            for phase, values in totals.items():
                accumulate(phases, phase, values)
                accumulate(window["phases"], phase, values)
                omitted_by_phase[phase] += values["draws"]-sums[phase]["draws"]
            for key, values in detail:
                accumulate(models, key, values)
                accumulate(window["models"], key, values)
                if key[1] < 0:
                    unattributed += values["draws"]
            overflow += lost
            contexts += context
            overflow_samples += int(lost > 0)
            peak_models = max(peak_models, len(detail))
            if capacity_info:
                peak_capacity = max(peak_capacity, capacity)
                growths += expanded
                allocation_failures += failures
            accepted.add(source)
        except (KeyError, ValueError, TypeError):
            invalid += 1

    with companion.open(newline="", encoding="utf-8") as stream:
        group, identity = [], None
        for row in csv.DictReader(stream):
            count_rows += 1
            next_id = row.get("source_frame_id")
            if group and next_id != identity:
                consume(group)
                group = []
            identity = next_id
            group.append(row)
        if group:
            consume(group)

    def phase_summary(data, n):
        return {phase: {"totals": dict(values), "mean_per_sample": {k: v/n for k, v in values.items()}}
                for phase, values in data.items()} if n else {}

    def model_summary(data, n, rank="draws"):
        return [{"phase": key[0], "model_id": key[1], "entity_class": key[2], "name": key[3],
                 "totals": dict(values), "mean_draws_per_sample": values["draws"]/n,
                 "mean_triangles_per_sample": values["triangles"]/n}
                for key, values in sorted(data.items(), key=lambda item: item[1][rank], reverse=True)[:20]] if n else []

    n = len(accepted)
    total_draws = sum(v["draws"] for v in phases.values())
    return {"available": bool(n), "file": str(companion.resolve()), "samples": n,
            "rows": count_rows, "row_count_matches_metadata": count_rows == int(metadata.get("draw_rows", count_rows)),
            "invalid_source_groups": invalid, "unmatched_sources": unmatched, "excluded_nongameplay_sources": excluded,
            "missing_gpu_sources": len((set(gpu) & selected_ids)-accepted),
            "model_overflow_draws": overflow, "context_overflows": contexts,
            "model_rankings_truncated": bool(overflow), "overflow_samples": overflow_samples,
            "peak_model_buckets": peak_models, "peak_model_capacity": peak_capacity or None,
            "model_table_growths": growths, "model_allocation_failures": allocation_failures,
            "omitted_model_draws_by_phase": dict(omitted_by_phase),
            "unattributed_draw_fraction": unattributed/total_draws if total_draws else None,
            "attributed_draw_fraction": (total_draws-unattributed-overflow)/total_draws if total_draws else None,
            "phases": phase_summary(phases, n), "top_models_by_draws": model_summary(models, n),
            "top_models_by_triangles": model_summary(models, n, "triangles"),
            "slow_5s_windows": [{"source_elapsed_s": second, "samples": w["samples"],
                "gpu_frame_mean_ms": w["gpu_sum"]/w["samples"],
                "model_overflow_draws": w["model_overflow_draws"], "peak_model_buckets": w["peak_model_buckets"],
                "phases": phase_summary(w["phases"], w["samples"]),
                "top_models_by_draws": model_summary(w["models"], w["samples"]),
                "top_models_by_triangles": model_summary(w["models"], w["samples"], "triangles")}
                for second, w in sorted(windows.items(), key=lambda item: item[1]["gpu_sum"]/item[1]["samples"], reverse=True)[:10]],
            "notes": ["Triangles count submitted primitives, including split passes; strip/fan degenerates are not removed.",
                      "Multiview draw and triangle counts are not multiplied by eye count.",
                      "Reasons overlap and indicate submitted features, not pixel coverage or exclusive GPU cost.",
                      "Model scope includes descendants rendered inside the entity; unscopeable draws are explicitly unattributed.",
                      "Model histogram overflow leaves phase totals intact and limits model rankings."]}


def summarize_gpu_passes(rows, selected_ids, start_ns, interval=8, sampling="fixed", timing_scope="legacy_in_render_pass"):
    if "gpu_pass_frame_id" not in rows[0]:
        return None
    sources = {int(row["frame_id"]): row for row in rows}
    seen = set()
    samples, statuses = [], Counter()
    repeated = unmatched = mismatched = excluded = 0
    for row in rows:  # Filter by the source frame, never the readback row.
        source = int(row["gpu_pass_frame_id"])
        if not source:
            continue
        if source in seen:
            repeated += 1
            continue
        seen.add(source)
        status = int(row["gpu_pass_status"])
        statuses[str(status)] += 1
        if source not in sources:
            unmatched += 1
            continue
        original = sources[source]
        if (int(row["gpu_pass_start_monotonic_ns"]) != int(original["start_monotonic_ns"])
                or source > int(row["frame_id"])):
            mismatched += 1
            continue
        if source not in selected_ids:
            excluded += 1
            continue
        if status != 1:
            continue
        mask = int(row["gpu_pass_valid_mask"])
        frame_ms = float(row["gpu_pass_frame_ms"])
        if not mask or mask & ~((1 << len(GPU_PASSES))-1) or not math.isfinite(frame_ms) or frame_ms < 0:
            mismatched += 1
            continue
        samples.append((source, original, row, mask))
    passes = {}
    for i, name in enumerate(GPU_PASSES):
        matching = [row for _, _, row, mask in samples if mask & (1 << i)]
        passes[name] = {
            "gpu_ms": distribution([float(row[f"gpu_pass_{name}_ms"]) for row in matching]),
            "draw_calls": distribution([int(row[f"gpu_pass_{name}_draw_calls"])
                                        for _, _, row, _ in samples
                                        if f"gpu_pass_{name}_draw_calls" in row]),
        }
    bins = {}
    for _, original, row, mask in samples:
        second = (int(original["start_monotonic_ns"])-start_ns)/1e9
        bins.setdefault(int(second//5)*5, []).append((row, mask))
    windows = []
    for second, group in bins.items():
        means = {}
        for i, name in enumerate(GPU_PASSES):
            values = [float(row[f"gpu_pass_{name}_ms"]) for row, mask in group if mask & (1 << i)]
            values = [v for v in values if math.isfinite(v) and v >= 0]
            if values:
                means[name] = sum(values)/len(values)
        windows.append({"source_elapsed_s": second, "samples": len(group),
                        "gpu_frame_mean_ms": sum(float(row["gpu_pass_frame_ms"]) for row, _ in group)/len(group),
                        "pass_mean_ms": means})
    interval = max(1, interval)
    if sampling == "rotating_phase_one_per_block":
        expected = {source for source in selected_ids if (source-1) % interval == ((source-1)//interval) % interval}
    else:
        expected = {source for source in selected_ids if source % interval == 0}
    return {
        "available": bool(samples), "unique_selected_samples": len(samples),
        "sample_interval_frames": interval, "sampling": sampling,
        "timing_scope": timing_scope,
        "timing_attribution_reliable": timing_scope == "outside_render_pass_bottom_of_pipe_intervals",
        "expected_source_frames": len(expected),
        "unobserved_source_frames": len(expected-seen), "unique_status_counts": dict(statuses),
        "repeated_observations_ignored": repeated, "unmatched_source_frames": unmatched,
        "mismatched_source_frames": mismatched, "excluded_nongameplay_sources": excluded,
        "gpu_frame_ms": distribution([float(row["gpu_pass_frame_ms"]) for _, _, row, _ in samples]),
        "passes": passes,
        "slow_5s_windows": sorted(windows, key=lambda item: item["gpu_frame_mean_ms"], reverse=True)[:10],
        "notes": (["Legacy in-render-pass timestamps cannot reliably attribute scene cost on tiled GPUs."]
                  if timing_scope != "outside_render_pass_bottom_of_pipe_intervals" else
                  ["Only whole render passes are GPU-timed; logical scene phases have draw counts and CPU timings only."]) +
                 ["Intervals are approximate primary-lane Vulkan timestamps, not exclusive shader costs.",
                  "Sampling, timestamp dependencies and tile-based execution can perturb or redistribute timings.",
                  "Pending GPU results at capture shutdown are not drained with extra waits."]}


def distribution(values):
    values = sorted(v for v in values if math.isfinite(v) and v >= 0)
    if not values:
        return None

    def percentile(fraction):
        index = (len(values) - 1) * fraction
        lo = int(index)
        hi = min(lo + 1, len(values) - 1)
        return values[lo] + (values[hi] - values[lo]) * (index - lo)

    return {
        "samples": len(values), "mean": sum(values) / len(values),
        "median": percentile(.5), "p95": percentile(.95),
        "p99": percentile(.99), "max": values[-1],
    }


def summarize(path, include_nongameplay=False, allow_incomplete=False):
    if not path.name.endswith(".frames.csv"):
        raise ValueError("Expected a new .frames.csv capture, not the one-second quest_perf.csv")
    metadata_path = path.with_name(path.name.replace(".frames.csv", ".session.csv"))
    with metadata_path.open(encoding="utf-8") as stream:
        metadata = dict((row["key"], row["value"]) for row in csv.DictReader(stream))
    if metadata.get("schema") not in ("1", "2", "3", "4", "5", "6"):
        raise ValueError("Unsupported capture schema")
    complete = metadata.get("closed") == "1" and metadata.get("write_error") == "0"
    if not complete and not allow_incomplete:
        raise ValueError("Capture was not cleanly closed; set profiling OFF first, or use --allow-incomplete")
    with path.open(encoding="utf-8") as stream:
        reader = csv.DictReader(stream)
        rows = list(reader)
    if not rows:
        raise ValueError("No captured frames")
    # Ignore a truncated trailing row only when explicitly salvaging a capture.
    partial_rows = sum(None in row or any(value is None for value in row.values()) for row in rows)
    if partial_rows:
        if not allow_incomplete:
            raise ValueError("Malformed/truncated CSV rows")
        rows = [row for row in rows if None not in row and all(v is not None for v in row.values())]
    if not rows:
        raise ValueError("No complete CSV rows")
    ids = [int(row["frame_id"]) for row in rows]
    starts = [int(row["start_monotonic_ns"]) for row in rows]
    if any(b <= a for a, b in zip(ids, ids[1:])) or any(b <= a for a, b in zip(starts, starts[1:])):
        raise ValueError("Frame IDs and monotonic timestamps must increase")
    if complete and int(metadata["written_rows"]) != len(rows):
        raise ValueError("Session row count does not match frame data")
    selected = rows if include_nongameplay else [row for row in rows if
        row["player_valid"] == "1" and row["paused"] == "0" and
        row["cutscene"] == "0" and row["dead"] == "0"]
    selected_ids = {int(row["frame_id"]) for row in selected}
    interval_ids = {b for a, b in zip(ids, ids[1:])
                    if b == a + 1 and a in selected_ids and b in selected_ids}
    events = Counter()
    for row in rows:
        mask = int(row["event_mask"])
        events.update(name for flag, name in EVENTS.items() if mask & flag)
    vehicle_speeds = {}
    for row in selected:
        if row.get("in_vehicle") != "1" or "vehicle_speed_kmh" not in row:
            continue
        model = row["vehicle_model"]
        vehicle_speeds.setdefault(model, []).append(row)
    vehicle_summary = {}
    for model, samples in vehicle_speeds.items():
        speeds = distribution([float(row["vehicle_speed_kmh"]) for row in samples])
        vehicle_summary[model] = {
            "speed_kmh": speeds,
            "observed_top_kmh": speeds["max"] if speeds else None,
            "speed_3d_kmh": distribution([float(row["vehicle_speed_3d_kmh"]) for row in samples]),
            "recorded_occupancy_peak_kmh": distribution([float(row["vehicle_peak_kmh"]) for row in samples]),
            "handling_cruise_kmh": sorted({float(row["vehicle_handling_cruise_kmh"]) for row in samples
                                            if float(row["vehicle_handling_cruise_kmh"]) >= 0}),
            "transmission_max_kmh": sorted({float(row["vehicle_transmission_max_kmh"]) for row in samples
                                             if float(row["vehicle_transmission_max_kmh"]) >= 0}),
        }
    timings = {}
    for key in ["frame_interval_ms", "cpu_local_ms", "vk_begin_ms", "step_ms",
                "recorder_prepare_ms", "runtime_cpu_ms", "runtime_gpu_ms", "vulkan_gpu_ms",
                "game_ms", "streaming_ms", "script_ms", "population_ms", "car_ms",
                "world_process_ms", "world_list_ms", "world_render_ms", "render_fading_ms",
                "vk_begin_pipeline_ms", "vk_begin_fence_wait_ms", "vk_begin_timestamp_ms",
                "vk_begin_retirement_ms", "vk_begin_setup_ms", "vk_begin_wrist_ms",
                "vk_begin_backend_total_ms"]:
        values = []
        if key not in rows[0]:
            timings[key] = None
            continue
        phase_keys = ["game", "streaming", "population", "car", "audio", "world_list",
                      "pre_render", "scene_setup", "world_render", "ui", "particle_update",
                      "particle_render", "script", "pre_world_misc", "world_process",
                      "post_world_camera_fx", "render_sky", "render_roads", "render_reflections",
                      "render_world", "render_water", "render_fading", "render_weather", "render_effects"]
        phase_name = key.removesuffix("_ms")
        for row in selected:
            if key.startswith("vk_begin_") and key != "vk_begin_ms" and row.get("vk_begin_detail_valid") != "1":
                continue
            if key == "frame_interval_ms" and int(row["frame_id"]) not in interval_ids:
                continue
            if phase_name in phase_keys and not int(row["phase_valid_mask"]) & (1 << phase_keys.index(phase_name)):
                continue
            values.append(float(row[key]))
        timings[key] = distribution(values)
    begin_parts = ["vk_begin_pipeline_ms", "vk_begin_fence_wait_ms", "vk_begin_timestamp_ms",
                   "vk_begin_retirement_ms", "vk_begin_setup_ms", "vk_begin_wrist_ms"]
    begin_stalls = []
    for row in sorted(selected, key=lambda item: float(item["vk_begin_ms"]), reverse=True):
        if row.get("vk_begin_detail_valid") != "1" or float(row["vk_begin_ms"]) < 5:
            continue
        parts = {key: float(row[key]) for key in begin_parts}
        parts["vk_begin_outside_backend_ms"] = max(0.0,
            float(row["vk_begin_ms"])-float(row["vk_begin_backend_total_ms"]))
        begin_stalls.append({
            "frame_id": int(row["frame_id"]),
            "elapsed_s": (int(row["start_monotonic_ns"])-starts[0])/1e9,
            "outer_begin_ms": float(row["vk_begin_ms"]), "parts_ms": parts,
            "largest_recorded_section": max(parts, key=parts.get),
            "counts": {key: int(row[key]) for key in ["vk_pipeline_requests", "vk_pipelines_created",
                "vk_pipeline_failures", "vk_retired_buffers", "vk_retired_images",
                "vk_retired_descriptors", "vk_upload_commands", "vk_framebuffer_created",
                "vk_last_pipeline_key"]},
        })
        if len(begin_stalls) == 10:
            break
    return {
        "file": str(path.resolve()), "metadata": metadata, "complete": complete,
        "rows": len(rows), "selected_rows": len(selected), "partial_rows_ignored": partial_rows,
        "selection": "all" if include_nongameplay else "player present, unpaused, outside cutscene, alive",
        "span_seconds": (starts[-1] - starts[0]) / 1e9,
        "missing_ids_between_rows": sum(b-a-1 for a, b in zip(ids, ids[1:])),
        "dropped_rows": int(metadata.get("dropped_rows", rows[-1]["dropped_rows"])),
        "activity_frames": dict(Counter(row["activity"] for row in selected)),
        "vehicle_speeds_by_model": vehicle_summary,
        "recorded_configuration": {key: sorted({row[key] for row in selected}) for key in
            ["active_world", "active_vegetation", "active_vehicles", "active_peds", "active_weapons",
             "render_width", "render_height", "render_scale_effective", "refresh_hz",
             "profiler_display_mode", "opaque_world_alpha_fast_path_enabled", "opaque_order_experiment_enabled", "replay_forward_view_active", "masked_alpha_pass_skip_enabled", "opaque_mesh_batch_enabled", "static_instances_enabled", "world_lod_mode", "world_backface_enabled", "world_occlusion_enabled", "lod_fade_transition_enabled", "fxaa_integer_sampling_enabled", "fxaa_integer_sampling_active"] if key in rows[0]},
        "events_all_frames": dict(events), "timings_ms": timings,
        "atomic_submission": summarize_atomic_submission(selected),
        "static_reuse": summarize_static_reuse(selected),
        "static_instances": summarize_static_instances(selected),
        "world_occlusion_source_model_frames": dict(Counter(row["world_occlusion_source_top_model"]
            for row in selected if int(row.get("world_occlusion_source_top_model", "-1"))>=0)),
        "world_occlusion": {key: distribution([float(row[key]) for row in selected]) for key in
            ("world_occlusion_builds", "world_occlusion_occluder_candidates", "world_occlusion_occluders",
             "world_occlusion_triangles", "world_occlusion_cell_updates", "world_occlusion_candidates",
             "world_occlusion_rejected", "world_occlusion_visible", "world_occlusion_invalid", "world_occlusion_budget",
             "world_occlusion_left_cells", "world_occlusion_right_cells", "world_occlusion_raster_tests",
             "world_occlusion_query_tests", "world_occlusion_indices_avoided", "world_occlusion_vertices_avoided",
             "world_occlusion_build_ms", "world_occlusion_query_ms",
             "world_occlusion_raster_rows", "world_occlusion_selected_triangles",
             "world_occlusion_cache_builds", "world_occlusion_cache_hits", "world_occlusion_cache_scanned",
             "world_occlusion_cache_deferred", "world_occlusion_source_objects", "world_occlusion_source_projected",
             "world_occlusion_source_projection_rejected", "world_occlusion_source_small",
             "world_occlusion_source_budget_skipped", "world_occlusion_source_top_samples",
             "world_occlusion_footprint_candidates", "world_occlusion_footprint_rejected",
             "world_occlusion_footprint_uncertain", "world_occlusion_footprint_selected",
             "world_occlusion_footprint_capacity_skipped") if key in rows[0]},
        "world_backface": {key: distribution([float(row[key]) for row in selected]) for key in
            ("world_backface_candidates", "world_backface_draws", "world_backface_reject_state",
             "world_backface_reject_geometry", "world_backface_reject_view", "world_backface_reject_transform",
             "world_backface_certifications", "world_backface_indices", "world_backface_certify_ms") if key in rows[0]},
        "world_lod": {key: distribution([int(row[key]) for row in selected]) for key in
            ("world_lod_high_selections", "world_lod_lower_selections", "world_lod_entity_selections",
             "world_lod_suppressed", "world_lod_missing_selections", "world_lod_paired_models", "world_lod_unpaired_models") if key in rows[0]},
        "opaque_mesh_batch": {key: {"mean": sum(int(r[key]) for r in selected)/len(selected), "max": max(int(r[key]) for r in selected)}
            for key in ("opaque_mesh_batch_eligible", "opaque_mesh_batch_checks", "opaque_mesh_batch_merged_meshes",
                "opaque_mesh_batch_saved_draws", "opaque_mesh_batch_reject_state", "opaque_mesh_batch_reject_material",
                "opaque_mesh_batch_reject_range") if key in rows[0]},
        "opaque_order": summarize_opaque_order(selected),
        "masked_alpha_bound": summarize_alpha_bound(selected),
        "renderdoc_capture": {
            "diagnostic_run": metadata.get("renderdoc_attached_at_start") == "1" or
                ";renderdoc=1;" in metadata.get("simulation_replay", "") or
                any(row.get("renderdoc_capture_active") == "1" for row in rows),
            "active_frame_ids": [int(row["frame_id"]) for row in rows if row.get("renderdoc_capture_active") == "1"],
            "note": "Capture instrumentation and file writing can affect this and neighboring frames; use an unhooked run for benchmarking.",
        } if "renderdoc_capture_active" in rows[0] or ";renderdoc=" in metadata.get("simulation_replay", "") or metadata.get("renderdoc_attached_at_start") == "1" else None,
        "gpu_pass_profile": summarize_gpu_passes(rows, selected_ids, starts[0], int(metadata.get("gpu_pass_interval_frames", "8")), metadata.get("gpu_pass_sampling", "fixed"), metadata.get("gpu_pass_scope", "legacy_in_render_pass")),
        "draw_profile": summarize_draw_details(path, rows, selected_ids, metadata) if metadata.get("schema") == "6" else None,
        "vk_begin_stalls_over_5ms_top10": begin_stalls,
        "notes": [
            "GPU samples are latest asynchronous observations, not attributed to the row's CPU frame.",
            "Frame intervals include pacing; they are not compositor missed-frame counts.",
            "Drops, canceled frames and selection gaps limit tail comparisons; inspect them before comparing.",
            "Recorder preparation excludes queue submission and disk-worker contention; measure total overhead separately.",
            "Begin subphase timers are synchronous CPU wall times; waits/preemption can contribute to any section.",
        ],
    }


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("captures", nargs="+", type=Path)
    parser.add_argument("--include-nongameplay", action="store_true")
    parser.add_argument("--allow-incomplete", action="store_true")
    args = parser.parse_args()
    try:
        results = [summarize(path, args.include_nongameplay, args.allow_incomplete) for path in args.captures]
        print(json.dumps(results, indent=2, allow_nan=False))
    except (ValueError, KeyError, OSError) as error:
        parser.exit(1, f"{error}\n")


if __name__ == "__main__":
    main()

# Assembles a buildable source tree for the Liberty City VR Quest port. # # .\tools\assemble.ps1 -Re3 <path to re3 source> -Out <output dir> # # The re3 source tree is not part of this repository and is not distributed # with it. The tested patch base is commit b050e1cc63b1869e6b514ab2f1a00ef4969e0c84 # from mrxenginner/re3. param( [Parameter(Mandatory=$true)][Alias("Revc")][string]$Re3, [Parameter(Mandatory=$true)][string]$Out ) $ErrorActionPreference = "Stop" $repo = Split-Path $PSScriptRoot -Parent
if (-not (Test-Path (Join-Path $Re3 "src\core\main.cpp"))) { Write-Error "'$Re3' does not look like a re3 source tree (src\core\main.cpp not found)" } if (Test-Path $Out) { Write-Error "'$Out' already exists; refusing to overwrite" }
Write-Host "[1/4] Copying the re3 tree..." New-Item -ItemType Directory -Path $Out | Out-Null robocopy $Re3 $Out /E /NFL /NDL /NJH /NJS /XD ".git" /XF ".git" | Out-Null if ($LASTEXITCODE -ge 8) { Write-Error "Failed to copy re3 (robocopy exit code $LASTEXITCODE). Remove the partial output and retry." }
Write-Host "[2/4] Applying the port patches..." if (Test-Path (Join-Path $Out ".git")) { Remove-Item -Force -Recurse (Join-Path $Out ".git") } Push-Location $Out git init -q 2>$null
$patchFiles = Get-ChildItem -Path (Join-Path $repo "patches") -Filter "*.patch" | Sort-Object Name foreach ($patch in $patchFiles) { Write-Host "Applying $($patch.Name)..." git apply --whitespace=nowarn $patch.FullName if ($LASTEXITCODE -ne 0) { Pop-Location Write-Error "Patch $($patch.Name) did not apply cleanly. The source must be a clean checkout of commit b050e1cc63b1869e6b514ab2f1a00ef4969e0c84 with no local edits." } } Remove-Item -Recurse -Force (Join-Path $Out ".git") Pop-Location
Write-Host "[3/4] Copying the port sources..." robocopy (Join-Path $repo "overlay") $Out /E /NFL /NDL /NJH /NJS | Out-Null if ($LASTEXITCODE -ge 8) { Write-Error "Failed to copy the Quest overlay (robocopy exit code $LASTEXITCODE)." }
Write-Host "[4/4] Copying librw with the Vulkan backend..." robocopy (Join-Path $repo "librw") (Join-Path $Out "vendor\librw") /E /NFL /NDL /NJH /NJS | Out-Null if ($LASTEXITCODE -ge 8) { Write-Error "Failed to copy librw (robocopy exit code $LASTEXITCODE)." }
Write-Host "" Write-Host "Done. Next steps:" Write-Host " cd $Out\android" Write-Host " gradle wrapper (first time only, or open in Android Studio)" Write-Host " .\gradlew assembleDebug" Write-Host "See BUILDING.md for prerequisites, game data, VR hands and headset installation."

# Builds and optionally installs a personal Liberty City VR Quest APK.
# No APK, re3 source, retail data, saves, or third-party model pack is
# distributed by this repository. The user supplies/downloads each input.
[CmdletBinding()]
param(
    [string]$GameDir,
    [string]$WorkDir = "C:\LCVRBuild",
    [string]$AndroidSdk,
    [string]$JavaHome,
    [string]$Serial,
    [string]$LogPath = (Join-Path $env:TEMP "LibertyCityVR-Build-And-Install.log"),
    [switch]$BuildOnly,
    [switch]$Release,
    [switch]$SkipGameData,
    [switch]$UpdateOnly,
    [switch]$NonInteractive
)

$ErrorActionPreference = "Stop"
$ProgressPreference = "SilentlyContinue"

$testedRe3Commit = "b050e1cc63b1869e6b514ab2f1a00ef4969e0c84"
$re3Url = "https://github.com/mrxenginner/re3.git"
$re3Branch = "master"
$gitVersion = "2.55.0.3"
$gitUrl = "https://github.com/git-for-windows/git/releases/download/v2.55.0.windows.3/MinGit-2.55.0.3-64-bit.zip"
$gitSha256 = "F48E2D2DC74A24454ADC6D8FD0AC25BF9C2386F19CFB06202B9465AAAD4F9F05"
$androidCommandLineToolsVersion = "15859902"
$androidCommandLineToolsUrl = "https://dl.google.com/android/repository/commandlinetools-win-15859902_latest.zip"
$androidCommandLineToolsSha256 = "90AE805D20434428BFFCB699C290860F19BB5F66A67E6B330067E3DE801FB04A"
$jdkVersion = "21.0.11+10"
$jdkUrl = "https://github.com/adoptium/temurin21-binaries/releases/download/jdk-21.0.11%2B10/OpenJDK21U-jdk_x64_windows_hotspot_21.0.11_10.zip"
$jdkSha256 = "D3625E7CADF23787EA540229544B6E2AB494B3B54DA1801879E583E1DFEE0A64"
$gradleVersion = "8.13"
$gradleUrl = "https://services.gradle.org/distributions/gradle-$gradleVersion-bin.zip"
$gradleSha256 = "20F1B1176237254A6FC204D8434196FA11A4CFB387567519C61556E8710AED78"
$ndkVersion = "27.2.12479018"
$cmakeVersion = "3.22.1"
$remoteGameData = "/sdcard/Android/data/com.libertyvr.quest/files/gamedata"
$saveProviderUri = "content://com.libertyvr.quest.saves/slot/1"
$repoRoot = Split-Path $PSScriptRoot -Parent
. (Join-Path $PSScriptRoot "device-diagnostics.ps1")
$script:transcriptStarted = $false
$script:replacedIncompatibleInstall = $false
$script:replacementGameDir = $null

try {
    $logDirectory = Split-Path -Parent $LogPath
    if (-not [string]::IsNullOrWhiteSpace($logDirectory)) {
        New-Item -ItemType Directory -Path $logDirectory -Force | Out-Null
    }
    Initialize-PrivateDiagnosticLog
    $script:transcriptStarted = $true
} catch {
    Write-Host "Warning: diagnostic logging could not start: $($_.Exception.Message)" -ForegroundColor Yellow
}

function Stop-DiagnosticLog {
    if (-not $script:transcriptStarted) { return }
    $script:diagnosticLogEnabled = $false
    $script:transcriptStarted = $false
}

function Write-Step {
    param([int]$Number, [string]$Text)
    Write-Host ""
    Write-Host "[$Number/8] $Text" -ForegroundColor Cyan
}

function Invoke-Checked {
    param(
        [Parameter(Mandatory = $true)][string]$FilePath,
        [Parameter(Mandatory = $true)][string[]]$Arguments,
        [string]$FailureMessage = "Command failed"
    )
    if (-not (Test-Path -LiteralPath $FilePath -PathType Leaf)) {
        throw "$FailureMessage (required tool is missing)."
    }
    # Windows PowerShell 5.1 wraps native stderr in ErrorRecords. Warnings
    # from Gradle/sdkmanager must remain visible without terminating a
    # successful command; the process exit code determines command failure.
    $savedErrorPreference = $ErrorActionPreference
    try {
        $ErrorActionPreference = "Continue"
        if ($FilePath -eq $script:adb) {
            Invoke-PrivateAdb @Arguments | ForEach-Object { Write-Host $_ }
        } else {
            & $FilePath @Arguments 2>&1 | ForEach-Object { Write-Host ([string]$_) }
        }
        $exitCode = $LASTEXITCODE
    } finally {
        $ErrorActionPreference = $savedErrorPreference
    }
    if ($exitCode -ne 0) {
        throw "$FailureMessage (exit code $exitCode)."
    }
}

function Find-JavaHome {
    $candidates = [System.Collections.Generic.List[string]]::new()
    if (-not [string]::IsNullOrWhiteSpace($JavaHome)) { $candidates.Add($JavaHome) }
    if (-not [string]::IsNullOrWhiteSpace($env:JAVA_HOME)) { $candidates.Add($env:JAVA_HOME) }
    $candidates.Add("C:\Program Files\Android\Android Studio\jbr")
    $candidates.Add((Join-Path $env:LOCALAPPDATA "Programs\Android Studio\jbr"))

    foreach ($candidate in $candidates) {
        if ([string]::IsNullOrWhiteSpace($candidate)) { continue }
        $java = Join-Path $candidate "bin\java.exe"
        if (-not (Test-Path -LiteralPath $java -PathType Leaf)) { continue }
        # java.exe deliberately writes its version banner to stderr. Windows
        # PowerShell 5.1 turns that into an ErrorRecord under our strict global
        # preference even though java exits successfully, so inspect it under
        # Continue and restore the caller's policy immediately afterward.
        $savedErrorPreference = $ErrorActionPreference
        $ErrorActionPreference = "Continue"
        try {
            $versionText = (& $java -version 2>&1 | Out-String)
        } finally {
            $ErrorActionPreference = $savedErrorPreference
        }
        if ($versionText -match 'version "21(?:\.|\")') {
            return (Resolve-Path -LiteralPath $candidate).Path
        }
    }

    # Android Studio installations do not always expose their bundled JBR in
    # a standard location. Keep the one-click path deterministic by fetching a
    # pinned official Eclipse Temurin JDK when no suitable local Java exists.
    $javaWorkRoot = [IO.Path]::GetFullPath($WorkDir)
    $javaDownloads = Join-Path $javaWorkRoot ".downloads"
    $javaTools = Join-Path $javaWorkRoot ".tools"
    $javaZip = Join-Path $javaDownloads "OpenJDK21U-jdk_x64_windows_hotspot_21.0.11_10.zip"
    $downloadedJavaHome = Join-Path $javaTools "jdk-$jdkVersion"
    $downloadedJava = Join-Path $downloadedJavaHome "bin\java.exe"
    New-Item -ItemType Directory -Path $javaDownloads,$javaTools -Force | Out-Null

    if (-not (Test-Path -LiteralPath $downloadedJava -PathType Leaf)) {
        if (-not (Test-Path -LiteralPath $javaZip -PathType Leaf)) {
            Write-Host "JDK 21 was not found; downloading official Eclipse Temurin $jdkVersion..." -ForegroundColor Yellow
            Invoke-WebRequest -UseBasicParsing -Uri $jdkUrl -OutFile $javaZip
        }
        $observedHash = (Get-FileHash -Algorithm SHA256 -LiteralPath $javaZip).Hash
        if ($observedHash -ne $jdkSha256) {
            throw "Temurin JDK archive hash mismatch. Expected $jdkSha256, got $observedHash. Delete $javaZip and retry."
        }
        Expand-Archive -LiteralPath $javaZip -DestinationPath $javaTools -Force
    }
    if (-not (Test-Path -LiteralPath $downloadedJava -PathType Leaf)) {
        throw "Temurin JDK extraction did not create $downloadedJava"
    }
    return $downloadedJavaHome
}

function Find-Git {
    $installed = Get-Command git.exe -ErrorAction SilentlyContinue
    if ($null -ne $installed) { return $installed.Source }

    $gitWorkRoot = [IO.Path]::GetFullPath($WorkDir)
    $gitDownloads = Join-Path $gitWorkRoot ".downloads"
    $gitTools = Join-Path $gitWorkRoot ".tools"
    $gitZip = Join-Path $gitDownloads "MinGit-$gitVersion-64-bit.zip"
    $gitHome = Join-Path $gitTools "MinGit-$gitVersion"
    $gitExe = Join-Path $gitHome "cmd\git.exe"
    New-Item -ItemType Directory -Path $gitDownloads,$gitTools -Force | Out-Null

    if (-not (Test-Path -LiteralPath $gitExe -PathType Leaf)) {
        if (-not (Test-Path -LiteralPath $gitZip -PathType Leaf)) {
            Write-Host "Git was not found; downloading official portable MinGit $gitVersion..." -ForegroundColor Yellow
            Invoke-WebRequest -UseBasicParsing -Uri $gitUrl -OutFile $gitZip
        }
        $observedHash = (Get-FileHash -Algorithm SHA256 -LiteralPath $gitZip).Hash
        if ($observedHash -ne $gitSha256) {
            throw "MinGit archive hash mismatch. Expected $gitSha256, got $observedHash. Delete $gitZip and retry."
        }
        Expand-Archive -LiteralPath $gitZip -DestinationPath $gitHome -Force
    }
    if (-not (Test-Path -LiteralPath $gitExe -PathType Leaf)) {
        throw "Portable MinGit extraction did not create $gitExe"
    }
    return $gitExe
}

function Ensure-AndroidCommandLineTools {
    param([Parameter(Mandatory = $true)][string]$SdkRoot)

    $managerCandidates = @(
        (Join-Path $SdkRoot "cmdline-tools\latest\bin\sdkmanager.bat"),
        (Join-Path $SdkRoot "cmdline-tools\bin\sdkmanager.bat")
    )
    $existingManager = $managerCandidates | Where-Object {
        Test-Path -LiteralPath $_ -PathType Leaf
    } | Select-Object -First 1
    if ($null -ne $existingManager) { return $existingManager }

    $sdkWorkRoot = [IO.Path]::GetFullPath($WorkDir)
    $sdkDownloads = Join-Path $sdkWorkRoot ".downloads"
    $sdkTools = Join-Path $sdkWorkRoot ".tools"
    $toolsZip = Join-Path $sdkDownloads "commandlinetools-win-$androidCommandLineToolsVersion.zip"
    $extractRoot = Join-Path $sdkTools "android-command-line-tools-$androidCommandLineToolsVersion"
    $latestRoot = Join-Path $sdkRoot "cmdline-tools\latest"
    $sdkManager = Join-Path $latestRoot "bin\sdkmanager.bat"
    New-Item -ItemType Directory -Path $sdkDownloads,$sdkTools,$SdkRoot -Force | Out-Null

    if (-not (Test-Path -LiteralPath $sdkManager -PathType Leaf)) {
        if (-not (Test-Path -LiteralPath $toolsZip -PathType Leaf)) {
            Write-Host "Android SDK command-line tools are missing; downloading them from Google..." -ForegroundColor Yellow
            Invoke-WebRequest -UseBasicParsing -Uri $androidCommandLineToolsUrl -OutFile $toolsZip
        }
        $observedHash = (Get-FileHash -Algorithm SHA256 -LiteralPath $toolsZip).Hash
        if ($observedHash -ne $androidCommandLineToolsSha256) {
            throw "Android command-line tools hash mismatch. Expected $androidCommandLineToolsSha256, got $observedHash. Delete $toolsZip and retry."
        }
        Expand-Archive -LiteralPath $toolsZip -DestinationPath $extractRoot -Force
        $extractedTools = Join-Path $extractRoot "cmdline-tools"
        if (-not (Test-Path -LiteralPath (Join-Path $extractedTools "bin\sdkmanager.bat") -PathType Leaf)) {
            throw "Android command-line tools archive has an unexpected layout."
        }
        New-Item -ItemType Directory -Path $latestRoot -Force | Out-Null
        Copy-Item -Path (Join-Path $extractedTools "*") -Destination $latestRoot -Recurse -Force
    }
    if (-not (Test-Path -LiteralPath $sdkManager -PathType Leaf)) {
        throw "Android SDK bootstrap did not create $sdkManager"
    }
    return $sdkManager
}

function Find-AndroidSdk {
    $candidates = [System.Collections.Generic.List[string]]::new()
    if (-not [string]::IsNullOrWhiteSpace($AndroidSdk)) { $candidates.Add($AndroidSdk) }
    if (-not [string]::IsNullOrWhiteSpace($env:ANDROID_HOME)) { $candidates.Add($env:ANDROID_HOME) }
    if (-not [string]::IsNullOrWhiteSpace($env:ANDROID_SDK_ROOT)) { $candidates.Add($env:ANDROID_SDK_ROOT) }
    $candidates.Add((Join-Path $env:LOCALAPPDATA "Android\Sdk"))

    foreach ($candidate in $candidates) {
        if ([string]::IsNullOrWhiteSpace($candidate)) { continue }
        $hasAdb = Test-Path -LiteralPath (Join-Path $candidate "platform-tools\adb.exe") -PathType Leaf
        $hasManager = (Test-Path -LiteralPath (Join-Path $candidate "cmdline-tools\latest\bin\sdkmanager.bat") -PathType Leaf) -or
            (Test-Path -LiteralPath (Join-Path $candidate "cmdline-tools\bin\sdkmanager.bat") -PathType Leaf)
        if ($hasAdb -or $hasManager) {
            return (Resolve-Path -LiteralPath $candidate).Path
        }
    }

    $sdkRoot = Join-Path ([IO.Path]::GetFullPath($WorkDir)) ".android-sdk"
    New-Item -ItemType Directory -Path $sdkRoot -Force | Out-Null
    Ensure-AndroidCommandLineTools -SdkRoot $sdkRoot | Out-Null
    return $sdkRoot
}

function Get-MissingSdkPackages {
    param([string]$SdkRoot)
    $requirements = @(
        [PSCustomObject]@{ Path = "platforms\android-35\android.jar"; Package = "platforms;android-35" },
        [PSCustomObject]@{ Path = "build-tools\34.0.0"; Package = "build-tools;34.0.0" },
        [PSCustomObject]@{ Path = "platform-tools\adb.exe"; Package = "platform-tools" },
        # The file each component is known by, not the folder. A download
        # that stopped part way leaves the folder behind; a folder test
        # then reports the component present, the wizard skips it, and
        # the build fails much later with CXX1101 naming the very
        # source.properties that never arrived.
        [PSCustomObject]@{ Path = "ndk\$ndkVersion\source.properties"; Package = "ndk;$ndkVersion" },
        [PSCustomObject]@{ Path = "cmake\$cmakeVersion\bin\cmake.exe"; Package = "cmake;$cmakeVersion" }
    )
    return @($requirements | Where-Object {
        -not (Test-Path -LiteralPath (Join-Path $SdkRoot $_.Path))
    })
}

function Ensure-SdkPackages {
    param([string]$SdkRoot)
    $missing = @(Get-MissingSdkPackages -SdkRoot $SdkRoot)
    if ($missing.Count -eq 0) { return }

    Write-Host "Missing Android SDK components:" -ForegroundColor Yellow
    $missing | ForEach-Object { Write-Host "  $($_.Package)" }
    $sdkManager = Ensure-AndroidCommandLineTools -SdkRoot $SdkRoot
    if ($NonInteractive) {
        throw "Required Android SDK components are missing; automatic installation needs an interactive license confirmation."
    }
    $answer = Read-Host "Install the missing SDK components now? You may need to accept Google licenses [Y/n]"
    if (-not [string]::IsNullOrWhiteSpace($answer) -and $answer -notmatch '^[Yy]') {
        throw "Required SDK components were not installed."
    }
    & $sdkManager "--sdk_root=$SdkRoot" --licenses
    if ($LASTEXITCODE -ne 0) { throw "Android SDK license step failed." }
    Invoke-Checked -FilePath $sdkManager -Arguments (@("--sdk_root=$SdkRoot") + @($missing.Package)) `
        -FailureMessage "Android SDK component installation failed"
    $stillMissing = @(Get-MissingSdkPackages -SdkRoot $SdkRoot)
    if ($stillMissing.Count -ne 0) {
        throw "Android SDK Manager completed, but required components are still missing: $($stillMissing.Package -join ', ')"
    }
}

function Get-AdbArguments {
    param([string[]]$Arguments)
    if ([string]::IsNullOrWhiteSpace($Serial)) { return $Arguments }
    return @("-s", $Serial) + $Arguments
}

function Invoke-AdbChecked {
    param([string[]]$Arguments, [string]$FailureMessage = "ADB command failed")
    Invoke-Checked -FilePath $script:adb -Arguments (Get-AdbArguments $Arguments) `
        -FailureMessage $FailureMessage
}

function Select-QuestDevice {
    $discovery = Invoke-PrivateAdbCapture -Arguments @("devices", "-l") -Discovery
    $output = $discovery.Lines
    if ($discovery.ExitCode -ne 0) { throw "adb devices failed." }
    $devices = @()
    foreach ($line in $output) {
        if ($line -match '^(\S+)\s+device(?:\s|$)') { $devices += $Matches[1] }
    }
    if (-not [string]::IsNullOrWhiteSpace($Serial)) {
        if ($devices -notcontains $Serial) {
            throw "The selected device is not connected and authorized. Check the USB debugging prompt inside the headset."
        }
        return
    }
    if ($devices.Count -eq 0) {
        throw "No authorized Android device found. Connect the Quest, enable USB debugging, and accept the prompt inside the headset."
    }
    if ($devices.Count -eq 1) {
        $script:Serial = $devices[0]
        return
    }
    if ($NonInteractive) {
        throw "More than one Android device is connected. Rerun with -Serial DEVICE_SERIAL."
    }
    Write-Host "Connected devices:"
    for ($index = 0; $index -lt $devices.Count; $index++) {
        Write-Host "  $($index + 1). $(Get-PrivateDeviceLabel $devices[$index])"
    }
    $selection = Read-Host "Select the Quest device number"
    $parsed = 0
    if (-not [int]::TryParse($selection, [ref]$parsed) -or
        $parsed -lt 1 -or $parsed -gt $devices.Count) {
        throw "Invalid device selection."
    }
    $script:Serial = $devices[$parsed - 1]
}

function Assert-UpdateInstalled {
    $arguments = Get-AdbArguments @("shell", "pm", "path", "com.libertyvr.quest")
    $installedPackage = Invoke-PrivateAdb @arguments
    if ($LASTEXITCODE -ne 0 -or ($installedPackage | Out-String) -notmatch '(?m)^package:') {
        throw "Update-only mode requires Liberty City VR already installed. Use BUILD_AND_INSTALL for the first installation."
    }
}

function Resolve-GameFolder {
    param([string]$Requested, [switch]$Required)
    if ([string]::IsNullOrWhiteSpace($Requested)) {
        if ($NonInteractive) { throw "-GameDir is required unless -SkipGameData or -BuildOnly is used." }
        Write-Host ""
        Write-Host "Enter your legally owned GTA III PC installation folder." -ForegroundColor Yellow
        if ($Required) {
            Write-Host "The previous app was removed, so its Quest data may have been erased. This folder is required to restore the game data." -ForegroundColor Yellow
        } else {
            Write-Host "Press Enter to skip copying data if it is already installed on the Quest."
        }
        $Requested = Read-Host "GTA III folder"
        if ([string]::IsNullOrWhiteSpace($Requested)) {
            if ($Required) { throw "A GTA III PC folder is required after replacing an incompatible installed app." }
            return $null
        }
    }
    if (-not (Test-Path -LiteralPath $Requested -PathType Container)) {
        throw "GTA III folder does not exist: $Requested"
    }
    return (Resolve-Path -LiteralPath $Requested).Path
}

function Find-ChildDirectory {
    param([string]$Parent, [string]$Name)
    return Get-ChildItem -LiteralPath $Parent -Directory | Where-Object {
        $_.Name.Equals($Name, [StringComparison]::OrdinalIgnoreCase)
    } | Select-Object -First 1
}

try {
    $versionFile = Join-Path $repoRoot "overlay/android/app/build.gradle.kts"
    $versionMatch = [regex]::Match((Get-Content -Raw -LiteralPath $versionFile), '(?m)^\s*versionName\s*=\s*"([0-9.]+)"\s*$')
    if (-not $versionMatch.Success) { throw "Cannot read the source kit versionName." }
    Write-Host "Liberty City VR $($versionMatch.Groups[1].Value) - personal Quest build wizard" -ForegroundColor Green
    Write-Host "This repository supplies source/build tooling only; no APK or GTA data is bundled."
    if ($UpdateOnly -and (Test-Path -LiteralPath (Join-Path $repoRoot "tools/update-required-assets.txt"))) {
        throw "This release requires updated bundled assets. Run the normal BUILD_AND_INSTALL separately and follow its asset instructions; UPDATE does not copy assets."
    }

    Write-Step 1 "Preparing Git, JDK 21 and the Android SDK"
    $gitExe = Find-Git
    $gitCommandDirectory = Split-Path -Parent $gitExe
    if (($env:PATH -split ';') -notcontains $gitCommandDirectory) {
        $env:PATH = "$gitCommandDirectory;$env:PATH"
    }
    $resolvedJavaHome = Find-JavaHome
    $env:JAVA_HOME = $resolvedJavaHome
    $resolvedSdk = Find-AndroidSdk
    $env:ANDROID_HOME = $resolvedSdk
    $env:ANDROID_SDK_ROOT = $resolvedSdk
    Ensure-SdkPackages -SdkRoot $resolvedSdk
    $script:adb = Join-Path $resolvedSdk "platform-tools\adb.exe"
    Write-Host "Git: $gitExe"
    Write-Host "JDK: $resolvedJavaHome"
    Write-Host "Android SDK: $resolvedSdk"

    Write-Step 2 "Preparing the short local build directory"
    $resolvedWork = [IO.Path]::GetFullPath($WorkDir)
    New-Item -ItemType Directory -Path $resolvedWork -Force | Out-Null
    if ($resolvedWork.Length -gt 80) {
        Write-Host "Warning: '$resolvedWork' is long; C:\LCVRBuild is safer for native builds." -ForegroundColor Yellow
    }

    Write-Step 3 "Obtaining the exact tested re3 source"
    $re3Dir = Join-Path $resolvedWork "re3-public-b050e1c"
    $safeRe3Dir = $re3Dir.Replace('\', '/')
    if (-not (Test-Path -LiteralPath $re3Dir)) {
        Invoke-Checked -FilePath $gitExe -Arguments @(
            "clone", "--no-checkout", "-b", $re3Branch, $re3Url, $re3Dir
        ) -FailureMessage "re3 clone failed"
        Invoke-Checked -FilePath $gitExe -Arguments @(
            "-c", "safe.directory=$safeRe3Dir", "-C", $re3Dir, "checkout", "--detach", $testedRe3Commit
        ) -FailureMessage "Could not select the tested re3 commit"
    } else {
        if (-not (Test-Path -LiteralPath (Join-Path $re3Dir ".git"))) {
            throw "$re3Dir exists but is not the wizard's re3 checkout. Choose another -WorkDir."
        }
        $savedErrorPreference = $ErrorActionPreference
        $ErrorActionPreference = "Continue"
        try {
            $headOutput = & $gitExe -c "safe.directory=$safeRe3Dir" -C $re3Dir rev-parse HEAD 2>&1
            $headExit = $LASTEXITCODE
            $dirtyOutput = & $gitExe -c "safe.directory=$safeRe3Dir" -C $re3Dir status --porcelain 2>&1
            $dirtyExit = $LASTEXITCODE
        } finally {
            $ErrorActionPreference = $savedErrorPreference
        }
        if ($headExit -ne 0 -or $dirtyExit -ne 0) {
            throw "Could not verify the existing re3 checkout at $re3Dir. Git said: $($headOutput | Out-String) $($dirtyOutput | Out-String)"
        }
        $head = ($headOutput | Out-String).Trim()
        $dirty = ($dirtyOutput | Out-String).Trim()
        if ($head -ne $testedRe3Commit -or $dirty.Length -ne 0) {
            throw "$re3Dir is not a clean checkout of $testedRe3Commit. Preserve your work and choose another -WorkDir."
        }
        Write-Host "Reusing verified clean re3 source."
    }

    Write-Step 4 "Assembling the private Quest source tree"
    $buildName = "liberty-city-vr-build"
    $assembledDir = Join-Path $resolvedWork $buildName
    if (Test-Path -LiteralPath $assembledDir) {
        $assembledDir = Join-Path $resolvedWork ($buildName + "-" + (Get-Date -Format "yyyyMMdd-HHmmss"))
        Write-Host "Previous build preserved; using $assembledDir"
    }
    & (Join-Path $PSScriptRoot "assemble.ps1") -Re3 $re3Dir -Out $assembledDir
    if (-not (Test-Path -LiteralPath (Join-Path $assembledDir "android"))) {
        throw "Quest source assembly failed."
    }

    Write-Step 5 "Preparing verified Gradle $gradleVersion"
    $downloadsDir = Join-Path $resolvedWork ".downloads"
    $toolsDir = Join-Path $resolvedWork ".tools"
    $gradleZip = Join-Path $downloadsDir "gradle-$gradleVersion-bin.zip"
    $gradleHome = Join-Path $toolsDir "gradle-$gradleVersion"
    $gradle = Join-Path $gradleHome "bin\gradle.bat"
    New-Item -ItemType Directory -Path $downloadsDir,$toolsDir -Force | Out-Null
    if (-not (Test-Path -LiteralPath $gradle -PathType Leaf)) {
        if (-not (Test-Path -LiteralPath $gradleZip -PathType Leaf)) {
            Write-Host "Downloading Gradle $gradleVersion from services.gradle.org..."
            Invoke-WebRequest -UseBasicParsing -Uri $gradleUrl -OutFile $gradleZip
        }
        $observedHash = (Get-FileHash -Algorithm SHA256 -LiteralPath $gradleZip).Hash
        if ($observedHash -ne $gradleSha256) {
            throw "Gradle archive hash mismatch. Expected $gradleSha256, got $observedHash. Delete $gradleZip and retry."
        }
        Expand-Archive -LiteralPath $gradleZip -DestinationPath $toolsDir -Force
    }
    if (-not (Test-Path -LiteralPath $gradle -PathType Leaf)) {
        throw "Gradle extraction did not create $gradle"
    }

    $buildVariant = if ($Release) { "release" } else { "debug" }
    $buildTask = if ($Release) { ":app:assembleRelease" } else { ":app:assembleDebug" }
    Write-Step 6 "Building the personal $buildVariant-signed APK"
    Push-Location (Join-Path $assembledDir "android")
    try {
        Invoke-Checked -FilePath $gradle -Arguments @(
            $buildTask, "--no-daemon"
        ) -FailureMessage "Android/ARM64 build failed"
    } finally {
        Pop-Location
    }
    $apk = Join-Path $assembledDir "android\app\build\outputs\apk\$buildVariant\app-$buildVariant.apk"
    if (-not (Test-Path -LiteralPath $apk -PathType Leaf)) {
        throw "Build completed without the expected APK: $apk"
    }
    $apkHash = (Get-FileHash -Algorithm SHA256 -LiteralPath $apk).Hash
    Write-Host "APK: $apk" -ForegroundColor Green
    Write-Host "SHA256: $apkHash"

    if ($BuildOnly) {
        Write-Host "Build-only mode complete." -ForegroundColor Green
        Write-Host "Diagnostic log: $LogPath"
        Stop-DiagnosticLog
        return
    }

    Write-Step 7 "Installing on the connected Quest"
    Select-QuestDevice
    Write-Host "Quest: personal Quest 3 device"
    if ($UpdateOnly) { Assert-UpdateInstalled }
    $installArguments = Get-AdbArguments @("install", "-r", $apk)
    $savedErrorPreference = $ErrorActionPreference
    $ErrorActionPreference = "Continue"
    try {
        $installOutput = @(Invoke-PrivateAdb @installArguments 2>&1)
        $installExitCode = $LASTEXITCODE
    } finally {
        $ErrorActionPreference = $savedErrorPreference
    }
    $installOutput | ForEach-Object { Write-Host $_ }
    if ($installExitCode -ne 0) {
        $installText = $installOutput | Out-String
        if ($installText -match 'INSTALL_FAILED_UPDATE_INCOMPATIBLE') {
            if ($UpdateOnly) {
                throw "The installed app uses a different signing key. UPDATE left it and its data intact. Build with the same personal key/computer used for the installed version; no uninstall was attempted."
            }
            Write-Host ""
            Write-Host "The Quest already contains Liberty City VR signed with a different key." -ForegroundColor Yellow
            Write-Host "Android cannot update it in place." -ForegroundColor Yellow
            Write-Host "WARNING: uninstalling the old app can erase its saves and all GTA data stored under the app." -ForegroundColor Red
            if ($NonInteractive) {
                throw "Incompatible installed signature. Interactive confirmation is required before uninstalling com.libertyvr.quest."
            }
            $replaceAnswer = Read-Host "Uninstall the old Liberty City VR and install this build now? [y/N]"
            if ($replaceAnswer -notmatch '^[Yy]') {
                throw "The old app was left untouched. Back up anything you need, then rerun and approve replacement."
            }
            if ($SkipGameData) {
                throw "The old app was left untouched. Rerun without -SkipGameData and provide the GTA III PC folder so erased game data can be restored after replacement."
            }
            # Validate the replacement data source before performing the
            # destructive uninstall. An empty/invalid answer leaves the old
            # application and all of its data untouched.
            $script:replacementGameDir = Resolve-GameFolder -Requested $GameDir -Required
            Invoke-AdbChecked -Arguments @("uninstall", "com.libertyvr.quest") `
                -FailureMessage "Could not uninstall the incompatible Liberty City VR package"
            Invoke-AdbChecked -Arguments @("install", $apk) `
                -FailureMessage "APK installation after removing the incompatible package failed"
            $script:replacedIncompatibleInstall = $true
            Write-Host "The incompatible app was removed and the new APK was installed." -ForegroundColor Green
        } else {
            if ($UpdateOnly -and $installText -match 'INSTALL_FAILED_VERSION_DOWNGRADE') {
                throw "The Quest has a newer app. UPDATE will not downgrade it. Wait for the corresponding source release."
            }
            throw "APK installation failed (exit code $installExitCode)."
        }
    }
    if (-not $UpdateOnly) {
    $providerArguments = Get-AdbArguments @(
        "shell", "content", "query", "--uri", $saveProviderUri,
        "--projection", "_display_name:_size"
    )
    $providerOutput = Invoke-PrivateAdb @providerArguments
    if ($LASTEXITCODE -ne 0 -or ($providerOutput | Out-String) -notmatch '_display_name=GTA3sf1\.b') {
        throw "The APK installed, but the safe external-data bootstrap failed. Output: $($providerOutput | Out-String)"
    }
    Write-Host "Application storage bootstrap verified."

    Write-Step 8 "Copying the user's game data and bundled VR hands"
    if (-not $SkipGameData) {
        if ($script:replacedIncompatibleInstall) {
            $resolvedGame = $script:replacementGameDir
        } else {
            $resolvedGame = Resolve-GameFolder -Requested $GameDir
        }
        if ($null -ne $resolvedGame) {
            $required = @("data", "TEXT", "anim", "models", "movies", "Audio")
            $resolvedFolders = @{}
            foreach ($name in $required) {
                $folder = Find-ChildDirectory -Parent $resolvedGame -Name $name
                if ($null -eq $folder) {
                    throw "Required game-data folder '$name' is missing from $resolvedGame. Use a complete PC installation."
                }
                $resolvedFolders[$name] = $folder
            }
            $audioFolder = $resolvedFolders["Audio"]
            $sfxRaw = Get-ChildItem -LiteralPath $audioFolder.FullName -File | Where-Object { $_.Name.Equals("sfx.raw", [StringComparison]::OrdinalIgnoreCase) }
            $sfxSdt = Get-ChildItem -LiteralPath $audioFolder.FullName -File | Where-Object { $_.Name.Equals("sfx.sdt", [StringComparison]::OrdinalIgnoreCase) }
            if ($null -eq $sfxRaw -or $null -eq $sfxSdt) {
                throw "Required sound effect archive sfx.RAW/sfx.SDT is missing from $($audioFolder.FullName). In retail GTA III PC, sfx.RAW and sfx.SDT are installed by Disc 1 (Install CD), while radio station/dialogue audio is on Disc 2 (Play CD). Ensure both sets are merged into the Audio folder."
            }
            foreach ($optName in @("mp3", "skins", "txd")) {
                $optFolder = Find-ChildDirectory -Parent $resolvedGame -Name $optName
                if ($null -ne $optFolder) {
                    $resolvedFolders[$optName] = $optFolder
                }
            }
            foreach ($name in $resolvedFolders.Keys) {
                $folder = $resolvedFolders[$name]
                Write-Host "Copying $($folder.Name)..." -ForegroundColor Cyan
                # Pre-create all subdirectories via SaveProvider to avoid Horizon OS scoped storage mkdir denial
                Get-ChildItem -LiteralPath $folder.FullName -Directory -Recurse | ForEach-Object {
                    $rel = $_.FullName.Substring($resolvedGame.Length).TrimStart('\', '/').Replace('\', '/')
                    Invoke-PrivateAdb @(Get-AdbArguments @("shell", "content", "call", "--uri", "content://com.libertyvr.quest.saves", "--method", "mkdir", "--arg", $rel)) 2>&1 | Out-Null
                }
                Invoke-AdbChecked -Arguments @("push", $folder.FullName, $remoteGameData) `
                    -FailureMessage "Failed to copy $($folder.FullName)"
            }
            Invoke-PrivateAdb @(Get-AdbArguments @("shell", "content", "call", "--uri", "content://com.libertyvr.quest.saves", "--method", "mkdir", "--arg", "txd")) 2>&1 | Out-Null
        } else {
            Write-Host "Game-data copy skipped. The app requires existing data under $remoteGameData." -ForegroundColor Yellow
        }
    } else {
        Write-Host "Game-data copy skipped by -SkipGameData."
    }

    # re3 does not run on retail data alone: it replaces several stock assets
    # and its frontend reads strings and button icons that a 2001 installation
    # never had. Without them the OPTIONS menus print "FET_GFX missing" and the
    # like where the labels belong.
    $portAssets = @(
        @{ Folder = "TEXT"; Files = @(
            "american.gxt", "english.gxt", "french.gxt", "german.gxt",
            "italian.gxt", "JAPANESE.gxt", "polish.gxt", "russian.gxt", "spanish.gxt") },
        @{ Folder = "models"; Files = @(
            "fonts_j.txd", "fonts_p.txd", "fonts_r.txd",
            "frontend_ds3.txd", "frontend_ds4.txd", "frontend_nsw.txd", "frontend_x360.txd", "frontend_xone.txd",
            "generic.txd", "menu.txd", "nswbtns.txd", "particle.txd", "ps3btns.txd", "x360btns.txd") }
    )
    Write-Host "Copying the port's replacement text and frontend assets..." -ForegroundColor Cyan
    foreach ($asset in $portAssets) {
        $localFolder = Join-Path $assembledDir "gamefiles\$($asset.Folder)"
        $remoteFolder = "$remoteGameData/$($asset.Folder)"
        foreach ($name in $asset.Files) {
            if (-not (Test-Path -LiteralPath (Join-Path $localFolder $name) -PathType Leaf)) {
                throw "Required port asset is missing from the assembled tree: gamefiles\$($asset.Folder)\$name"
            }
        }
        Invoke-AdbChecked -Arguments @("shell", "mkdir", "-p", $remoteFolder) `
            -FailureMessage "Could not create $remoteFolder on the headset"
        foreach ($name in $asset.Files) {
            Invoke-AdbChecked -Arguments @(
                "push", (Join-Path $localFolder $name), "$remoteFolder/$name"
            ) -FailureMessage "Failed to copy port asset $($asset.Folder)/$name"
        }
    }

    $handsSource = Join-Path $assembledDir "gamefiles\models\vrhands"
    $handsRemote = "$remoteGameData/models/vrhands"
    $handFiles = @("BigHandLeft.uxrh", "BigHandRight.uxrh", "BigHandsAlbedo.png")
    foreach ($name in $handFiles) {
        if (-not (Test-Path -LiteralPath (Join-Path $handsSource $name) -PathType Leaf)) {
            throw "Bundled VR hand file is missing: $name"
        }
    }
    Invoke-AdbChecked -Arguments @("shell", "mkdir", "-p", $handsRemote) `
        -FailureMessage "Could not create the VR hand data directory"
    foreach ($name in $handFiles) {
        Invoke-AdbChecked -Arguments @(
            "push", (Join-Path $handsSource $name), "$handsRemote/$name"
        ) -FailureMessage "Failed to copy VR hand asset $name"
    }
    } else {
        Write-Step 8 "APK updated; existing game data, saves, settings and bundled assets were left unchanged"
    }
    Invoke-AdbChecked -Arguments @("shell", "am", "force-stop", "com.libertyvr.quest") `
        -FailureMessage "Could not leave the app stopped after installation"

    Write-Host ""
    Write-Host "LIBERTY CITY VR IS READY." -ForegroundColor Green
    Write-Host "The app was left stopped. Put on the headset and launch Liberty City VR."
    Write-Host "Build directory: $assembledDir"
    Write-Host "APK SHA256: $apkHash"
    Write-Host "Diagnostic log: $LogPath"
    Stop-DiagnosticLog
} catch {
    Write-Host ""
    Write-Host "ERROR: $($_.Exception.Message)" -ForegroundColor Red
    Write-Host "No failure was treated as success. Fix the reported item and rerun."
    Write-Host "Diagnostic log: $LogPath"
    Stop-DiagnosticLog
    exit 1
}

#!/usr/bin/env bash # Builds and optionally installs a personal Liberty City VR Quest APK. # No APK, re3 source, retail data, saves, or third-party model pack is # distributed by this repository. The user supplies/downloads each input. # # Linux port of build-and-install.ps1. The one-click entry point is the # top-level BUILD_AND_INSTALL.sh wrapper, which keeps the terminal open on # error and always prints the diagnostic-log path. # # Arguments (Windows-style names are accepted for familiarity): # --game-dir DIR / -GameDir DIR your legally owned GTA III PC folder # --work-dir DIR / -WorkDir DIR build scratch dir (default ~/LCVRBuild) # --android-sdk DIR / -AndroidSdk DIR Android SDK root # --java-home DIR / -JavaHome DIR JDK 21 home # --serial SERIAL / -Serial SERIAL Quest USB serial # --log-path PATH / -LogPath PATH diagnostic log location # --release / -Release release APK with configured signing key # --build-only / -BuildOnly stop after producing the APK # --update-only / -UpdateOnly update APK only; keep all app data # --skip-game-data / -SkipGameData do not copy game data # --non-interactive / -NonInteractive never prompt; fail instead # --help / -h show this help
set -uo pipefail source "$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)/device-diagnostics.sh"
# ---- defaults ------------------------------------------------------------- GAME_DIR="" WORK_DIR="${HOME}/LCVRBuild" ANDROID_SDK="" JAVA_HOME_ARG="" SERIAL="" LOG_PATH="${TMPDIR:-/tmp}/LibertyCityVR-Build-And-Install.log" BUILD_ONLY=0 SKIP_GAME_DATA=0 UPDATE_ONLY=0 RELEASE_BUILD=0 NON_INTERACTIVE=0
# ---- constants ------------------------------------------------------------ TESTED_RE3_COMMIT="b050e1cc63b1869e6b514ab2f1a00ef4969e0c84" RE3_URL="https://github.com/mrxenginner/re3.git" RE3_BRANCH="master" JDK_VERSION="21.0.11+10" JDK_URL="https://github.com/adoptium/temurin21-binaries/releases/download/jdk-21.0.11%2B10/OpenJDK21U-jdk_x64_linux_hotspot_21.0.11_10.tar.gz" # Verified against the official Adoptium download on 2026-08-23. JDK_SHA256="4B2220E232A97997B436CA6AB15CBF70171ECFF52958A46159DFA5A8C44CA4DE" ANDROID_CMDLINE_TOOLS_VERSION="15859902" ANDROID_CMDLINE_TOOLS_URL="https://dl.google.com/android/repository/commandlinetools-linux-${ANDROID_CMDLINE_TOOLS_VERSION}_latest.zip" # Verified against the official Google download on 2026-08-23. ANDROID_CMDLINE_TOOLS_SHA256="4E4C464F145A7512B57D088AC6C278C03C9EEA610886B35A5E0804E74EEDF583" GRADLE_VERSION="8.13" GRADLE_URL="https://services.gradle.org/distributions/gradle-${GRADLE_VERSION}-bin.zip" # Verified against services.gradle.org on 2026-08-23 (platform-independent). GRADLE_SHA256="20F1B1176237254A6FC204D8434196FA11A4CFB387567519C61556E8710AED78" NDK_VERSION="27.2.12479018" CMAKE_VERSION="3.22.1" REMOTE_GAME_DATA="/sdcard/Android/data/com.libertyvr.quest/files/gamedata" SAVE_PROVIDER_URI="content://com.libertyvr.quest.saves/slot/1" PACKAGE_NAME="com.libertyvr.quest"
REPO_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)" ADB="" REPLACED_INCOMPATIBLE_INSTALL=0 REPLACEMENT_GAME_DIR=""
# ---- logging -------------------------------------------------------------- LOG_DIR="$(dirname "$LOG_PATH")" mkdir -p "$LOG_DIR" 2>/dev/null || true # Mirror everything (stdout + stderr) to the diagnostic log as well as the # terminal, so a failed run always leaves a persistent artifact. exec > >(tee "$LOG_PATH") 2>&1
die() { echo "" echo "ERROR: $1" >&2 echo "No failure was treated as success. Fix the reported item and rerun." >&2 echo "Diagnostic log: $LOG_PATH" >&2 exit 1 }
# Run a command, printing its output; die with a message if it fails. checked() { local msg="$1"; shift "$@" local rc=$? if [ "$rc" -ne 0 ]; then die "$msg (exit code $rc)." fi }
# Run a command and capture its output without dying on a non-zero exit. # Sets CAPTURED_OUTPUT and CAPTURED_EXIT. capture() { CAPTURED_OUTPUT="$( "$@" 2>&1 )" CAPTURED_EXIT=$? }
step() { echo "" echo "[$1/8] $2" }
# ---- argument parsing ----------------------------------------------------- while [ $# -gt 0 ]; do case "$1" in --game-dir|-GameDir) GAME_DIR="$2"; shift 2 ;; --work-dir|-WorkDir) WORK_DIR="$2"; shift 2 ;; --android-sdk|-AndroidSdk) ANDROID_SDK="$2"; shift 2 ;; --java-home|-JavaHome) JAVA_HOME_ARG="$2"; shift 2 ;; --serial|-Serial) SERIAL="$2"; shift 2 ;; --log-path|-LogPath) LOG_PATH="$2"; shift 2 ;; --release|-Release) RELEASE_BUILD=1; shift ;; --update-only|-UpdateOnly) UPDATE_ONLY=1; SKIP_GAME_DATA=1; shift ;; --build-only|-BuildOnly) BUILD_ONLY=1; shift ;; --skip-game-data|-SkipGameData) SKIP_GAME_DATA=1; shift ;; --non-interactive|-NonInteractive) NON_INTERACTIVE=1; shift ;; --help|-h) sed -n '2,20p' "$0" | sed 's/^# \{0,1\}//' exit 0 ;; *) die "Unknown argument: $1 (see --help)" ;; esac done
if [ "$UPDATE_ONLY" -eq 1 ] && [ -e "$REPO_ROOT/tools/update-required-assets.txt" ]; then die "This source version needs updated bundled assets. Use BUILD_AND_INSTALL for that version instead of UPDATE." fi
# Re-point the log if --log-path was supplied after the initial redirect. if [ "$LOG_PATH" != "${TMPDIR:-/tmp}/LibertyCityVR-Build-And-Install.log" ]; then mkdir -p "$(dirname "$LOG_PATH")" 2>/dev/null || true exec > >(tee "$LOG_PATH") 2>&1 fi
# ---- toolchain discovery -------------------------------------------------- find_git() { local g g="$(command -v git || true)" if [ -n "$g" ]; then echo "$g" return 0 fi die "git was not found on PATH. Install it (e.g. 'sudo pacman -S git' or 'sudo apt install git') and rerun." }
# Return a JDK 21 home. Searches the supplied/env candidates, then common # Android Studio JBR locations, then downloads a pinned official Temurin JDK. find_java_home() { local candidates=() [ -n "$JAVA_HOME_ARG" ] && candidates+=("$JAVA_HOME_ARG") [ -n "${JAVA_HOME:-}" ] && candidates+=("$JAVA_HOME") candidates+=("/opt/android-studio/jbr" "${HOME}/Android/jbr" "${HOME}/.local/share/Android/jbr")
local candidate java for candidate in "${candidates[@]}"; do [ -z "$candidate" ] && continue java="$candidate/bin/java" [ -x "$java" ] || continue if "$java" -version 2>&1 | grep -Eq 'version "21(\.|")'; then echo "$(cd "$candidate" && pwd)" return 0 fi done
# No suitable local Java: fetch a pinned official Temurin JDK 21. local downloads="$WORK_DIR/.downloads" local tools="$WORK_DIR/.tools" local zip="$downloads/OpenJDK21U-jdk_x64_linux_hotspot_21.0.11_10.tar.gz" local home="$tools/jdk-$JDK_VERSION" local bin="$home/bin/java" mkdir -p "$downloads" "$tools"
if [ ! -x "$bin" ]; then if [ ! -f "$zip" ]; then echo "JDK 21 was not found; downloading official Eclipse Temurin $JDK_VERSION..." >&2 checked "Temurin JDK download failed" curl -fsSL --retry 5 --retry-all-errors -o "$zip" "$JDK_URL" fi local observed observed="$(sha256sum "$zip" | awk '{print toupper($1)}')" if [ "$observed" != "$JDK_SHA256" ]; then die "Temurin JDK archive hash mismatch. Expected $JDK_SHA256, got $observed. Delete $zip and retry." fi checked "Temurin JDK extraction failed" tar -xzf "$zip" -C "$tools" fi [ -x "$bin" ] || die "Temurin JDK extraction did not create $bin" echo "$home" }
# Ensure the Android command-line tools exist under $1/cmdline-tools/latest. ensure_android_command_line_tools() { local sdk_root="$1" local candidates=( "$sdk_root/cmdline-tools/latest/bin/sdkmanager" "$sdk_root/cmdline-tools/bin/sdkmanager" ) local c for c in "${candidates[@]}"; do [ -x "$c" ] && { echo "$c"; return 0; } done
local downloads="$WORK_DIR/.downloads" local tools="$WORK_DIR/.tools" local zip="$downloads/commandlinetools-linux-${ANDROID_CMDLINE_TOOLS_VERSION}_latest.zip" local extract_root="$tools/android-command-line-tools-${ANDROID_CMDLINE_TOOLS_VERSION}" local latest_root="$sdk_root/cmdline-tools/latest" local sdkmanager="$latest_root/bin/sdkmanager" mkdir -p "$downloads" "$tools" "$sdk_root"
if [ ! -x "$sdkmanager" ]; then if [ ! -f "$zip" ]; then echo "Android SDK command-line tools are missing; downloading them from Google..." >&2 checked "Android command-line tools download failed" curl -fsSL --retry 5 --retry-all-errors -o "$zip" "$ANDROID_CMDLINE_TOOLS_URL" fi local observed observed="$(sha256sum "$zip" | awk '{print toupper($1)}')" if [ "$observed" != "$ANDROID_CMDLINE_TOOLS_SHA256" ]; then die "Android command-line tools hash mismatch. Expected $ANDROID_CMDLINE_TOOLS_SHA256, got $observed. Delete $zip and retry." fi checked "Android command-line tools extraction failed" unzip -q -o "$zip" -d "$extract_root" local extracted_tools="$extract_root/cmdline-tools" [ -f "$extracted_tools/bin/sdkmanager" ] || die "Android command-line tools archive has an unexpected layout." mkdir -p "$latest_root" cp -rf "$extracted_tools/." "$latest_root/" fi [ -x "$sdkmanager" ] || die "Android SDK bootstrap did not create $sdkmanager" echo "$sdkmanager" }
# Return an Android SDK root. Searches candidates, then bootstraps a private # one under $WORK_DIR/.android-sdk. find_android_sdk() { local candidates=() [ -n "$ANDROID_SDK" ] && candidates+=("$ANDROID_SDK") [ -n "${ANDROID_HOME:-}" ] && candidates+=("$ANDROID_HOME") [ -n "${ANDROID_SDK_ROOT:-}" ] && candidates+=("$ANDROID_SDK_ROOT") candidates+=("${HOME}/Android/Sdk" "${HOME}/.android/sdk")
local candidate for candidate in "${candidates[@]}"; do [ -z "$candidate" ] && continue if [ -f "$candidate/platform-tools/adb" ] || \ [ -f "$candidate/cmdline-tools/latest/bin/sdkmanager" ] || \ [ -f "$candidate/cmdline-tools/bin/sdkmanager" ]; then echo "$(cd "$candidate" && pwd)" return 0 fi done
local sdk_root="$WORK_DIR/.android-sdk" mkdir -p "$sdk_root" ensure_android_command_line_tools "$sdk_root" >/dev/null echo "$sdk_root" }
# Print the sdkmanager packages that are still missing (one per line). get_missing_sdk_packages() { local sdk_root="$1" [ -f "$sdk_root/platforms/android-35/android.jar" ] || echo "platforms;android-35" [ -d "$sdk_root/build-tools/34.0.0" ] || echo "build-tools;34.0.0" [ -f "$sdk_root/platform-tools/adb" ] || echo "platform-tools" # The file each component is known by, not the folder: a download that # stopped part way leaves the folder behind, and a folder test then # reports it present and skips the repair. [ -f "$sdk_root/ndk/$NDK_VERSION/source.properties" ] || echo "ndk;$NDK_VERSION" [ -f "$sdk_root/cmake/$CMAKE_VERSION/bin/cmake" ] || echo "cmake;$CMAKE_VERSION" }
ensure_sdk_packages() { local sdk_root="$1" local missing missing="$(get_missing_sdk_packages "$sdk_root")" [ -z "$missing" ] && return 0
echo "Missing Android SDK components:" echo "$missing" | sed 's/^/ /' local sdkmanager sdkmanager="$(ensure_android_command_line_tools "$sdk_root")" || die "Android command-line tools bootstrap failed; stopping." if [ "$NON_INTERACTIVE" -eq 1 ]; then die "Required Android SDK components are missing; automatic installation needs an interactive license confirmation." fi local answer read -r -p "Install the missing SDK components now? You may need to accept Google licenses [Y/n] " answer case "$answer" in [Yy]*|'') ;; *) die "Required SDK components were not installed." ;; esac yes | "$sdkmanager" --sdk_root="$sdk_root" --licenses local license_rc=${PIPESTATUS[1]} [ "$license_rc" -eq 0 ] || die "Android SDK license step failed (exit code $license_rc)." # shellcheck disable=SC2086 checked "Android SDK component installation failed" "$sdkmanager" --sdk_root="$sdk_root" $missing local still still="$(get_missing_sdk_packages "$sdk_root")" if [ -n "$still" ]; then die "Android SDK Manager completed, but required components are still missing: $(echo "$still" | tr '\n' ', ')" fi }
# Prepend -s SERIAL to adb arguments when a serial is pinned. adb_args() { local out=() if [ -n "$SERIAL" ]; then out+=("-s" "$SERIAL"); fi out+=("$@") printf '%s\n' "${out[@]}" }
# Run adb with a failure message; die on non-zero. adb_checked() { local msg="${2:-ADB command failed}" local args=() if [ -n "$SERIAL" ]; then args+=("-s" "$SERIAL"); fi args+=("$1") "${args[@]}" local rc=$? [ "$rc" -eq 0 ] || die "$msg (exit code $rc)." }
select_quest_device() { local output private_adb_discover [ "$CAPTURED_EXIT" -eq 0 ] || die "adb devices failed." local devices=() local line while IFS= read -r line; do if [[ "$line" =~ ^([A-Za-z0-9._-]+)[[:space:]]+device([[:space:]]|$) ]]; then devices+=("${BASH_REMATCH[1]}") fi done <<< "$CAPTURED_OUTPUT"
if [ -n "$SERIAL" ]; then local d for d in "${devices[@]}"; do [ "$d" = "$SERIAL" ] && return 0; done die "The selected device is not connected and authorized. Check the USB debugging prompt inside the headset." fi if [ "${#devices[@]}" -eq 0 ]; then die "No authorized Android device found. Connect the Quest, enable USB debugging, and accept the prompt inside the headset." fi if [ "${#devices[@]}" -eq 1 ]; then SERIAL="${devices[0]}" return 0 fi if [ "$NON_INTERACTIVE" -eq 1 ]; then die "More than one Android device is connected. Rerun with --serial DEVICE_SERIAL." fi echo "Connected devices:" local i for i in "${!devices[@]}"; do echo " $((i + 1)). $(private_device_label "${devices[$i]}")" done local selection read -r -p "Select the Quest device number " selection [[ "$selection" =~ ^[0-9]+$ ]] || die "Invalid device selection." local idx=$((selection - 1)) if [ "$idx" -lt 0 ] || [ "$idx" -ge "${#devices[@]}" ]; then die "Invalid device selection." fi SERIAL="${devices[$idx]}" }
resolve_game_folder() { local requested="${1:-}" local required="${2:-0}" if [ -z "$requested" ]; then if [ "$NON_INTERACTIVE" -eq 1 ]; then die "--game-dir is required unless --skip-game-data or --build-only is used." fi # User-facing prompts go to stderr: this function's stdout is captured as # its return value (the resolved path), so informational text must not # pollute it. (PowerShell equivalent: Write-Host, which bypasses the # output stream and only writes to the console.) echo "" >&2 echo "Enter your legally owned GTA III PC installation folder." >&2 if [ "$required" -eq 1 ]; then echo "The previous app was removed, so its Quest data may have been erased. This folder is required to restore the game data." >&2 else echo "Press Enter to skip copying data if it is already installed on the Quest." >&2 fi read -r -p "GTA III folder " requested if [ -z "$requested" ]; then if [ "$required" -eq 1 ]; then die "A GTA III PC folder is required after replacing an incompatible installed app." fi return 0 fi fi [ -d "$requested" ] || die "GTA III folder does not exist: $requested" (cd "$requested" && pwd) }
# Find a case-insensitive child directory of $1 named $2; print its path. find_child_directory() { local parent="$1" name="$2" local entry for entry in "$parent"/*/; do [ -d "$entry" ] || continue local base base="$(basename "$entry")" if [ "${base,,}" = "${name,,}" ]; then echo "$entry" return 0 fi done return 1 }
require_installed_for_update() { local installed installed="$(private_adb -s "$SERIAL" shell pm path "$PACKAGE_NAME" 2>&1)" [ "$?" -eq 0 ] && printf '%s\n' "$installed" | grep -q '^package:' || die "UPDATE requires an existing Liberty City VR installation. Use BUILD_AND_INSTALL for the first install." }
# ---- main ----------------------------------------------------------------- KIT_VERSION="$(sed -nE 's/^[[:space:]]*versionName[[:space:]]*=[[:space:]]*"([^"]+)"[[:space:]]*$/\1/p' "$REPO_ROOT/overlay/android/app/build.gradle.kts")" [ -n "$KIT_VERSION" ] || die "Cannot read the source kit version." echo "Liberty City VR $KIT_VERSION - personal Quest build wizard" echo "This repository supplies source/build tooling only; no APK or GTA data is bundled."
step 1 "Preparing Git, JDK 21 and the Android SDK" GIT_EXE="$(find_git)" || die "Git discovery failed; stopping." RESOLVED_JAVA_HOME="$(find_java_home)" || die "JDK discovery or bootstrap failed; stopping." export JAVA_HOME="$RESOLVED_JAVA_HOME" RESOLVED_SDK="$(find_android_sdk)" || die "Android SDK discovery or bootstrap failed; stopping." export ANDROID_HOME="$RESOLVED_SDK" export ANDROID_SDK_ROOT="$RESOLVED_SDK" ensure_sdk_packages "$RESOLVED_SDK" ADB="$RESOLVED_SDK/platform-tools/adb" echo "Git: $GIT_EXE" echo "JDK: $RESOLVED_JAVA_HOME" echo "Android SDK: $RESOLVED_SDK" if [ "$UPDATE_ONLY" -eq 1 ] && [ "$BUILD_ONLY" -eq 0 ]; then select_quest_device require_installed_for_update fi
step 2 "Preparing the short local build directory" RESOLVED_WORK="$(realpath -m -- "$WORK_DIR" 2>/dev/null || printf '%s' "$WORK_DIR")" mkdir -p "$WORK_DIR" RESOLVED_WORK="$(cd "$WORK_DIR" && pwd)" if [ "${#RESOLVED_WORK}" -gt 80 ]; then echo "Warning: '$RESOLVED_WORK' is long; a short path is safer for native builds." fi
step 3 "Obtaining the exact tested re3 source" RE3_DIR="$RESOLVED_WORK/re3-public-b050e1c" if [ ! -d "$RE3_DIR" ]; then checked "re3 clone failed" "$GIT_EXE" clone --no-checkout -b "$RE3_BRANCH" "$RE3_URL" "$RE3_DIR" checked "Could not select the tested re3 commit" "$GIT_EXE" -c "safe.directory=$RE3_DIR" -C "$RE3_DIR" checkout --detach "$TESTED_RE3_COMMIT" else [ -d "$RE3_DIR/.git" ] || die "$RE3_DIR exists but is not the wizard's re3 checkout. Choose another --work-dir." local_head="$("$GIT_EXE" -c "safe.directory=$RE3_DIR" -C "$RE3_DIR" rev-parse HEAD 2>&1)" local_dirty="$("$GIT_EXE" -c "safe.directory=$RE3_DIR" -C "$RE3_DIR" status --porcelain 2>&1)" head_trim="$(echo "$local_head" | tr -d '[:space:]')" if [ "$head_trim" != "$TESTED_RE3_COMMIT" ] || [ -n "$local_dirty" ]; then die "$RE3_DIR is not a clean checkout of $TESTED_RE3_COMMIT. Preserve your work and choose another --work-dir." fi echo "Reusing verified clean re3 source." fi
step 4 "Assembling the private Quest source tree" BUILD_NAME="liberty-city-vr-build" ASSEMBLED_DIR="$RESOLVED_WORK/$BUILD_NAME" if [ -e "$ASSEMBLED_DIR" ]; then ASSEMBLED_DIR="$RESOLVED_WORK/${BUILD_NAME}-$(date +%Y%m%d-%H%M%S)" echo "Previous build preserved; using $ASSEMBLED_DIR" fi checked "Quest source assembly failed" bash "$REPO_ROOT/tools/assemble.sh" "$RE3_DIR" "$ASSEMBLED_DIR" [ -d "$ASSEMBLED_DIR/android" ] || die "Quest source assembly failed."
step 5 "Preparing verified Gradle $GRADLE_VERSION" DOWNLOADS_DIR="$RESOLVED_WORK/.downloads" TOOLS_DIR="$RESOLVED_WORK/.tools" GRADLE_ZIP="$DOWNLOADS_DIR/gradle-${GRADLE_VERSION}-bin.zip" GRADLE_HOME="$TOOLS_DIR/gradle-${GRADLE_VERSION}" GRADLE_BIN="$GRADLE_HOME/bin/gradle" mkdir -p "$DOWNLOADS_DIR" "$TOOLS_DIR" if [ ! -x "$GRADLE_BIN" ]; then if [ ! -f "$GRADLE_ZIP" ]; then echo "Downloading Gradle $GRADLE_VERSION from services.gradle.org..." checked "Gradle download failed" curl -fsSL --retry 5 --retry-all-errors -o "$GRADLE_ZIP" "$GRADLE_URL" fi observed="$(sha256sum "$GRADLE_ZIP" | awk '{print toupper($1)}')" if [ "$observed" != "$GRADLE_SHA256" ]; then die "Gradle archive hash mismatch. Expected $GRADLE_SHA256, got $observed. Delete $GRADLE_ZIP and retry." fi checked "Gradle extraction failed" unzip -q -o "$GRADLE_ZIP" -d "$TOOLS_DIR" fi [ -x "$GRADLE_BIN" ] || die "Gradle extraction did not create $GRADLE_BIN"
BUILD_VARIANT="debug" GRADLE_TASK="assembleDebug" if [ "$RELEASE_BUILD" -eq 1 ]; then BUILD_VARIANT="release" GRADLE_TASK="assembleRelease" fi step 6 "Building the personal $BUILD_VARIANT APK" ( cd "$ASSEMBLED_DIR/android" "$GRADLE_BIN" ":app:$GRADLE_TASK" -PlibertyvrDevTools=false --no-daemon ) rc=$? [ "$rc" -eq 0 ] || die "Android/ARM64 build failed (exit code $rc)." APK="$ASSEMBLED_DIR/android/app/build/outputs/apk/$BUILD_VARIANT/app-$BUILD_VARIANT.apk" [ -f "$APK" ] || die "Build completed without the expected APK: $APK" APK_HASH="$(sha256sum "$APK" | awk '{print toupper($1)}')" echo "APK: $APK" echo "SHA256: $APK_HASH"
if [ "$BUILD_ONLY" -eq 1 ]; then echo "Build-only mode complete." echo "Diagnostic log: $LOG_PATH" exit 0 fi
step 7 "Installing on the connected Quest" select_quest_device echo "Quest: personal Quest 3 device" if [ "$UPDATE_ONLY" -eq 1 ]; then require_installed_for_update; fi # Build the full adb argv (with -s SERIAL when pinned) and run it, capturing # output because a failed install must be inspected, not treated as fatal # before the incompatible-signature handling below. adb_argv=(private_adb) if [ -n "$SERIAL" ]; then adb_argv+=("-s" "$SERIAL"); fi adb_argv+=("install" "-r" "$APK") install_output="$("${adb_argv[@]}" 2>&1)" install_rc=$? echo "$install_output" if [ "$install_rc" -ne 0 ]; then if [ "$UPDATE_ONLY" -eq 1 ]; then die "APK update failed. The existing app and its data were kept; use the same signing key and a non-older version. No uninstall was attempted." fi if echo "$install_output" | grep -q 'INSTALL_FAILED_UPDATE_INCOMPATIBLE'; then echo "" echo "The Quest already contains Liberty City VR signed with a different key." echo "Android cannot update it in place." echo "WARNING: uninstalling the old app can erase its saves and all GTA data stored under the app." if [ "$NON_INTERACTIVE" -eq 1 ]; then die "Incompatible installed signature. Interactive confirmation is required before uninstalling $PACKAGE_NAME." fi read -r -p "Uninstall the old Liberty City VR and install this build now? [y/N] " replace_answer case "$replace_answer" in [Yy]*) ;; *) die "The old app was left untouched. Back up anything you need, then rerun and approve replacement." ;; esac if [ "$SKIP_GAME_DATA" -eq 1 ]; then die "The old app was left untouched. Rerun without --skip-game-data and provide the GTA III PC folder so erased game data can be restored after replacement." fi REPLACEMENT_GAME_DIR="$(resolve_game_folder "$GAME_DIR" 1)" [ -n "$REPLACEMENT_GAME_DIR" ] || die "A GTA III PC folder is required to restore game data after replacement." adb_checked "uninstall" "Could not uninstall the incompatible Liberty City VR package" adb_checked "install" "APK installation after removing the incompatible package failed" REPLACED_INCOMPATIBLE_INSTALL=1 echo "The incompatible app was removed and the new APK was installed." else die "APK installation failed (exit code $install_rc)." fi fi if [ "$UPDATE_ONLY" -eq 1 ]; then echo "APK updated. Saves, settings, GTA data and bundled assets were left unchanged." echo "The game was not launched." echo "Diagnostic log: $LOG_PATH" exit 0 fi # Run the save-provider bootstrap query with the same device prefix. provider_argv=(private_adb) if [ -n "$SERIAL" ]; then provider_argv+=("-s" "$SERIAL"); fi provider_argv+=("shell" "content" "query" "--uri" "$SAVE_PROVIDER_URI" "--projection" "_display_name:_size") provider_output="$("${provider_argv[@]}" 2>&1)" provider_rc=$? if [ "$provider_rc" -ne 0 ] || ! echo "$provider_output" | grep -q '_display_name=GTA3sf1\.b'; then die "The APK installed, but the safe external-data bootstrap failed. Output: $provider_output" fi echo "Application storage bootstrap verified."
step 8 "Copying the user's game data and bundled VR hands" if [ "$SKIP_GAME_DATA" -eq 0 ]; then if [ "$REPLACED_INCOMPATIBLE_INSTALL" -eq 1 ]; then RESOLVED_GAME="$REPLACEMENT_GAME_DIR" else RESOLVED_GAME="$(resolve_game_folder "$GAME_DIR")" fi if [ -n "$RESOLVED_GAME" ]; then required_folders=(data TEXT anim models movies Audio) declare -A resolved_folders for name in "${required_folders[@]}"; do folder="$(find_child_directory "$RESOLVED_GAME" "$name")" || die "Required game-data folder '$name' is missing from $RESOLVED_GAME. Use a complete PC installation." resolved_folders[$name]="${folder%/}" done audio_folder="${resolved_folders[Audio]}" sfx_raw="$(find "$audio_folder" -maxdepth 1 -iname "sfx.raw" -print -quit 2>/dev/null)" sfx_sdt="$(find "$audio_folder" -maxdepth 1 -iname "sfx.sdt" -print -quit 2>/dev/null)" if [ -z "$sfx_raw" ] || [ -z "$sfx_sdt" ]; then die "Required sound effect archive sfx.RAW/sfx.SDT is missing from $audio_folder. In retail GTA III PC, sfx.RAW and sfx.SDT are installed by Disc 1 (Install CD), while radio station/dialogue audio is on Disc 2 (Play CD). Ensure both sets are merged into the Audio folder." fi for opt_name in mp3 skins txd; do if opt_folder="$(find_child_directory "$RESOLVED_GAME" "$opt_name")"; then resolved_folders[$opt_name]="${opt_folder%/}" fi done for name in "${!resolved_folders[@]}"; do folder="${resolved_folders[$name]}" echo "Copying $(basename "$folder")..." # Pre-create all subdirectories via SaveProvider to avoid Horizon OS scoped storage mkdir denial find "$folder" -type d | while read -r subdir; do rel="${subdir#"${RESOLVED_GAME%/}/"}" if [ -n "$SERIAL" ]; then private_adb -s "$SERIAL" shell content call --uri content://com.libertyvr.quest.saves --method mkdir --arg "$rel" >/dev/null 2>&1 || true else private_adb shell content call --uri content://com.libertyvr.quest.saves --method mkdir --arg "$rel" >/dev/null 2>&1 || true fi done if [ -n "$SERIAL" ]; then private_adb -s "$SERIAL" push "$folder" "$REMOTE_GAME_DATA" || die "Failed to copy $folder" else private_adb push "$folder" "$REMOTE_GAME_DATA" || die "Failed to copy $folder" fi done if [ -n "$SERIAL" ]; then private_adb -s "$SERIAL" shell content call --uri content://com.libertyvr.quest.saves --method mkdir --arg txd >/dev/null 2>&1 || true else private_adb shell content call --uri content://com.libertyvr.quest.saves --method mkdir --arg txd >/dev/null 2>&1 || true fi else echo "Game-data copy skipped. The app requires existing data under $REMOTE_GAME_DATA." fi else echo "Game-data copy skipped by --skip-game-data." fi
# re3 does not run on retail data alone: it replaces several stock assets and # its frontend reads strings and button icons that a 2001 installation never # had. Without them the OPTIONS menus print "FET_GFX missing" and the like where # the labels belong. port_text_files=(american.gxt english.gxt french.gxt german.gxt italian.gxt JAPANESE.gxt polish.gxt russian.gxt spanish.gxt) port_model_files=(fonts_j.txd fonts_p.txd fonts_r.txd frontend_ds3.txd frontend_ds4.txd frontend_nsw.txd frontend_x360.txd frontend_xone.txd generic.txd menu.txd nswbtns.txd particle.txd ps3btns.txd x360btns.txd) echo "Copying the port's replacement text and frontend assets..." for name in "${port_text_files[@]}"; do [ -f "$ASSEMBLED_DIR/gamefiles/TEXT/$name" ] || die "Required port asset is missing from the assembled tree: gamefiles/TEXT/$name" done for name in "${port_model_files[@]}"; do [ -f "$ASSEMBLED_DIR/gamefiles/models/$name" ] || die "Required port asset is missing from the assembled tree: gamefiles/models/$name" done if [ -n "$SERIAL" ]; then private_adb -s "$SERIAL" shell mkdir -p "$REMOTE_GAME_DATA/TEXT" private_adb -s "$SERIAL" shell mkdir -p "$REMOTE_GAME_DATA/models" else private_adb shell mkdir -p "$REMOTE_GAME_DATA/TEXT" private_adb shell mkdir -p "$REMOTE_GAME_DATA/models" fi [ $? -eq 0 ] || die "Could not create the port asset directories on the headset" for name in "${port_text_files[@]}"; do if [ -n "$SERIAL" ]; then private_adb -s "$SERIAL" push "$ASSEMBLED_DIR/gamefiles/TEXT/$name" "$REMOTE_GAME_DATA/TEXT/$name"; else private_adb push "$ASSEMBLED_DIR/gamefiles/TEXT/$name" "$REMOTE_GAME_DATA/TEXT/$name"; fi [ $? -eq 0 ] || die "Failed to copy port asset TEXT/$name" done for name in "${port_model_files[@]}"; do if [ -n "$SERIAL" ]; then private_adb -s "$SERIAL" push "$ASSEMBLED_DIR/gamefiles/models/$name" "$REMOTE_GAME_DATA/models/$name"; else private_adb push "$ASSEMBLED_DIR/gamefiles/models/$name" "$REMOTE_GAME_DATA/models/$name"; fi [ $? -eq 0 ] || die "Failed to copy port asset models/$name" done
hands_source="$ASSEMBLED_DIR/gamefiles/models/vrhands" hands_remote="$REMOTE_GAME_DATA/models/vrhands" hand_files=(BigHandLeft.uxrh BigHandRight.uxrh BigHandsAlbedo.png) for name in "${hand_files[@]}"; do [ -f "$hands_source/$name" ] || die "Bundled VR hand file is missing: $name" done if [ -n "$SERIAL" ]; then private_adb -s "$SERIAL" shell mkdir -p "$hands_remote" else private_adb shell mkdir -p "$hands_remote" fi [ $? -eq 0 ] || die "Could not create the VR hand data directory" for name in "${hand_files[@]}"; do if [ -n "$SERIAL" ]; then private_adb -s "$SERIAL" push "$hands_source/$name" "$hands_remote/$name"; else private_adb push "$hands_source/$name" "$hands_remote/$name"; fi [ $? -eq 0 ] || die "Failed to copy VR hand asset $name" done if [ -n "$SERIAL" ]; then private_adb -s "$SERIAL" shell am force-stop "$PACKAGE_NAME" else private_adb shell am force-stop "$PACKAGE_NAME" fi [ $? -eq 0 ] || die "Could not leave the app stopped after installation"
echo "" echo "LIBERTY CITY VR IS READY." echo "The app was left stopped. Put on the headset and launch Liberty City VR." echo "Build directory: $ASSEMBLED_DIR" echo "APK SHA256: $APK_HASH" echo "Diagnostic log: $LOG_PATH" exit 0

# Dot-source before starting diagnostics. Never use Start-Transcript here: its
# Windows PowerShell header includes the process command line (and -Serial).
$script:diagnosticLogEnabled = $false
$script:privateDeviceIds = @()
$script:privateDeviceLabels = @{}

function Get-PrivateDeviceLabel {
    param([string]$Id)
    if ($script:privateDeviceLabels.ContainsKey($Id)) { return Protect-DeviceDiagnostic $script:privateDeviceLabels[$Id] }
    return 'Android device'
}

function Protect-DeviceDiagnostic {
    param([AllowEmptyString()][string]$Text)
    $ids = @(@($script:privateDeviceIds) + @($Serial) | Sort-Object { $_.Length } -Descending)
    foreach ($id in $ids) {
        if (-not [string]::IsNullOrWhiteSpace($id)) {
            $Text = $Text.Replace($id, 'personal Quest 3 device')
        }
    }
    return $Text
}

function Initialize-PrivateDiagnosticLog {
    [IO.File]::WriteAllText($LogPath, "Liberty City VR diagnostic log`r`n", [Text.UTF8Encoding]::new($false))
    $script:diagnosticLogEnabled = $true
}

# Installer status messages go to the console and log only after redaction.
# Native ADB output must be captured through Invoke-PrivateAdb first.
function Write-Host {
    param([object]$Object = '', [ConsoleColor]$ForegroundColor)
    $safe = Protect-DeviceDiagnostic ([string]$Object)
    if ($script:diagnosticLogEnabled) {
        try { [IO.File]::AppendAllText($LogPath, $safe + [Environment]::NewLine) }
        catch {
            $script:diagnosticLogEnabled = $false
            Microsoft.PowerShell.Utility\Write-Host 'Warning: diagnostic logging stopped because the log could not be written.'
        }
    }
    if ($PSBoundParameters.ContainsKey('ForegroundColor')) {
        Microsoft.PowerShell.Utility\Write-Host $safe -ForegroundColor $ForegroundColor
    } else {
        Microsoft.PowerShell.Utility\Write-Host $safe
    }
}

function Invoke-PrivateAdbCapture {
    param([string[]]$Arguments, [switch]$Discovery)
    $savedPreference = $ErrorActionPreference
    $ErrorActionPreference = 'Continue'
    # A failed process launch need not update LASTEXITCODE in Windows PowerShell.
    $global:LASTEXITCODE = 1
    try {
        $lines = @(& $script:adb @Arguments 2>&1 | ForEach-Object { $_.ToString() })
        $code = $LASTEXITCODE
    } catch {
        # Invocation errors can embed the full command and its private arguments.
        $lines = @('ADB could not be started. Check the platform-tools installation.')
        $code = 1
    } finally { $ErrorActionPreference = $savedPreference }
    if ($Discovery) {
        foreach ($line in $lines) {
            if ($line -match '^(\S+)\s+(?:device|offline|unauthorized|recovery|sideload)\b') {
                $script:privateDeviceIds += $Matches[1]
                $id = $Matches[1]
                if ($line -match 'model:(\S+)') {
                    $script:privateDeviceLabels[$id] = $Matches[1].Replace('_', ' ')
                }
            }
        }
        # Discovery is raw local data for selection, never diagnostic output.
        return [pscustomobject]@{ ExitCode = $code; Lines = $lines }
    }
    return [pscustomobject]@{
        ExitCode = $code
        Lines = @($lines | ForEach-Object { Protect-DeviceDiagnostic $_ })
    }
}

function Invoke-PrivateAdb {
    $result = Invoke-PrivateAdbCapture -Arguments @($args | ForEach-Object { $_ })
    $global:LASTEXITCODE = $result.ExitCode
    $result.Lines
}

# Source from installers. Raw discovery is captured locally; all other ADB # output is redacted before it reaches the terminal, tee, or a failure message. PRIVATE_DEVICE_IDS=() protect_device_diagnostic() { local text="$1" id i j swap local ids=("${PRIVATE_DEVICE_IDS[@]}" "${SERIAL:-}") # Replace longer IDs first so an overlapping shorter ID cannot leave a suffix. for ((i=0; i<${#ids[@]}; i++)); do for ((j=i+1; j<${#ids[@]}; j++)); do if [ "${#ids[j]}" -gt "${#ids[i]}" ]; then swap="${ids[i]}"; ids[i]="${ids[j]}"; ids[j]="$swap" fi done done for id in "${ids[@]}"; do [ -n "$id" ] || continue # Quoted pattern expansion treats punctuation in a supplied ID literally. text="${text//"$id"/personal Quest 3 device}" done printf '%s\n' "$text" }
private_device_label() { local line model='Android device' while IFS= read -r line; do if [[ "$line" == "$1 "* || "$line" == "$1"$'\t'* ]]; then if [[ "$line" =~ model:([^[:space:]]+) ]]; then model="${BASH_REMATCH[1]//_/ }"; fi fi done <<< "${CAPTURED_OUTPUT:-}" protect_device_diagnostic "$model" }
private_adb() { local output rc output="$("$ADB" "$@" 2>&1)" rc=$? protect_device_diagnostic "$output" return "$rc" }
private_adb_discover() { # Must be called in the parent shell so the redaction list survives. CAPTURED_OUTPUT="$("$ADB" devices -l 2>&1)" CAPTURED_EXIT=$? local line while IFS= read -r line; do if [[ "$line" =~ ^([^[:space:]]+)[[:space:]]+(device|offline|unauthorized|recovery|sideload)([[:space:]]|$) ]]; then PRIVATE_DEVICE_IDS+=("${BASH_REMATCH[1]}") fi done <<< "$CAPTURED_OUTPUT" }

#!/usr/bin/env python3
"""Copy app-owned RenderDoc captures locally without exposing device identifiers."""
import argparse
import hashlib
from pathlib import Path
import re
import shutil
import subprocess
import sys

NAME = re.compile(r"[0-9]{8}T[0-9]{6}Z-[0-9]+(?:_[A-Za-z0-9-]+)*\.rdc\Z")
BASE = "content://com.libertyvr.quest.performance/"


def run(adb, args, timeout=30):
    result = subprocess.run([str(adb), *args], stdout=subprocess.PIPE,
                            stderr=subprocess.PIPE, timeout=timeout)
    if result.returncode:
        raise RuntimeError("ADB operation failed; private diagnostics suppressed.")
    return result.stdout


def find_device(adb):
    eligible = []
    for line in run(adb, ["devices", "-l"]).decode(errors="replace").splitlines():
        fields = line.split()
        if len(fields) > 1 and fields[1] == "device":
            try:
                model = run(adb, ["-s", fields[0], "shell", "getprop", "ro.product.model"])
            except RuntimeError:
                continue
            if model.strip() == b"Quest 3":
                eligible.append(fields[0])
    if len(eligible) != 1:
        raise RuntimeError("Connect exactly one authorized, responsive personal Quest 3 device.")
    return eligible[0]  # Local selection only; never printed or persisted.


def listing(data):
    entries = {}
    for line in data.decode(errors="replace").splitlines():
        name = re.search(r"_display_name=([^,]+)", line)
        size = re.search(r"_size=([0-9]+)", line)
        if name and size and NAME.fullmatch(name[1]) and len(name[1]) <= 192:
            entries[name[1]] = int(size[1])
    return entries


def save(output, name, expected_size, data):
    if not NAME.fullmatch(name) or len(name) > 192:
        raise ValueError("Invalid capture name.")
    if expected_size < 16 or len(data) != expected_size or data[:4] != b"RDOC":
        raise ValueError("Incomplete or invalid transfer; no destination file was written.")
    digest = hashlib.sha256(data).hexdigest()
    output = Path(output)
    output.mkdir(parents=True, exist_ok=True)
    target = output / name
    if target.exists():
        if hashlib.sha256(target.read_bytes()).hexdigest() != digest:
            raise ValueError("Destination already exists with different contents; left unchanged.")
    else:
        # Exclusive creation never replaces an existing capture or placeholder.
        with target.open("xb") as stream:
            stream.write(data)
    return target, digest


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--adb", type=Path, help="Path to adb if not on PATH")
    parser.add_argument("--output", required=True, type=Path, help="Local output directory")
    parser.add_argument("--latest", type=int, default=1, help="Number of newest captures (default 1)")
    parser.add_argument("--name", help="Export one exact listed capture instead")
    args = parser.parse_args()
    if args.latest < 1 or (args.name and not NAME.fullmatch(args.name)):
        parser.error("Use a positive capture count and a valid capture filename.")
    adb = args.adb or shutil.which("adb")
    if not adb:
        parser.error("ADB unavailable; provide --adb.")
    try:
        device = find_device(adb)
        entries = listing(run(adb, ["-s", device, "shell", "content", "query", "--uri", BASE+"renderdocs"]))
        names = [args.name] if args.name else sorted(entries, reverse=True)[:args.latest]
        if not names or any(name not in entries for name in names):
            raise RuntimeError("No matching capture listed; install the capture-export update and retry.")
        for name in names:
            data = run(adb, ["-s", device, "exec-out", "content", "read", "--uri", BASE+"renderdoc/"+name], 120)
            path, digest = save(args.output, name, entries[name], data)
            print(f"Saved {path.name}: {len(data)} bytes; RDOC signature and size verified; SHA256 {digest}")
        return 0
    except (RuntimeError, ValueError) as error:
        print(str(error), file=sys.stderr)
    except (OSError, subprocess.SubprocessError):
        print("Export failed; private device identifiers and raw diagnostics suppressed.", file=sys.stderr)
    return 1


if __name__ == "__main__":
    sys.exit(main())

#!/usr/bin/env python3
"""Local-only Quest music transfer. Requires Python 3, ADB and ffprobe.

No transcoding, deletion, overwrite or game-data transfer. Uses the release
APK's restricted provider, atomic commits and SHA-256 transfer verification.
"""
import argparse
import hashlib
import json
import os
import pathlib
import re
import shlex
import shutil
import subprocess
import sys
import unicodedata
import uuid

CODECS = {'.mp3': {'mp3'}, '.m4a': {'aac'}, '.ogg': {'vorbis', 'opus'}, '.opus': {'opus'}, '.flac': {'flac'}, '.wav': {'pcm_s16le'}}
EXTENSIONS = set(CODECS)
MAX_BYTES = 512 * 1024 * 1024
MAX_DURATION = 24 * 24 * 60 * 60 * 1000
RESERVE = 1024 * 1024 * 1024
URI = 'content://com.libertyvr.quest.music'


def run(args, **kwargs):
    try:
        return subprocess.run(args, check=True, **kwargs)
    except FileNotFoundError as error:
        raise RuntimeError(f'Cannot launch {args[0]!r}: executable not found') from error


def find_adb(requested=None):
    """Prefer an explicit override/PATH, then SDKs used by the local builder."""
    if requested:
        found = shutil.which(requested)
        if found:
            return found
        raise RuntimeError(f'ADB not found at {requested!r}. Check --adb and supply the full path to adb.')
    found = shutil.which('adb')
    if found:
        return found
    roots = [pathlib.Path(os.environ[key]) for key in ('ANDROID_HOME', 'ANDROID_SDK_ROOT') if os.environ.get(key)]
    if sys.platform == 'win32':
        if os.environ.get('LOCALAPPDATA'):
            roots.append(pathlib.Path(os.environ['LOCALAPPDATA']) / 'Android' / 'Sdk')
        roots.append(pathlib.Path('C:/LCVRBuild/.android-sdk'))
    executable = 'adb.exe' if sys.platform == 'win32' else 'adb'
    for root in roots:
        candidate = root / 'platform-tools' / executable
        if candidate.is_file():
            return str(candidate.resolve())
    raise RuntimeError('ADB was not found. Install Android Platform Tools, set ANDROID_HOME/ANDROID_SDK_ROOT, '
                       'or pass --adb "FULL_PATH_TO_ADB" (for example C:\\LCVRBuild\\.android-sdk\\platform-tools\\adb.exe).')


def digest(path):
    h = hashlib.sha256()
    with path.open('rb') as source:
        for block in iter(lambda: source.read(65536), b''):
            h.update(block)
    return h.hexdigest()


def safe_name(path, sha):
    stem = unicodedata.normalize('NFKD', path.stem).encode('ascii', 'ignore').decode()
    stem = re.sub('[^A-Za-z0-9_.-]+', '-', stem).strip('._-')[:70] or 'track'
    return f'{stem}-{sha[:16]}{path.suffix.lower()}'


def probe(path, ffprobe):
    size = path.stat().st_size
    if size <= 0 or size > MAX_BYTES:
        raise ValueError('File must be between 1 byte and 512 MiB')
    proc = run([ffprobe, '-v', 'error', '-show_format', '-show_streams', '-of', 'json', str(path)], capture_output=True, text=True)
    data = json.loads(proc.stdout)
    streams = data.get('streams', [])
    audio = [s for s in streams if s.get('codec_type') == 'audio']
    # Embedded cover art is fine; moving video and ambiguous audio tracks are not.
    video = [s for s in streams if s.get('codec_type') == 'video' and not s.get('disposition', {}).get('attached_pic')]
    if len(audio) != 1 or video:
        raise ValueError('Expected one audio stream and no moving video')
    a = audio[0]
    if a.get('codec_name') not in CODECS.get(path.suffix.lower(), set()):
        raise ValueError('Unsupported codec or codec/extension combination')
    if a.get('channels') not in (1, 2) or int(a.get('sample_rate', 0)) not in (44100, 48000):
        raise ValueError('Use mono/stereo at 44.1 or 48 kHz')
    duration = int(float(data.get('format', {}).get('duration', a.get('duration', 0))) * 1000)
    if not 0 < duration <= MAX_DURATION:
        raise ValueError('Invalid or excessive duration')
    return size, duration


def provider(adb, method, arg=None):
    args = adb + ['shell', 'content', 'call', '--uri', URI, '--method', method]
    if arg is not None:
        args += ['--arg', arg]
    output = run(args, capture_output=True, text=True).stdout
    start = output.find('{"')
    if start < 0:
        raise RuntimeError('Music provider unavailable. Install the updated APK. ' + output.strip())
    result, _ = json.JSONDecoder().raw_decode(output[start:])
    if not result.get('ok'):
        raise RuntimeError(result.get('error', output))
    return result


def choose_device(adb_path, requested):
    output = run([adb_path, 'devices', '-l'], capture_output=True, text=True).stdout
    devices = [line.split()[0] for line in output.splitlines()[1:] if re.match(r'^\S+\s+device(?:\s|$)', line)]
    if requested:
        if requested not in devices:
            raise RuntimeError('Requested device is not authorized and connected')
        serial = requested
    elif len(devices) == 1:
        serial = devices[0]
    else:
        raise RuntimeError('Connect one authorized Quest or specify --serial')
    adb = [adb_path, '-s', serial]
    model = run(adb + ['shell', 'getprop', 'ro.product.model'], capture_output=True, text=True).stdout.strip()
    if not re.search(r'Quest (3|3S)\b', model, re.I):
        raise RuntimeError(f'Expected Quest 3/3S; found {model!r}')
    print(f'Using {model} ({serial})')
    return adb


def upload(adb, path, name):
    # ADB shell stdin can corrupt binary input on Windows. Use the sync
    # protocol, then let content read a complete, device-local regular file.
    remote = '/data/local/tmp/lcvr-music-' + uuid.uuid4().hex + '.tmp'
    try:
        run(adb + ['push', str(path), remote], capture_output=True)
        command = f'content write --uri {shlex.quote(URI + "/upload/" + name)} < {shlex.quote(remote)}'
        run(adb + ['shell', command], stdin=subprocess.DEVNULL, capture_output=True)
    finally:
        try:
            run(adb + ['shell', 'rm', '-f', remote], stdin=subprocess.DEVNULL, capture_output=True)
        except (OSError, RuntimeError, subprocess.CalledProcessError) as error:
            print(f'Warning: could not remove temporary upload {remote}: {error}', file=sys.stderr)


def main(argv=None):
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('files', nargs='*', type=pathlib.Path, help='Files or flat music directories')
    parser.add_argument('--serial')
    parser.add_argument('--adb', help='ADB executable; defaults to PATH, Android SDK locations, or the Windows build SDK')
    parser.add_argument('--ffprobe', default='ffprobe')
    parser.add_argument('--export-board', type=pathlib.Path, help='Download the placement exported in the Radio settings page')
    parser.add_argument('--dry-run', action='store_true', help='Validate locally; no ADB or headset required')
    args = parser.parse_args(argv)
    paths = []
    for item in args.files:
        if item.is_dir():
            paths.extend(p.resolve() for p in sorted(item.iterdir()) if p.is_file() and p.suffix.lower() in EXTENSIONS)
        else:
            paths.append(item.resolve())
    if not paths and not args.export_board:
        parser.error('Select audio files/a directory or --export-board')
    adb_path = None if args.dry_run else find_adb(args.adb)
    accepted, rejected, seen = [], 0, set()
    if paths and not shutil.which(args.ffprobe):
        raise RuntimeError('ffprobe is required for validation. Install FFmpeg or specify --ffprobe')
    for path in paths:
        try:
            if not path.is_file() or path.suffix.lower() not in EXTENSIONS:
                raise ValueError('Missing file or unsupported extension')
            size, duration = probe(path, args.ffprobe)
            sha = digest(path)
            if sha in seen:
                print(f'SKIP duplicate: {path.name}'); continue
            seen.add(sha)
            accepted.append((path, size, duration, sha, safe_name(path, sha)))
            print(f'VALID {path.name}: {size / 1e6:.1f} MB, {duration / 60000:.1f} min')
        except (ValueError, OSError, subprocess.CalledProcessError) as error:
            rejected += 1; print(f'REJECT {path.name}: {error}', file=sys.stderr)
    if len(accepted) > 1000 or sum(t[2] for t in accepted) > MAX_DURATION:
        raise RuntimeError('Selection exceeds 1000 tracks or 24 days total duration')
    if args.dry_run:
        print(f'Dry run: {len(accepted)} valid, {rejected} rejected. No headset accessed.')
        return 1 if rejected else 0
    if paths and not accepted:
        raise RuntimeError('No valid music to import')
    adb = choose_device(adb_path, args.serial)
    if args.export_board:
        if args.export_board.exists():
            raise RuntimeError('Export destination already exists; choose a new filename')
        data = run(adb + ['exec-out', 'content', 'read', '--uri', URI + '/board-export'], capture_output=True).stdout
        if b'[RadioBoard]' not in data or b'[Vehicle.' not in data or len(data) > 65536:
            raise RuntimeError('Export unavailable. Export a saved vehicle placement from the in-game Radio settings first.')
        args.export_board.write_bytes(data)
        print(f'Exported placement: {args.export_board}')
    if not accepted:
        return 0
    info = provider(adb, 'info')
    duplicates = 0
    new = []
    remote_names = set(info.get('names', []))
    for item in accepted:
        path, size, duration, sha, name = item
        if name in remote_names and provider(adb, 'check', name + ':' + sha).get('exists'):
            duplicates += 1
            print(f'ALREADY PRESENT {path.name}')
        else:
            new.append(item)
    accepted = new
    if info['count'] + len(accepted) > 1000:
        raise RuntimeError('Existing library plus selection exceeds 1000 files')
    if info.get('duration', 0) + sum(t[2] for t in accepted) > MAX_DURATION:
        raise RuntimeError('Existing library plus selection exceeds 24 days total duration')
    # The largest file also needs a temporary ADB copy during upload.
    if info['free'] - sum(t[1] for t in accepted) - max((t[1] for t in accepted), default=0) < RESERVE:
        raise RuntimeError('Import would leave less than 1 GiB free')
    imported = 0
    for path, size, duration, sha, name in accepted:
        try:
            upload(adb, path, name)
            result = provider(adb, 'commit', name + ':' + sha)
            if result.get('bytes') != size:
                raise RuntimeError('Verified file size does not match local source')
            if result.get('duplicate'):
                duplicates += 1; print(f'ALREADY PRESENT {path.name}')
            else:
                imported += 1; print(f'IMPORTED {path.name}')
        except Exception:
            try:
                provider(adb, 'abort', name)
            except Exception:
                pass
            raise
    print(f'{imported} imported, {duplicates} already present, {rejected} rejected. The game rescans automatically; RESCAN is also available on the radio board.')
    print('See Radio settings for accepted/rejected counts and calibration controls.')
    return 1 if rejected else 0


if __name__ == '__main__':
    try:
        sys.exit(main())
    except (OSError, RuntimeError, ValueError, subprocess.CalledProcessError) as error:
        print(f'Import failed: {error}', file=sys.stderr)
        sys.exit(1)

# Repairs an existing Liberty City VR installation that is missing the port's
# replacement text and frontend assets.
#
# re3 does not run on retail GTA III data alone. Its frontend reads strings
# and button icons that a 2001 installation never shipped, and when they are
# absent the OPTIONS menus print "FET_GFX missing" and the like where the labels
# belong. Installations made before the build wizard copied these files show
# exactly that.
#
# This script copies nothing but those port assets, from the re3 source the
# wizard already downloaded. It touches no save, no setting and no model data.
[CmdletBinding()]
param(
    [string]$GameFilesDir,
    [string]$WorkDir = "C:\LCVRBuild",
    [string]$AndroidSdk,
    [string]$Serial,
    [string]$LogPath = (Join-Path $env:TEMP "LibertyCityVR-Install-Game-Files.log"),
    [switch]$NonInteractive
)

$ErrorActionPreference = "Stop"
$ProgressPreference = "SilentlyContinue"
$installerVersion = "0.5.2-gamefiles-1"
$packageName = "com.libertyvr.quest"
$remoteGameData = "/sdcard/Android/data/$packageName/files/gamedata"
$testedRe3Commit = "b050e1cc63b1869e6b514ab2f1a00ef4969e0c84"
$re3Url = "https://github.com/mrxenginner/re3.git"
$re3Branch = "master"
$re3DirName = "re3-public-b050e1c"
. (Join-Path $PSScriptRoot "device-diagnostics.ps1")
$script:transcriptStarted = $false
$script:adb = $null

# The exact set the Quest build reads and a retail installation does not
# provide.
$portAssets = @(
    @{ Folder = "TEXT"; Files = @(
        "american.gxt", "english.gxt", "french.gxt", "german.gxt",
        "italian.gxt", "JAPANESE.gxt", "polish.gxt", "russian.gxt", "spanish.gxt") },
    @{ Folder = "models"; Files = @(
        "fonts_j.txd", "fonts_p.txd", "fonts_r.txd",
        "frontend_ds3.txd", "frontend_ds4.txd", "frontend_nsw.txd", "frontend_x360.txd", "frontend_xone.txd",
        "generic.txd", "menu.txd", "nswbtns.txd", "particle.txd", "ps3btns.txd", "x360btns.txd") }
)

try {
    $logDirectory = Split-Path -Parent $LogPath
    if (-not [string]::IsNullOrWhiteSpace($logDirectory)) {
        New-Item -ItemType Directory -Path $logDirectory -Force | Out-Null
    }
    Initialize-PrivateDiagnosticLog
    $script:transcriptStarted = $true
} catch {
    Write-Host "Warning: diagnostic logging could not start: $($_.Exception.Message)" -ForegroundColor Yellow
}

function Stop-DiagnosticLog {
    if (-not $script:transcriptStarted) { return }
    $script:diagnosticLogEnabled = $false
    $script:transcriptStarted = $false
}

function Invoke-NativeCapture {
    param(
        [Parameter(Mandatory = $true)][string]$FilePath,
        [Parameter(Mandatory = $true)][string[]]$Arguments
    )
    if ($FilePath -eq $script:adb) {
        return Invoke-PrivateAdbCapture -Arguments $Arguments -Discovery:($Arguments[0] -eq "devices")
    }
    $savedErrorPreference = $ErrorActionPreference
    $ErrorActionPreference = "Continue"
    try {
        $lines = @(& $FilePath @Arguments 2>&1)
        $exitCode = $LASTEXITCODE
    } finally {
        $ErrorActionPreference = $savedErrorPreference
    }
    return [PSCustomObject]@{ ExitCode = $exitCode; Lines = $lines }
}

function Invoke-Checked {
    param(
        [Parameter(Mandatory = $true)][string]$FilePath,
        [Parameter(Mandatory = $true)][string[]]$Arguments,
        [string]$FailureMessage = "Command failed"
    )
    $result = Invoke-NativeCapture -FilePath $FilePath -Arguments $Arguments
    $result.Lines | ForEach-Object { Write-Host $_ }
    if ($result.ExitCode -ne 0) {
        throw "$FailureMessage (exit code $($result.ExitCode))."
    }
}

function Get-AdbArguments {
    param([string[]]$Arguments)
    if ([string]::IsNullOrWhiteSpace($Serial)) { return $Arguments }
    return @("-s", $Serial) + $Arguments
}

function Invoke-AdbChecked {
    param(
        [Parameter(Mandatory = $true)][string[]]$Arguments,
        [string]$FailureMessage = "ADB command failed",
        [switch]$Quiet
    )
    $result = Invoke-NativeCapture -FilePath $script:adb `
        -Arguments (Get-AdbArguments $Arguments)
    if (-not $Quiet) { $result.Lines | ForEach-Object { Write-Host $_ } }
    if ($result.ExitCode -ne 0) {
        $details = ($result.Lines | Out-String).Trim()
        throw "$FailureMessage (exit code $($result.ExitCode)). $details"
    }
}

function Find-Adb {
    $candidates = [System.Collections.Generic.List[string]]::new()
    if (-not [string]::IsNullOrWhiteSpace($AndroidSdk)) {
        $candidates.Add((Join-Path $AndroidSdk "platform-tools\adb.exe"))
    }
    if (-not [string]::IsNullOrWhiteSpace($env:ANDROID_HOME)) {
        $candidates.Add((Join-Path $env:ANDROID_HOME "platform-tools\adb.exe"))
    }
    if (-not [string]::IsNullOrWhiteSpace($env:ANDROID_SDK_ROOT)) {
        $candidates.Add((Join-Path $env:ANDROID_SDK_ROOT "platform-tools\adb.exe"))
    }
    $candidates.Add((Join-Path $WorkDir ".android-sdk\platform-tools\adb.exe"))
    $candidates.Add("C:\VCVRBuild\.android-sdk\platform-tools\adb.exe")
    if (-not [string]::IsNullOrWhiteSpace($env:LOCALAPPDATA)) {
        $candidates.Add((Join-Path $env:LOCALAPPDATA "Android\Sdk\platform-tools\adb.exe"))
    }
    $installed = Get-Command adb.exe -ErrorAction SilentlyContinue
    if ($null -ne $installed) { $candidates.Add($installed.Source) }

    foreach ($candidate in $candidates) {
        if (Test-Path -LiteralPath $candidate -PathType Leaf) {
            return (Resolve-Path -LiteralPath $candidate).Path
        }
    }
    throw "ADB was not found. Run BUILD_AND_INSTALL.bat once, or pass -AndroidSdk with the SDK folder."
}

function Test-GameFilesFolder {
    param([string]$Path)
    if ([string]::IsNullOrWhiteSpace($Path) -or
        -not (Test-Path -LiteralPath $Path -PathType Container)) { return $false }
    foreach ($asset in $portAssets) {
        foreach ($name in $asset.Files) {
            if (-not (Test-Path -LiteralPath (Join-Path $Path "$($asset.Folder)\$name") -PathType Leaf)) {
                return $false
            }
        }
    }
    return $true
}

function Find-Git {
    $installed = Get-Command git.exe -ErrorAction SilentlyContinue
    if ($null -ne $installed) { return $installed.Source }
    $portable = Get-ChildItem -Path (Join-Path $WorkDir ".tools") -Filter "MinGit-*" `
        -Directory -ErrorAction SilentlyContinue | Sort-Object Name -Descending
    foreach ($candidate in $portable) {
        $exe = Join-Path $candidate.FullName "cmd\git.exe"
        if (Test-Path -LiteralPath $exe -PathType Leaf) { return $exe }
    }
    return $null
}

# The wizard leaves a clean pinned reVC checkout and an assembled tree behind,
# so a repair normally copies from disk and downloads nothing.
function Resolve-GameFilesFolder {
    if (-not [string]::IsNullOrWhiteSpace($GameFilesDir)) {
        $requested = [IO.Path]::GetFullPath($GameFilesDir.Trim('"'))
        foreach ($candidate in @($requested, (Join-Path $requested "gamefiles"))) {
            if (Test-GameFilesFolder -Path $candidate) {
                return (Resolve-Path -LiteralPath $candidate).Path
            }
        }
        throw "-GameFilesDir '$requested' does not contain the re3 gamefiles (TEXT\american.gxt and models\x360btns.txd)."
    }

    $work = [IO.Path]::GetFullPath($WorkDir)
    $candidates = [System.Collections.Generic.List[string]]::new()
    $candidates.Add((Join-Path $work "$re3DirName\gamefiles"))
    $assembled = Get-ChildItem -Path $work -Filter "liberty-city-vr-build*" `
        -Directory -ErrorAction SilentlyContinue |
        Sort-Object LastWriteTime -Descending
    foreach ($tree in $assembled) {
        $candidates.Add((Join-Path $tree.FullName "gamefiles"))
    }
    foreach ($candidate in $candidates) {
        if (Test-GameFilesFolder -Path $candidate) {
            Write-Host "Using the port assets already on this PC: $candidate"
            return (Resolve-Path -LiteralPath $candidate).Path
        }
    }

    $gitExe = Find-Git
    if ($null -eq $gitExe) {
        throw "No re3 source was found under $work and Git is not available. Run BUILD_AND_INSTALL.bat once, or pass -GameFilesDir with a re3 checkout."
    }
    $re3Dir = Join-Path $work $re3DirName
    if (Test-Path -LiteralPath $re3Dir) {
        throw "$re3Dir exists but has no usable gamefiles folder. Remove it and retry, or pass -GameFilesDir."
    }
    Write-Host "Downloading the tested re3 source for its replacement assets..." -ForegroundColor Yellow
    New-Item -ItemType Directory -Path $work -Force | Out-Null
    Invoke-Checked -FilePath $gitExe -Arguments @(
        "clone", "--no-checkout", "-b", $re3Branch, $re3Url, $re3Dir
    ) -FailureMessage "re3 clone failed"
    Invoke-Checked -FilePath $gitExe -Arguments @(
        "-c", "safe.directory=$($re3Dir.Replace('\', '/'))", "-C", $re3Dir,
        "checkout", "--detach", $testedRe3Commit
    ) -FailureMessage "Could not select the tested re3 commit"

    $downloaded = Join-Path $re3Dir "gamefiles"
    if (-not (Test-GameFilesFolder -Path $downloaded)) {
        throw "The downloaded re3 source does not contain the expected gamefiles."
    }
    return (Resolve-Path -LiteralPath $downloaded).Path
}

function Select-QuestDevice {
    $result = Invoke-NativeCapture -FilePath $script:adb -Arguments @("devices", "-l")
    if ($result.ExitCode -ne 0) { throw "adb devices failed." }
    $devices = @()
    foreach ($line in $result.Lines) {
        if (([string]$line) -match '^(\S+)\s+device(?:\s|$)') { $devices += $Matches[1] }
    }
    if (-not [string]::IsNullOrWhiteSpace($Serial)) {
        if ($devices -notcontains $Serial) {
            throw "The selected device is not connected and authorized. Accept the USB debugging prompt inside the headset."
        }
        return
    }
    if ($devices.Count -eq 0) {
        throw "No authorized Quest was found. Connect it by USB, enable USB debugging and accept the prompt inside the headset."
    }
    if ($devices.Count -eq 1) {
        $script:Serial = $devices[0]
        return
    }
    if ($NonInteractive) { throw "Multiple Android devices are connected; pass -Serial." }
    Write-Host "Connected Android devices:" -ForegroundColor Yellow
    for ($index = 0; $index -lt $devices.Count; $index++) {
        Write-Host "  $($index + 1). $(Get-PrivateDeviceLabel $devices[$index])"
    }
    $answer = Read-Host "Select the Quest number"
    $selection = 0
    if (-not [int]::TryParse($answer, [ref]$selection) -or
        $selection -lt 1 -or $selection -gt $devices.Count) {
        throw "Invalid device selection."
    }
    $script:Serial = $devices[$selection - 1]
}

try {
    Write-Host "Liberty City VR - port text and frontend asset repair ($installerVersion)" -ForegroundColor Green
    Write-Host "This replaces only the port's own text and frontend files. Saves, settings and models are untouched."
    Write-Host ""

    $source = Resolve-GameFilesFolder
    $script:adb = Find-Adb
    Write-Host "ADB: $script:adb"
    Select-QuestDevice
    Write-Host "Quest: personal Quest 3 device"

    # A missing gamedata root means the game was never given its data; copying
    # the port assets into an empty tree would look like success and still fail
    # on launch, so say what is actually wrong instead.
    $probe = Invoke-NativeCapture -FilePath $script:adb `
        -Arguments (Get-AdbArguments @("shell", "ls", "$remoteGameData/models/gta3.img"))
    if ($probe.ExitCode -ne 0 -or (($probe.Lines | Out-String) -match "No such file")) {
        throw "No GTA III data was found at $remoteGameData. Install the game with BUILD_AND_INSTALL.bat first; this tool only repairs an existing installation."
    }

    $copied = 0
    foreach ($asset in $portAssets) {
        $localFolder = Join-Path $source $asset.Folder
        $remoteFolder = "$remoteGameData/$($asset.Folder)"
        Invoke-AdbChecked -Arguments @("shell", "mkdir", "-p", $remoteFolder) `
            -FailureMessage "Could not create $remoteFolder on the headset" -Quiet
        foreach ($name in $asset.Files) {
            Write-Host "  $($asset.Folder)/$name" -ForegroundColor Cyan
            Invoke-AdbChecked -Arguments @(
                "push", (Join-Path $localFolder $name), "$remoteFolder/$name"
            ) -FailureMessage "Failed to copy $($asset.Folder)/$name" -Quiet
            $copied++
        }
    }

    Invoke-AdbChecked -Arguments @("shell", "am", "force-stop", $packageName) `
        -FailureMessage "Could not leave the app stopped" -Quiet

    Write-Host ""
    Write-Host "$copied files installed. Launch Liberty City VR again." -ForegroundColor Green
    Write-Host "Diagnostic log: $LogPath"
    Stop-DiagnosticLog
} catch {
    Write-Host ""
    Write-Host "ERROR: $($_.Exception.Message)" -ForegroundColor Red
    Write-Host "Nothing was silently ignored. Fix the reported item and rerun."
    Write-Host "Diagnostic log: $LogPath"
    Stop-DiagnosticLog
    exit 1
}

#!/usr/bin/env bash # Repairs an existing Vice City VR installation that is missing the port's # replacement text and frontend assets. # # reVC does not run on retail Vice City data alone. Its frontend reads strings # and button icons that a 2002 installation never shipped, and when they are # absent the OPTIONS menus print "FET_GFX missing" and the like where the # labels belong. Installations made before the build wizard copied these # files show exactly that. # # This script copies nothing but those port assets, from the reVC source the # wizard already downloaded. It touches no save, no setting and no model data. # # Linux port of install-game-files.ps1. # # Arguments: # --game-files-dir DIR / -GameFilesDir DIR reVC source with gamefiles/ # --work-dir DIR / -WorkDir DIR wizard work dir (default ~/VCVRBuild) # --android-sdk DIR / -AndroidSdk DIR Android SDK root # --serial SERIAL / -Serial SERIAL Quest USB serial # --log-path PATH / -LogPath PATH diagnostic log location # --non-interactive / -NonInteractive never prompt; fail instead
set -uo pipefail source "$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)/device-diagnostics.sh"
GAME_FILES_DIR="" WORK_DIR="${HOME}/LCVRBuild" ANDROID_SDK="" SERIAL="" LOG_PATH="${TMPDIR:-/tmp}/LibertyCityVR-Install-Game-Files.log" NON_INTERACTIVE=0
INSTALLER_VERSION="0.5.2-gamefiles-1" PACKAGE_NAME="com.libertyvr.quest" REMOTE_GAME_DATA="/sdcard/Android/data/${PACKAGE_NAME}/files/gamedata" TESTED_RE3_COMMIT="b050e1cc63b1869e6b514ab2f1a00ef4969e0c84" RE3_URL="https://github.com/mrxenginner/re3.git" RE3_BRANCH="master" RE3_DIR_NAME="re3-public-b050e1c" ADB=""
# The exact set the Quest build reads and a retail installation does not # provide. port_text_files=(american.gxt english.gxt french.gxt german.gxt italian.gxt JAPANESE.gxt polish.gxt russian.gxt spanish.gxt) port_model_files=(fonts_j.txd fonts_p.txd fonts_r.txd frontend_ds3.txd frontend_ds4.txd frontend_nsw.txd frontend_x360.txd frontend_xone.txd generic.txd menu.txd nswbtns.txd particle.txd ps3btns.txd x360btns.txd)
while [ $# -gt 0 ]; do case "$1" in --game-files-dir|-GameFilesDir) GAME_FILES_DIR="$2"; shift 2 ;; --work-dir|-WorkDir) WORK_DIR="$2"; shift 2 ;; --android-sdk|-AndroidSdk) ANDROID_SDK="$2"; shift 2 ;; --serial|-Serial) SERIAL="$2"; shift 2 ;; --log-path|-LogPath) LOG_PATH="$2"; shift 2 ;; --non-interactive|-NonInteractive) NON_INTERACTIVE=1; shift ;; --help|-h) sed -n '2,20p' "$0" | sed 's/^# \{0,1\}//' exit 0 ;; *) echo "Unknown argument: $1 (see --help)" >&2; exit 1 ;; esac done
LOG_DIR="$(dirname "$LOG_PATH")" mkdir -p "$LOG_DIR" 2>/dev/null || true exec > >(tee "$LOG_PATH") 2>&1
die() { echo "" echo "ERROR: $1" >&2 echo "Nothing was silently ignored. Fix the reported item and rerun." >&2 echo "Diagnostic log: $LOG_PATH" >&2 exit 1 }
checked() { local msg="$1"; shift "$@" local rc=$? if [ "$rc" -ne 0 ]; then die "$msg (exit code $rc)." fi }
# Run a command capturing output; sets CAPTURED_OUTPUT / CAPTURED_EXIT. capture() { CAPTURED_OUTPUT="$( "$@" 2>&1 )" CAPTURED_EXIT=$? }
adb_args() { local out=() if [ -n "$SERIAL" ]; then out+=("-s" "$SERIAL"); fi out+=("$@") printf '%s\n' "${out[@]}" }
# adb_checked MSG SUBCMD [ARGS...] — runs adb SUBCMD ARGS, die on failure. adb_checked() { local msg="$1"; shift local args=() if [ -n "$SERIAL" ]; then args+=("-s" "$SERIAL"); fi args+=("$@") private_adb "${args[@]}" local rc=$? [ "$rc" -eq 0 ] || die "$msg (exit code $rc)." }
# adb_checked_quiet — same, but suppresses output. adb_checked_quiet() { local msg="$1"; shift local args=() if [ -n "$SERIAL" ]; then args+=("-s" "$SERIAL"); fi args+=("$@") private_adb "${args[@]}" >/dev/null local rc=$? [ "$rc" -eq 0 ] || die "$msg (exit code $rc)." }
find_adb() { local candidates=() [ -n "$ANDROID_SDK" ] && candidates+=("$ANDROID_SDK/platform-tools/adb") [ -n "${ANDROID_HOME:-}" ] && candidates+=("$ANDROID_HOME/platform-tools/adb") [ -n "${ANDROID_SDK_ROOT:-}" ] && candidates+=("$ANDROID_SDK_ROOT/platform-tools/adb") candidates+=("$WORK_DIR/.android-sdk/platform-tools/adb" "${HOME}/VCVRBuild/.android-sdk/platform-tools/adb" "${HOME}/Android/Sdk/platform-tools/adb") local installed installed="$(command -v adb || true)" [ -n "$installed" ] && candidates+=("$installed")
local c for c in "${candidates[@]}"; do if [ -x "$c" ]; then echo "$c" return 0 fi done die "ADB was not found. Run BUILD_AND_INSTALL.sh once, or pass --android-sdk with the SDK folder." }
# True if $1 contains every port asset. test_game_files_folder() { local path="$1" [ -n "$path" ] && [ -d "$path" ] || return 1 local name for name in "${port_text_files[@]}"; do [ -f "$path/TEXT/$name" ] || return 1 done for name in "${port_model_files[@]}"; do [ -f "$path/models/$name" ] || return 1 done return 0 }
find_git() { local g g="$(command -v git || true)" [ -n "$g" ] && echo "$g" return 0 }
# Resolve the folder holding the port's gamefiles/. resolve_game_files_folder() { if [ -n "$GAME_FILES_DIR" ]; then local requested requested="$(realpath -m -- "$GAME_FILES_DIR" 2>/dev/null || printf '%s' "$GAME_FILES_DIR")" local candidate for candidate in "$requested" "$requested/gamefiles"; do if test_game_files_folder "$candidate"; then echo "$(cd "$candidate" && pwd)" return 0 fi done die "-game-files-dir '$requested' does not contain the re3 gamefiles (TEXT/american.gxt and models/x360btns.txd)." fi
local work work="$(realpath -m -- "$WORK_DIR" 2>/dev/null || printf '%s' "$WORK_DIR")" mkdir -p "$WORK_DIR" work="$(cd "$WORK_DIR" && pwd)"
local candidates=("$work/$RE3_DIR_NAME/gamefiles") # Newest assembled trees first. local tree while IFS= read -r tree; do candidates+=("$tree/gamefiles") done < <(find "$work" -maxdepth 1 -type d -name 'liberty-city-vr-build*' -printf '%T@ %p\n' 2>/dev/null | sort -rn | cut -d' ' -f2-)
local candidate for candidate in "${candidates[@]}"; do if test_game_files_folder "$candidate"; then echo "Using the port assets already on this PC: $candidate" >&2 echo "$(cd "$candidate" && pwd)" return 0 fi done
local git_exe git_exe="$(find_git)" if [ -z "$git_exe" ]; then die "No re3 source was found under $work and Git is not available. Run BUILD_AND_INSTALL.sh once, or pass --game-files-dir with a re3 checkout." fi local re3_dir="$work/$RE3_DIR_NAME" if [ -d "$re3_dir" ]; then die "$re3_dir exists but has no usable gamefiles folder. Remove it and retry, or pass --game-files-dir." fi echo "Downloading the tested re3 source for its replacement assets..." >&2 checked "re3 clone failed" "$git_exe" clone --no-checkout -b "$RE3_BRANCH" "$RE3_URL" "$re3_dir" checked "Could not select the tested re3 commit" "$git_exe" -c "safe.directory=$re3_dir" -C "$re3_dir" checkout --detach "$TESTED_RE3_COMMIT"
local downloaded="$re3_dir/gamefiles" test_game_files_folder "$downloaded" || die "The downloaded re3 source does not contain the expected gamefiles." echo "$(cd "$downloaded" && pwd)" }
select_quest_device() { private_adb_discover [ "$CAPTURED_EXIT" -eq 0 ] || die "adb devices failed." local devices=() local line while IFS= read -r line; do if [[ "$line" =~ ^([A-Za-z0-9._-]+)[[:space:]]+device([[:space:]]|$) ]]; then devices+=("${BASH_REMATCH[1]}") fi done <<< "$CAPTURED_OUTPUT"
if [ -n "$SERIAL" ]; then local d for d in "${devices[@]}"; do [ "$d" = "$SERIAL" ] && return 0; done die "The selected device is not connected and authorized. Accept the USB debugging prompt inside the headset." fi if [ "${#devices[@]}" -eq 0 ]; then die "No authorized Quest was found. Connect it by USB, enable USB debugging and accept the prompt inside the headset." fi if [ "${#devices[@]}" -eq 1 ]; then SERIAL="${devices[0]}" return 0 fi if [ "$NON_INTERACTIVE" -eq 1 ]; then die "Multiple Android devices are connected; pass --serial."; fi echo "Connected Android devices:" local i for i in "${!devices[@]}"; do echo " $((i + 1)). $(private_device_label "${devices[$i]}")" done local answer selection read -r -p "Select the Quest number " answer [[ "$answer" =~ ^[0-9]+$ ]] || die "Invalid device selection." selection=$((answer - 1)) if [ "$selection" -lt 0 ] || [ "$selection" -ge "${#devices[@]}" ]; then die "Invalid device selection." fi SERIAL="${devices[$selection]}" }
echo "Liberty City VR - port text and frontend asset repair ($INSTALLER_VERSION)" echo "This replaces only the port's own text and frontend files. Saves, settings and models are untouched." echo ""
SOURCE="$(resolve_game_files_folder)" ADB="$(find_adb)" echo "ADB: $ADB" select_quest_device echo "Quest: personal Quest 3 device"
# A missing gamedata root means the game was never given its data; copying # the port assets into an empty tree would look like success and still fail # on launch, so say what is actually wrong instead. probe_argv=(private_adb) if [ -n "$SERIAL" ]; then probe_argv+=("-s" "$SERIAL"); fi probe_argv+=("shell" "ls" "$REMOTE_GAME_DATA/models/gta3.img") probe_output="$("${probe_argv[@]}" 2>&1)" probe_rc=$? if [ "$probe_rc" -ne 0 ] || echo "$probe_output" | grep -q "No such file"; then die "No GTA III data was found at $REMOTE_GAME_DATA. Install the game with BUILD_AND_INSTALL.sh first; this tool only repairs an existing installation." fi
copied=0 adb_checked_quiet "Could not create $REMOTE_GAME_DATA/TEXT on the headset" shell mkdir -p "$REMOTE_GAME_DATA/TEXT" adb_checked_quiet "Could not create $REMOTE_GAME_DATA/models on the headset" shell mkdir -p "$REMOTE_GAME_DATA/models" for name in "${port_text_files[@]}"; do echo " TEXT/$name" if [ -n "$SERIAL" ]; then private_adb -s "$SERIAL" push "$SOURCE/TEXT/$name" "$REMOTE_GAME_DATA/TEXT/$name" >/dev/null || die "Failed to copy TEXT/$name" else private_adb push "$SOURCE/TEXT/$name" "$REMOTE_GAME_DATA/TEXT/$name" >/dev/null || die "Failed to copy TEXT/$name" fi copied=$((copied + 1)) done for name in "${port_model_files[@]}"; do echo " models/$name" if [ -n "$SERIAL" ]; then private_adb -s "$SERIAL" push "$SOURCE/models/$name" "$REMOTE_GAME_DATA/models/$name" >/dev/null || die "Failed to copy models/$name" else private_adb push "$SOURCE/models/$name" "$REMOTE_GAME_DATA/models/$name" >/dev/null || die "Failed to copy models/$name" fi copied=$((copied + 1)) done
adb_checked_quiet "Could not leave the app stopped" shell am force-stop "$PACKAGE_NAME"
echo "" echo "$copied files installed. Launch Vice City VR again." echo "Diagnostic log: $LOG_PATH" exit 0

# Installs a locally generated optional Modern model overlay on a connected
# Quest. No APK or third-party assets are downloaded by this script.
[CmdletBinding()]
param(
    [Alias("ModelDir")][string]$ModernDir,
    [ValidateSet("Modern","Xbox")][string]$Profile="Modern",
    [string]$AndroidSdk,
    [string]$Serial,
    [string]$LogPath = (Join-Path $env:TEMP "LibertyCityVR-Install-Modern-Models.log"),
    [switch]$NonInteractive
)

$ErrorActionPreference = "Stop"
$ProgressPreference = "SilentlyContinue"
$installerVersion = "0.7.0-models-lcv-1"
if ($Profile -eq 'Xbox') { Write-Host 'Xbox is a legacy alias for the single Modern profile.' }
$Profile = 'Modern'
$profileDirectory = 'modern'
$profileRequiredFiles = @("models/gta3.img", "models/gta3.dir", "BUILD_INFO.txt")
$profileHashFiles = @("models/gta3.img", "models/gta3.dir")
$packageName = "com.libertyvr.quest"
$remoteModelSets = "/sdcard/Android/data/$packageName/files/gamedata/modelsets"
$repoRoot = Split-Path $PSScriptRoot -Parent
. (Join-Path $PSScriptRoot "device-diagnostics.ps1")
$script:transcriptStarted = $false
$script:adb = $null
$script:stagingRemote = $null

try {
    $logDirectory = Split-Path -Parent $LogPath
    if (-not [string]::IsNullOrWhiteSpace($logDirectory)) {
        New-Item -ItemType Directory -Path $logDirectory -Force | Out-Null
    }
    Initialize-PrivateDiagnosticLog
    $script:transcriptStarted = $true
} catch {
    Write-Host "Warning: diagnostic logging could not start: $($_.Exception.Message)" -ForegroundColor Yellow
}

function Stop-DiagnosticLog {
    if (-not $script:transcriptStarted) { return }
    $script:diagnosticLogEnabled = $false
    $script:transcriptStarted = $false
}

function Invoke-NativeCapture {
    param(
        [Parameter(Mandatory = $true)][string]$FilePath,
        [Parameter(Mandatory = $true)][string[]]$Arguments
    )
    if ($FilePath -eq $script:adb) {
        return Invoke-PrivateAdbCapture -Arguments $Arguments -Discovery:($Arguments[0] -eq "devices")
    }
    $savedErrorPreference = $ErrorActionPreference
    $ErrorActionPreference = "Continue"
    try {
        $lines = @(& $FilePath @Arguments 2>&1)
        $exitCode = $LASTEXITCODE
    } finally {
        $ErrorActionPreference = $savedErrorPreference
    }
    return [PSCustomObject]@{ ExitCode = $exitCode; Lines = $lines }
}

function Get-AdbArguments {
    param([string[]]$Arguments)
    if ([string]::IsNullOrWhiteSpace($Serial)) { return $Arguments }
    return @("-s", $Serial) + $Arguments
}

function Invoke-AdbCapture {
    param([Parameter(Mandatory = $true)][string[]]$Arguments)
    return Invoke-NativeCapture -FilePath $script:adb -Arguments (Get-AdbArguments $Arguments)
}

function Invoke-AdbChecked {
    param(
        [Parameter(Mandatory = $true)][string[]]$Arguments,
        [string]$FailureMessage = "ADB command failed",
        [switch]$Quiet
    )
    $result = Invoke-AdbCapture -Arguments $Arguments
    if (-not $Quiet) { $result.Lines | ForEach-Object { Write-Host $_ } }
    if ($result.ExitCode -ne 0) {
        $details = ($result.Lines | Out-String).Trim()
        throw "$FailureMessage (exit code $($result.ExitCode)). $details"
    }
    return $result
}

function Get-RelativeRemotePath {
    param([string]$Root, [string]$Path)
    return $Path.Substring($Root.Length).TrimStart([char[]]"\/").Replace("\", "/")
}

function Find-Adb {
    $candidates = [System.Collections.Generic.List[string]]::new()
    if (-not [string]::IsNullOrWhiteSpace($AndroidSdk)) {
        $candidates.Add((Join-Path $AndroidSdk "platform-tools\adb.exe"))
    }
    if (-not [string]::IsNullOrWhiteSpace($env:ANDROID_HOME)) {
        $candidates.Add((Join-Path $env:ANDROID_HOME "platform-tools\adb.exe"))
    }
    if (-not [string]::IsNullOrWhiteSpace($env:ANDROID_SDK_ROOT)) {
        $candidates.Add((Join-Path $env:ANDROID_SDK_ROOT "platform-tools\adb.exe"))
    }
    $candidates.Add("C:\LCVRBuild\.android-sdk\platform-tools\adb.exe")
    $candidates.Add("C:\VCVRBuild\.android-sdk\platform-tools\adb.exe")
    if (-not [string]::IsNullOrWhiteSpace($env:LOCALAPPDATA)) {
        $candidates.Add((Join-Path $env:LOCALAPPDATA "Android\Sdk\platform-tools\adb.exe"))
    }
    $installed = Get-Command adb.exe -ErrorAction SilentlyContinue
    if ($null -ne $installed) { $candidates.Add($installed.Source) }

    foreach ($candidate in $candidates) {
        if (Test-Path -LiteralPath $candidate -PathType Leaf) {
            return (Resolve-Path -LiteralPath $candidate).Path
        }
    }
    throw "ADB was not found. Run BUILD_AND_INSTALL.bat once, or pass -AndroidSdk with the SDK folder."
}

function Test-ModernFolder {
    param([string]$Path)
    if ([string]::IsNullOrWhiteSpace($Path) -or -not (Test-Path -LiteralPath $Path -PathType Container)) { return $false }
    . (Join-Path $PSScriptRoot 'modelsets/xbox-modelset.ps1')
    $python = Get-ModelsetPython
    & $python (Join-Path $PSScriptRoot 'modelsets/xbox-modelset.py') validate --out $Path --profile $Profile.ToLowerInvariant()
    return $LASTEXITCODE -eq 0
}

function Resolve-ModernFolder {
    param([string]$Requested)
    if ([string]::IsNullOrWhiteSpace($Requested)) {
        if ($NonInteractive) { throw "-ModernDir is required in non-interactive mode." }
        try {
            Add-Type -AssemblyName System.Windows.Forms
            $dialog = New-Object System.Windows.Forms.FolderBrowserDialog
            $dialog.Description = "Select the generated modelsets\$profileDirectory folder"
            $dialog.ShowNewFolderButton = $false
            if ($dialog.ShowDialog() -ne [System.Windows.Forms.DialogResult]::OK) {
                throw "No Modern model folder was selected."
            }
            $Requested = $dialog.SelectedPath
        } catch [System.Management.Automation.RuntimeException] {
            throw
        } catch {
            Write-Host "Folder picker was unavailable. Paste the generated modern folder path." -ForegroundColor Yellow
            $Requested = Read-Host "Modern folder"
        }
    }

    $root = [IO.Path]::GetFullPath($Requested.Trim('"'))
    $candidates = @(
        $root,
        (Join-Path $root $profileDirectory),
        (Join-Path $root "modelsets\$profileDirectory")
    )
    foreach ($candidate in $candidates) {
        if (Test-ModernFolder -Path $candidate) {
            return (Resolve-Path -LiteralPath $candidate).Path
        }
    }
    throw "The selected folder is not a complete generated $Profile profile. Validation must pass before device transfer."
}

function Select-QuestDevice {
    $result = Invoke-NativeCapture -FilePath $script:adb -Arguments @("devices", "-l")
    if ($result.ExitCode -ne 0) { throw "adb devices failed." }
    $devices = @()
    foreach ($line in $result.Lines) {
        if (([string]$line) -match '^(\S+)\s+device(?:\s|$)') { $devices += $Matches[1] }
    }
    if (-not [string]::IsNullOrWhiteSpace($Serial)) {
        if ($devices -notcontains $Serial) {
            throw "The selected device is not connected and authorized. Accept the USB debugging prompt inside the headset."
        }
        return
    }
    if ($devices.Count -eq 0) {
        throw "No authorized Quest was found. Connect it by USB, enable USB debugging and accept the prompt inside the headset."
    }
    if ($devices.Count -eq 1) {
        $script:Serial = $devices[0]
        return
    }
    if ($NonInteractive) { throw "Multiple Android devices are connected; pass -Serial." }
    Write-Host "Connected Android devices:" -ForegroundColor Yellow
    for ($index = 0; $index -lt $devices.Count; $index++) {
        Write-Host "  $($index + 1). $(Get-PrivateDeviceLabel $devices[$index])"
    }
    $answer = Read-Host "Select the Quest number"
    $selection = 0
    if (-not [int]::TryParse($answer, [ref]$selection) -or
        $selection -lt 1 -or $selection -gt $devices.Count) {
        throw "Invalid device selection."
    }
    $script:Serial = $devices[$selection - 1]
}

try {
    Write-Host "Liberty City VR - $Profile model installer ($installerVersion)" -ForegroundColor Green
    Write-Host "This copies a model overlay generated locally by the player; it downloads no model assets."

    $modern = Resolve-ModernFolder -Requested $ModernDir
    $profileHashFiles = @([IO.File]::ReadAllLines((Join-Path $modern 'BUILD_INFO.txt')) | ForEach-Object {
        if ($_ -match '^SHA256 (.+)=([A-F0-9]{64})$') { $Matches[1] }
    })
    $script:adb = Find-Adb
    Select-QuestDevice

    Write-Host "$Profile folder: $modern"
    Write-Host "ADB: $script:adb"
    Write-Host "Quest: personal Quest 3 device"

    $packageResult = Invoke-AdbCapture -Arguments @("shell", "pm", "path", $packageName)
    if ($packageResult.ExitCode -ne 0 -or
        (($packageResult.Lines | Out-String) -notmatch "package:")) {
        throw "Liberty City VR is not installed on the selected Quest. Run BUILD_AND_INSTALL.bat first."
    }

    # Starting the provider creates the application-owned external directory on
    # a fresh install before the ADB shell writes any children into it.
    Invoke-AdbChecked -Arguments @(
        "shell", "content", "query", "--uri", "content://$packageName.saves/slot/1",
        "--projection", "_display_name:_size"
    ) -FailureMessage "Could not bootstrap Liberty City VR application storage" -Quiet | Out-Null
    Invoke-AdbChecked -Arguments @("shell", "am", "force-stop", $packageName) `
        -FailureMessage "Could not stop Liberty City VR before copying" -Quiet | Out-Null

    $stamp = Get-Date -Format "yyyyMMdd-HHmmss"
    $script:stagingRemote = "$remoteModelSets/.$profileDirectory-incoming-$stamp"
    $backupRemote = "$remoteModelSets/.$profileDirectory-backup-$stamp"
    $finalRemote = "$remoteModelSets/$profileDirectory"

    Invoke-AdbChecked -Arguments @("shell", "mkdir", "-p", $script:stagingRemote) `
        -FailureMessage "Could not create the temporary Modern directory" -Quiet | Out-Null

    $directories = @(Get-ChildItem -LiteralPath $modern -Directory -Recurse -Force |
        Sort-Object { $_.FullName.Length })
    foreach ($directory in $directories) {
        $relative = Get-RelativeRemotePath -Root $modern -Path $directory.FullName
        Invoke-AdbChecked -Arguments @("shell", "mkdir", "-p", "$script:stagingRemote/$relative") `
            -FailureMessage "Could not create temporary Modern directory: $relative" -Quiet | Out-Null
    }

    $files = @(Get-ChildItem -LiteralPath $modern -File -Recurse -Force)
    if ($files.Count -eq 0) { throw "The selected Modern folder is empty." }
    Write-Host "Copying $($files.Count) $Profile files into pre-created app storage. This can take several minutes..." -ForegroundColor Cyan
    $fileIndex = 0
    foreach ($file in $files) {
        $fileIndex++
        $relative = Get-RelativeRemotePath -Root $modern -Path $file.FullName
        $destinationRemote = "$script:stagingRemote/$relative"
        Write-Host "  [$fileIndex/$($files.Count)] $relative"
        Invoke-AdbChecked -Arguments @("push", $file.FullName, $destinationRemote) `
            -FailureMessage "Failed while transferring $relative" | Out-Null
        $sizeResult = Invoke-AdbChecked -Arguments @("shell", "stat", "-c", "%s", $destinationRemote) `
            -FailureMessage "Could not verify copied size for $relative" -Quiet
        $remoteSizeText = (($sizeResult.Lines | Out-String).Trim() -replace '[^0-9]', '')
        $remoteSize = 0L
        if (-not [long]::TryParse($remoteSizeText, [ref]$remoteSize) -or
            $remoteSize -ne $file.Length) {
            throw "Copied size mismatch for $relative (PC $($file.Length), Quest $remoteSizeText)."
        }
    }

    # ADB-created directories may be shell-owned 0770. The app needs
    # read/traverse access before the verified profile is activated.
    Invoke-AdbChecked -Arguments @("shell", "chmod", "-R", "a+rX", $script:stagingRemote) `
        -FailureMessage "Could not grant application read access to the copied profile" -Quiet | Out-Null

    foreach ($relative in $profileRequiredFiles) {
        $requiredRemote="$script:stagingRemote/$relative"
        Invoke-AdbChecked -Arguments @("shell", "test", "-f", $requiredRemote) `
            -FailureMessage "Required copied file is missing: $requiredRemote" -Quiet | Out-Null
    }

    # Verify every manifest file, including world definitions and loose TXDs,
    # before activating the staged profile.
    foreach ($relative in $profileHashFiles) {
        $localWheel = Join-Path $modern $relative
        $remoteWheel = "$script:stagingRemote/$($relative.Replace('\', '/'))"
        $localHash = (Get-FileHash -LiteralPath $localWheel -Algorithm SHA256).Hash.ToLowerInvariant()
        $hashResult = Invoke-AdbChecked -Arguments @("shell", "sha256sum", $remoteWheel) `
            -FailureMessage "Could not verify copied wheel asset: $relative" -Quiet
        $remoteHashText = ($hashResult.Lines | Out-String)
        $remoteHashMatch = [regex]::Match($remoteHashText, '(?i)\b[0-9a-f]{64}\b')
        if (-not $remoteHashMatch.Success -or
            $remoteHashMatch.Value.ToLowerInvariant() -ne $localHash) {
            throw "Copied SHA256 mismatch for $relative. The previous Modern folder remains active."
        }
    }

    $existingResult = Invoke-AdbCapture -Arguments @("shell", "test", "-d", $finalRemote)
    $hadExisting = $existingResult.ExitCode -eq 0
    if ($hadExisting) {
        Invoke-AdbChecked -Arguments @("shell", "rm", "-rf", $backupRemote) `
            -FailureMessage "Could not prepare the Modern backup path" -Quiet | Out-Null
        Invoke-AdbChecked -Arguments @("shell", "mv", $finalRemote, $backupRemote) `
            -FailureMessage "Could not preserve the previous Modern folder" -Quiet | Out-Null
    }

    $commitResult = Invoke-AdbCapture -Arguments @("shell", "mv", $script:stagingRemote, $finalRemote)
    if ($commitResult.ExitCode -ne 0) {
        if ($hadExisting) {
            Invoke-AdbCapture -Arguments @("shell", "mv", $backupRemote, $finalRemote) | Out-Null
        }
        throw "Could not activate the copied Modern folder. The previous folder was restored when possible. $($commitResult.Lines | Out-String)"
    }
    $script:stagingRemote = $null
    if ($hadExisting) {
        Invoke-AdbChecked -Arguments @("shell", "rm", "-rf", $backupRemote) `
            -FailureMessage "New Modern models are active, but the temporary old backup could not be removed" -Quiet | Out-Null
    }

    Invoke-AdbChecked -Arguments @("shell", "ls", "$finalRemote/models/gta3.img") `
        -FailureMessage "Final Modern archive verification failed" | Out-Null
    $manifestFile=if ($Profile -eq "Xbox") { "vehicle_models.txt" } else { "vegetation_models.txt" }
    Invoke-AdbChecked -Arguments @("shell", "ls", "$finalRemote/$manifestFile") `
        -FailureMessage "Final profile manifest verification failed" | Out-Null
    Invoke-AdbChecked -Arguments @("shell", "am", "force-stop", $packageName) `
        -FailureMessage "Could not leave Liberty City VR stopped" -Quiet | Out-Null

    Write-Host ""
    Write-Host "$Profile MODELS INSTALLED." -ForegroundColor Green
    Write-Host "Select $Profile under VR MENU > SETTINGS > MODEL ASSETS, then fully restart. Saved profile settings were not changed."
    Write-Host "Diagnostic log: $LogPath"
    Stop-DiagnosticLog
    exit 0
} catch {
    if ($null -ne $script:adb -and -not [string]::IsNullOrWhiteSpace($script:stagingRemote)) {
        try {
            Invoke-AdbCapture -Arguments @("shell", "rm", "-rf", $script:stagingRemote) | Out-Null
        } catch { }
    }
    Write-Host ""
    Write-Host "ERROR: $($_.Exception.Message)" -ForegroundColor Red
    Write-Host "The active $Profile folder was not replaced before a complete verified copy was ready."
    Write-Host "Diagnostic log: $LogPath"
    Stop-DiagnosticLog
    exit 1
}

#!/usr/bin/env bash
# Modern alias of the supported GTA III Xbox Version HD (re3) builder.
set -euo pipefail
SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
ARGS=(build --profile modern)
while [ "$#" -gt 0 ]; do
  case "$1" in
    --source|-Source) ARGS+=(--source "$2"); shift 2 ;;
    --out|-Out) ARGS+=(--out "$2"); shift 2 ;;
    --force|-Force) ARGS+=(--force); shift ;;
    *) echo "Unsupported argument: $1. Use --source for the extracted Xbox Version HD (re3) folder." >&2; exit 1 ;;
  esac
done
exec python3 "$SCRIPT_DIR/xbox-modelset.py" "${ARGS[@]}"

#!/usr/bin/env python3 """Extracts named entries from an IMG v1 archive into a target directory.
Linux port of imgextract.ps1. The IMG v1 directory is a flat list of 32-byte entries: [0:4] sector (u32 LE), [4:8] sector count (u32 LE), [8:32] name (24 bytes, NUL-terminated). Sector size is 2048, so an entry lives at offset = sector*2048 and spans count*2048 bytes.
Usage: imgextract.py --img gta3.img --out outdir --entries name1 name2 ... """ import argparse import os import sys
SECT = 2048
def main(): ap = argparse.ArgumentParser(description=__doc__) ap.add_argument("--img", required=True, help="path to the .img archive") ap.add_argument("--out", required=True, help="target directory for extracted files") ap.add_argument("--entries", nargs="+", required=True, help="entry names to extract (matched case-insensitively)") args = ap.parse_args()
dir_path = os.path.splitext(args.img)[0] + ".dir" if not os.path.isfile(dir_path): sys.exit(f"directory file not found: {dir_path}")
with open(dir_path, "rb") as f: db = f.read() if len(db) % 32 != 0: sys.exit(f"{dir_path} length {len(db)} is not a multiple of 32") n = len(db) // 32
os.makedirs(args.out, exist_ok=True) want = {e.lower() for e in args.entries}
with open(args.img, "rb") as fs: for i in range(n): b = i * 32 # name starts at b+8; find the NUL terminator within the 24-byte field z = db.find(b"\x00", b + 8, b + 32) - (b + 8) if z < 0 or z > 24: z = 24 name = db[b + 8:b + 8 + z].decode("ascii", "replace") if name.lower() not in want: continue off = int.from_bytes(db[b:b + 4], "little") * SECT ln = int.from_bytes(db[b + 4:b + 8], "little") * SECT fs.seek(off) buf = fs.read(ln) out_name = name with open(os.path.join(args.out, out_name), "wb") as o: o.write(buf) print(f"extracted {out_name} ({ln:,} bytes)")
if __name__ == "__main__": main()

# Rebuilds a GTA IMG version 1 archive (gta3.img + gta3.dir), replacing entries
# whose name matches a file supplied on disk. Entries keep their dir order;
# offsets and sizes are recomputed.
param(
    [Parameter(Mandatory=$true)][string]$Img,
    [Parameter(Mandatory=$true)][string[]]$From,
    [string[]]$Exclude = @()
)

# A .NET method that throws -- a full disk, a file the antivirus is holding --
# otherwise ends only its own statement, and the run limps on to the archive
# swap and reports a missing .new file instead of the real cause.
$ErrorActionPreference = "Stop"

$SECTOR = 2048
$dirPath = [System.IO.Path]::ChangeExtension($Img, ".dir")

# collect replacements, later sources win
$repl = @{}
foreach ($src in $From) {
    # -LiteralPath throughout: a game folder named like "GTA Vice City [Rus]"
    # is a wildcard to these cmdlets, and they quietly match nothing.
    if (-not (Test-Path -LiteralPath $src)) { Write-Output "  missing source: $src"; continue }
    foreach ($f in Get-ChildItem -LiteralPath $src -File) {
        if ($f.Extension -notmatch '^\.(dff|txd)$') { continue }
        $repl[$f.Name.ToLower()] = $f.FullName
    }
}
Write-Output ("replacement files offered: {0}" -f $repl.Count)

$db = [System.IO.File]::ReadAllBytes($dirPath)
$n = $db.Length / 32
$entries = @()
for ($i = 0; $i -lt $n; $i++) {
    $b = $i*32
    $z = [Array]::IndexOf($db, [byte]0, $b+8) - ($b+8); if ($z -lt 0 -or $z -gt 24) { $z = 24 }
    $entries += [pscustomobject]@{
        Name   = [System.Text.Encoding]::ASCII.GetString($db, $b+8, $z)
        Offset = [int64][BitConverter]::ToUInt32($db, $b) * $SECTOR
        Size   = [int64][BitConverter]::ToUInt32($db, $b+4) * $SECTOR
    }
}
Write-Output ("archive entries: {0}" -f $entries.Count)

# Optional exact-name pruning is used by the Quest builder to remove expensive
# vegetation geometry from the Modern archive. Missing entries then fall back
# to the user's original Classic gta3.img at runtime.
$excludeSet = @{}
foreach ($name in $Exclude) {
    if (-not [string]::IsNullOrWhiteSpace($name)) {
        $excludeSet[$name.ToLowerInvariant()] = $true
    }
}
if ($excludeSet.Count -gt 0) {
    $beforeExclude = $entries.Count
    $entries = @($entries | Where-Object {
        -not $excludeSet.ContainsKey($_.Name.ToLowerInvariant())
    })
    Write-Output ("archive entries excluded: {0}" -f ($beforeExclude - $entries.Count))
}

$outImg = "$Img.new"

# The rebuild writes a full second copy of the archive beside the original, so
# the drive has to have room for it. Running out halfway is what turns into an
# unhelpful "gta3.img.new does not exist" three statements later.
$needBytes = (Get-Item -LiteralPath $Img).Length
$freeBytes = $null
try {
    $root = [System.IO.Path]::GetPathRoot((Resolve-Path -LiteralPath $Img).ProviderPath)
    $freeBytes = (New-Object System.IO.DriveInfo($root)).AvailableFreeSpace
} catch {
    $freeBytes = $null
}
if ($freeBytes -ne $null -and $freeBytes -lt $needBytes) {
    throw ("Rebuilding '{0}' needs {1:N1} GB free on that drive; {2:N1} GB is available." -f
        $Img, ($needBytes / 1GB), ($freeBytes / 1GB))
}

$in = $null
$out = $null
$newDir = New-Object byte[] ($entries.Count * 32)
$replaced = 0
$used = @{}
$failure = $null
try {
    $in  = [System.IO.File]::OpenRead($Img)
    $out = [System.IO.File]::Create($outImg)
    $buf = New-Object byte[] (8*1024*1024)
    $pad = New-Object byte[] $SECTOR
    $nextSector = [int64]0

    for ($i = 0; $i -lt $entries.Count; $i++) {
        $e = $entries[$i]
        $key = $e.Name.ToLower()
        $written = [int64]0

        if ($repl.ContainsKey($key)) {
            $bytes = [System.IO.File]::ReadAllBytes($repl[$key])
            $out.Write($bytes, 0, $bytes.Length)
            $written = $bytes.Length
            $replaced++
            $used[$key] = $true
        } else {
            $in.Position = $e.Offset
            $left = $e.Size
            while ($left -gt 0) {
                $take = [int][math]::Min($buf.Length, $left)
                $got = $in.Read($buf, 0, $take)
                if ($got -le 0) { break }
                $out.Write($buf, 0, $got)
                $written += $got
                $left -= $got
            }
        }

        $tail = $written % $SECTOR
        if ($tail -ne 0) { $out.Write($pad, 0, $SECTOR - $tail); $written += ($SECTOR - $tail) }
        $sizeSectors = [uint32]($written / $SECTOR)

        $b = $i*32
        [BitConverter]::GetBytes([uint32]$nextSector).CopyTo($newDir, $b)
        [BitConverter]::GetBytes($sizeSectors).CopyTo($newDir, $b+4)
        [System.Text.Encoding]::ASCII.GetBytes($e.Name).CopyTo($newDir, $b+8)
        $nextSector += $sizeSectors
    }
} catch {
    $failure = $_
} finally {
    if ($in) { $in.Close() }
    if ($out) { $out.Close() }
}

if ($failure) {
    # Nothing has been swapped yet, so the archive on disk is still the one we
    # started from. Clear the half-written copy so a retry starts clean.
    if (Test-Path -LiteralPath $outImg) {
        Remove-Item -LiteralPath $outImg -Force -ErrorAction SilentlyContinue
    }
    throw ("Rebuilding '{0}' failed and the original was left untouched: {1}" -f
        $Img, $failure.Exception.Message)
}

[System.IO.File]::WriteAllBytes("$dirPath.new", $newDir)


# The swap goes through a backup, and through .NET rather than Remove-Item and
# Rename-Item. Two reasons, both seen in the wild: those cmdlets treat a path
# as a wildcard, so a folder named like "C:\Users\Bob [PC]" makes them report a
# file that plainly exists as missing; and deleting the original first means
# that if anything removes the rebuilt file between writing it and moving it --
# security software scanning a fresh multi-gigabyte archive is the usual
# suspect -- the archive that was there is gone too, and a 3.5 GB copy has to
# be redone. Here nothing is deleted until its replacement is in place.
function Swap-InPlace([string]$New, [string]$Target) {
    if (-not [System.IO.File]::Exists($New)) {
        throw ("'{0}' was written but is no longer there. Antivirus or a folder-sync client is the usual cause; build outside Downloads and Documents, or exclude the build folder from real-time scanning." -f $New)
    }
    $backup = "$Target.old"
    if ([System.IO.File]::Exists($backup)) { [System.IO.File]::Delete($backup) }
    [System.IO.File]::Move($Target, $backup)
    try {
        [System.IO.File]::Move($New, $Target)
    } catch {
        [System.IO.File]::Move($backup, $Target)
        throw ("Could not put the rebuilt '{0}' in place, the original is back: {1}" -f
            $Target, $_.Exception.Message)
    }
    [System.IO.File]::Delete($backup)
}

if ((Get-Item -LiteralPath $outImg).Length -lt $SECTOR) {
    throw "The rebuilt archive '$outImg' is empty; the original was left untouched."
}
Swap-InPlace $outImg $Img
Swap-InPlace "$dirPath.new" $dirPath

Write-Output ("entries replaced in archive: {0}" -f $replaced)
# @() so that zero or one leftover name still yields an array: the caller may
# run under Set-StrictMode, where .Count on $null or a scalar string throws.
$unused = @($repl.Keys | Where-Object { -not $used.ContainsKey($_) })
Write-Output ("supplied files with no matching entry: {0}" -f $unused.Count)
$unused | Sort-Object | Select-Object -First 20 | ForEach-Object { Write-Output "    $_" }

# Audits every TXD inside an IMG v1 archive and reports which entries contain
# textures that stream badly: uncompressed 24/32-bit, or any texture at 64px+
# with a single mip level. CandidateList is configurable so release builds can
# keep generated state in their private staging directory instead of modifying
# the read-only tools folder or colliding with another build.
param(
  [Parameter(Mandatory=$true)][string]$Img,
  [string]$CandidateList = (Join-Path $PSScriptRoot "txd_candidates.txt")
)
$SECT=2048
$db=[System.IO.File]::ReadAllBytes([System.IO.Path]::ChangeExtension($Img,".dir"))
$n=$db.Length/32
$fs=[System.IO.File]::OpenRead($Img)
$bad=@()
for($i=0;$i -lt $n;$i++){
  $b=$i*32
  $z=[Array]::IndexOf($db,[byte]0,$b+8)-($b+8); if($z -lt 0 -or $z -gt 24){$z=24}
  $name=[System.Text.Encoding]::ASCII.GetString($db,$b+8,$z)
  if($name -notmatch '\.txd$'){continue}
  $off=[int64][BitConverter]::ToUInt32($db,$b)*$SECT
  $len=[int64][BitConverter]::ToUInt32($db,$b+4)*$SECT
  if($len -le 0 -or $len -gt 80MB){continue}
  $fs.Position=$off
  $buf=New-Object byte[] $len
  $r=$fs.Read($buf,0,[int]$len)
  # walk texture natives
  $uncmp=0; $nomip=0; $texs=0; $wasted=[int64]0
  $stack=New-Object System.Collections.Stack
  $stack.Push(@(12,[int64]$r,0))   # skip outer header: pos, end, parent
  $pos=12
  function ScanChunks([byte[]]$data,[int]$start,[long]$end,[uint32]$parent){
    $p=$start
    while($p+12 -le $end){
      $t=[BitConverter]::ToUInt32($data,$p); $s=[BitConverter]::ToUInt32($data,$p+4)
      $de=$p+12+$s
      if($de -gt $end -or $s -eq 0){break}
      if($t -eq 0x01 -and $parent -eq 0x15){
        $w=[BitConverter]::ToUInt16($data,$p+12+80)
        $h=[BitConverter]::ToUInt16($data,$p+12+82)
        $depth=$data[$p+12+84]; $lev=$data[$p+12+85]; $comp=$data[$p+12+87]
        $script:texs++
        $dim=[Math]::Max($w,$h)
        if($comp -eq 0 -and $depth -ge 24){
          $script:uncmp++
          $script:wasted += [int64]$w*$h*($depth/8)
        } elseif($lev -le 1 -and $dim -ge 64){
          $script:nomip++
        }
      } elseif($t -in 0x16,0x15){ ScanChunks $data ($p+12) $de $t }
      $p=$de
    }
  }
  $script:texs=0;$script:uncmp=0;$script:nomip=0;$script:wasted=[int64]0
  ScanChunks $buf 0 $r 0
  if($script:uncmp -gt 0 -or $script:nomip -gt 0){
    $bad += [pscustomobject]@{Name=$name;KB=[math]::Round($len/1KB);Texs=$script:texs;Uncompressed=$script:uncmp;NoMip=$script:nomip;UncmpMB=[math]::Round($script:wasted/1MB,1)}
  }
}
$fs.Close()
Write-Output ("txd entries with problems: {0}" -f $bad.Count)
$bad | Sort-Object UncmpMB -Descending | Select-Object -First 25 | Format-Table -AutoSize
Write-Output ("total uncompressed pixel data: {0:N0} MB" -f (($bad | Measure-Object UncmpMB -Sum).Sum))
Write-Output ("total no-mip textures: {0}" -f (($bad | Measure-Object NoMip -Sum).Sum))
# dump the full list for the extraction step
$bad | ForEach-Object { $_.Name } | Sort-Object -Unique |
  Set-Content -LiteralPath $CandidateList -Encoding ASCII
Write-Output "candidate list written to $CandidateList"

#!/usr/bin/env python3 """Merges TXD dictionaries: keeps every texture from --base, and appends only the textures from --extra whose names are not already in the base. Used to pull a few missing textures out of a pack without inheriting its worse versions of the ones we already have.
Linux port of txdmerge.ps1.
Usage: txdmerge.py --base original.txd --extra pack.txd --out merged.txd """ import argparse import os import struct import sys
def read_txd(path): with open(path, "rb") as f: b = f.read() # outer chunk: type, size, version outer_type, outer_size, version = struct.unpack_from("<III", b, 0) if outer_type != 0x16: raise ValueError(f"{path} is not a texture dictionary (type {outer_type})") pos = 12 # struct chunk s_type, s_size, s_ver = struct.unpack_from("<III", b, pos) if s_type != 0x01: raise ValueError(f"{path} has no struct chunk") num_tex, device_id = struct.unpack_from("<HH", b, pos + 12) pos += 12 + s_size end = 12 + outer_size
tex = [] trailing = [] while pos + 12 <= end: c_type, c_size = struct.unpack_from("<II", b, pos) total = 12 + c_size if c_type == 0x15: # name lives at struct payload +8 (after platformId and filter/addr) name_off = pos + 12 + 12 + 8 z = b.find(b"\x00", name_off) - name_off if z < 0 or z > 32: z = 32 name = b[name_off:name_off + z].decode("ascii", "replace") tex.append((name, b[pos:pos + total])) else: trailing.append(b[pos:pos + total]) pos += total
return { "version": version, "s_ver": s_ver, "num_tex": num_tex, "device_id": device_id, "tex": tex, "trailing": trailing, }
def main(): ap = argparse.ArgumentParser(description=__doc__) ap.add_argument("--base", required=True) ap.add_argument("--extra", required=True) ap.add_argument("--out", required=True) args = ap.parse_args()
bd = read_txd(args.base) ed = read_txd(args.extra) print(f"base : {len(bd['tex'])} textures (declared {bd['num_tex']})") print(f"extra: {len(ed['tex'])} textures (declared {ed['num_tex']})")
have = {t[0].lower() for t in bd["tex"]} add = [t for t in ed["tex"] if t[0].lower() not in have] print(f"adding {len(add)} textures absent from base:") for name, _ in add: print(f" {name}")
all_tex = bd["tex"] + add
# struct chunk body = bytearray() body += struct.pack("<III", 0x01, 4, bd["s_ver"]) body += struct.pack("<HH", len(all_tex), bd["device_id"]) for _, chunk in all_tex: body += chunk for chunk in bd["trailing"]: body += chunk
with open(args.out, "wb") as f: f.write(struct.pack("<III", 0x16, len(body), bd["version"])) f.write(bytes(body)) size_mb = os.path.getsize(args.out) / (1024 * 1024) print(f"wrote {args.out} ({size_mb:.1f} MB, {len(all_tex)} textures)")
if __name__ == "__main__": main()

# Shared adapter: Windows and Unix use the same pinned builder and validation.
function Get-ModelsetPython {
    foreach ($name in @('python', 'python3', 'py')) {
        $command = Get-Command $name -ErrorAction SilentlyContinue
        if ($command) {
            Write-Host "Checking Python 3.9+ ($name)..."
            $process = $null
            try {
                $info = New-Object System.Diagnostics.ProcessStartInfo
                $info.FileName = $command.Source
                $info.Arguments = '-c "import sys; sys.exit(0 if sys.version_info >= (3, 9) else 1)"'
                $info.UseShellExecute = $false
                $info.CreateNoWindow = $true
                $info.RedirectStandardOutput = $true
                $info.RedirectStandardError = $true
                $process = [System.Diagnostics.Process]::Start($info)
                if (-not $process.WaitForExit(5000)) {
                    $process.Kill()
                    Write-Host "$name did not respond within 5 seconds; trying the next launcher."
                    continue
                }
                if ($process.ExitCode -eq 0) { return $command.Source }
            } catch { } finally {
                if ($null -ne $process) { $process.Dispose() }
            }
        }
    }
    throw 'Python 3.9 or later is required. Install Python and add it to PATH.'
}
function Invoke-ModelsetPython {
    param([string[]]$Arguments)
    $python = Get-ModelsetPython
    & $python -u (Join-Path $PSScriptRoot 'xbox-modelset.py') @Arguments | ForEach-Object { Write-Host $_ }
    if ($LASTEXITCODE -ne 0) { throw 'Asset preparation/validation failed. The previous profile was preserved.' }
}
function Test-XboxOverlay([string]$Root) {
    $python = Get-ModelsetPython
    & $python (Join-Path $PSScriptRoot 'xbox-modelset.py') validate --out $Root --profile modern
    return $LASTEXITCODE -eq 0
}

#!/usr/bin/env python3
"""Prepare the pinned GTA III Xbox Version HD re3 pack for Xbox or Modern."""
import argparse
import hashlib
import html
import json
import os
from pathlib import Path
import re
import shutil
import struct
import subprocess
import sys
import time
import urllib.parse
import urllib.request
import uuid
import zipfile

TOOLS = Path(__file__).resolve().parent
PACK = json.loads((TOOLS / 'xbox-pack.json').read_text())
BUILDER_VERSION = PACK['builderVersion']
NAME = re.compile(r'[a-z0-9_@]{1,19}\.(dff|txd)\Z')


def progress(message):
    print(message, flush=True)


def prompt(message):
    # PowerShell forwards native output one line at a time. A bare input()
    # prompt has no newline, so it can be hidden while we wait for the answer.
    progress(message)
    return input()


def report_item(index, total, phase, name):
    if index == 1 or index == total or index % 20 == 0:
        progress(f'{phase}: {index}/{total} - {name}')


def report_bytes(done, total, label, previous, final=False):
    now = time.monotonic()
    if final or now - previous >= 1:
        percent = min(100, done * 100 // total) if total else 0
        progress(f'{label}: {percent}% ({done // (1024 * 1024)}/{total // (1024 * 1024)} MiB)')
        return now
    return previous


def copy_with_progress(source, target, total, label):
    done, previous = 0, 0
    for block in iter(lambda: source.read(1024 * 1024), b''):
        target.write(block)
        done += len(block)
        if total >= 64 * 1024 * 1024:
            previous = report_bytes(done, total, label, previous)
    if total >= 64 * 1024 * 1024:
        report_bytes(done, total, label, previous, final=True)


def sha(path, label=None):
    digest = hashlib.sha256()
    done, previous = 0, 0
    total = Path(path).stat().st_size
    if label:
        progress(label + '...')
    with Path(path).open('rb') as stream:
        for block in iter(lambda: stream.read(1024 * 1024), b''):
            digest.update(block)
            done += len(block)
            if label and total >= 64 * 1024 * 1024:
                previous = report_bytes(done, total, label, previous)
    if label and total >= 64 * 1024 * 1024:
        report_bytes(done, total, label, previous, final=True)
    return digest.hexdigest().upper()


def assert_archive(path):
    if Path(path).stat().st_size != PACK['archiveBytes'] or sha(path, 'Checking source archive SHA256') != PACK['archiveSha256']:
        raise ValueError('Source archive does not match the supported ModDB re3 release (size/SHA256).')


def source_root(path):
    path = Path(path).resolve()
    progress('Locating the supported re3 source folder...')
    candidates = [path] + [p.parent.parent for p in path.rglob('*') if p.name.lower() == 'xbox_vehicles.img']
    valid = {}
    for candidate in candidates:
        files = {p.relative_to(candidate).as_posix().lower(): p for p in candidate.rglob('*') if p.is_file()}
        if all(rel in files for rel in PACK['files']):
            valid[candidate] = files
    if len(valid) != 1:
        raise ValueError('Select the extracted Xbox Version HD (re3) folder; older vehicle packs are unsupported.')
    root, files = next(iter(valid.items()))
    for index, (rel, expected) in enumerate(PACK['files'].items(), 1):
        file = files[rel]
        report_item(index, len(PACK['files']), 'Checking source files', rel)
        label = 'Checking ' + rel if expected['bytes'] >= 64 * 1024 * 1024 else None
        if file.is_symlink() or not file.resolve().is_relative_to(root) or file.stat().st_size != expected['bytes'] or sha(file, label) != expected['sha256']:
            raise ValueError('Source file does not match pinned re3 pack: ' + rel)
    return root, {rel: files[rel] for rel in PACK['files']}


def extract_archive(archive, destination):
    """Extract only allowlisted assets, never executables, saves or scripts."""
    assert_archive(archive)
    destination = Path(destination).resolve()
    destination.mkdir(parents=True, exist_ok=True)
    with zipfile.ZipFile(archive) as source:
        entries = {i.filename.lower(): i for i in source.infolist()}
        for index, rel in enumerate(PACK['files'], 1):
            report_item(index, len(PACK['files']), 'Extracting source files', rel)
            entry = entries.get((PACK['sourceFolder'] + '/' + rel).lower())
            if entry is None:
                raise ValueError('Missing pack entry: ' + rel)
            target = destination / rel
            if target.is_symlink() or not target.resolve().is_relative_to(destination):
                raise ValueError('Unsafe extraction target.')
            target.parent.mkdir(parents=True, exist_ok=True)
            with source.open(entry) as src, target.open('wb') as dst:
                copy_with_progress(src, dst, entry.file_size, 'Extracting ' + rel)
    source_root(destination)


def archive_entries(img, directory, allow_empty=False):
    data = Path(directory).read_bytes()
    length = Path(img).stat().st_size
    if not data or len(data) % 32:
        raise ValueError('Invalid IMG v1 directory length.')
    names = set()
    for sector, count, raw in struct.iter_unpack('<II24s', data):
        name = raw.split(b'\0')[0].decode('ascii').lower()
        if not NAME.fullmatch(name) or name in names or (count < 1 and not allow_empty) or (sector + count) * 2048 > length:
            raise ValueError('Invalid IMG v1 entry: ' + name)
        names.add(name)
        if count == 0:
            continue  # Four unused placeholder models in the pinned base IMG.
        yield name, sector, count


def assert_img(root):
    root = Path(root)
    expected = 0
    for name, sector, count in archive_entries(root / 'models/gta3.img', root / 'models/gta3.dir'):
        if sector != expected:
            raise ValueError('Generated IMG is not compact.')
        expected = sector + count
    if expected * 2048 != (root / 'models/gta3.img').stat().st_size:
        raise ValueError('Unexpected trailing IMG bytes.')


def valid_overlay(root, profile=None, report=False):
    root = Path(root)
    try:
        info = dict(line.split('=', 1) for line in (root / 'BUILD_INFO.txt').read_text().splitlines() if '=' in line)
        if info['Profile'] != 'MODERN' or (profile and info['Profile'] != profile.upper()):
            return False
        if info['BuilderVersion'] != BUILDER_VERSION or info['SourceSHA256'] != PACK['archiveSha256']:
            return False
        hashes = {key[7:]: value for key, value in info.items() if key.startswith('SHA256 ')}
        required = {'models/gta3.img', 'models/gta3.dir', 'models/generic/player.bmp', 'vegetation_models.txt', 'vehicle_models.txt', 'asset_categories.json'}
        if not required <= hashes.keys():
            return False
        actual = {p.relative_to(root).as_posix() for p in root.rglob('*') if p.is_file()}
        if actual != set(hashes) | {'BUILD_INFO.txt'}:
            return False
        for index, (rel, digest) in enumerate(hashes.items(), 1):
            p = root / rel
            if report:
                report_item(index, len(hashes), 'Verifying output files', rel)
            label = 'Verifying ' + rel if report and p.is_file() and p.stat().st_size >= 64 * 1024 * 1024 else None
            if not p.resolve().is_relative_to(root.resolve()) or p.is_symlink() or sha(p, label) != digest:
                return False
        assert_img(root)
        return True
    except (OSError, ValueError, KeyError, UnicodeError):
        return False


def remove_temporary(path, parent):
    path, parent = Path(path).absolute(), Path(parent).resolve()
    if path.parent.resolve() != parent or not re.fullmatch(r'\.xbox\.(build|source|previous)-[0-9a-f]+', path.name):
        raise ValueError('Unexpected temporary path.')
    if path.exists() and not path.is_symlink():
        shutil.rmtree(path)


def replace_directory(fresh, output, backup):
    existed = output.exists()
    if existed:
        output.rename(backup)
    try:
        fresh.rename(output)
    except OSError:
        if existed:
            backup.rename(output)
        raise
    remove_temporary(backup, output.parent)


def compressor_path():
    bundled = TOOLS / ('txdcompress.exe' if os.name == 'nt' else 'txdcompress')
    if bundled.is_file():
        return str(bundled)
    raise ValueError('Build tools/modelsets/txdcompress.cpp first; texture conversion is required.')


def repair_wheel_texture_references(path):
    """Repair the pinned pack's absent wheel-back texture using its stock rim art.

    Only TEXTURE name strings are changed, keeping geometry, UVs, masks and
    chunk sizes intact. The matching stock wheel_lightvan64 lives in MISC.TXD.
    """
    data = bytearray(Path(path).read_bytes())
    missing, fallback = b'wheel_lightvan64back', b'wheel_lightvan64'
    repaired = 0

    def visit(begin, end):
        nonlocal repaired
        offset = begin
        while offset < end:
            if offset + 12 > end:
                raise ValueError('Truncated shared wheel chunk header.')
            kind, size, _ = struct.unpack_from('<III', data, offset)
            start, stop = offset + 12, offset + 12 + size
            if stop > end:
                raise ValueError('Truncated shared wheel chunk payload.')
            if kind == 6:  # TEXTURE: STRUCT followed by name STRING and mask STRING.
                child = start
                while child < stop:
                    if child + 12 > stop:
                        raise ValueError('Truncated wheel texture chunk.')
                    tag, length, _ = struct.unpack_from('<III', data, child)
                    value = child + 12
                    if value + length > stop:
                        raise ValueError('Truncated wheel texture string.')
                    if tag == 2:
                        if bytes(data[value:value+length]).split(b'\0')[0] == missing:
                            data[value:value+length] = fallback.ljust(length, b'\0')
                            repaired += 1
                        break  # The second STRING is the mask, never an alias.
                    child = value + length
            elif kind in (16, 26, 15, 8, 7):  # CLUMP/GEOLIST/GEOMETRY/MATLIST/MATERIAL
                visit(start, stop)
            offset = stop

    visit(0, len(data))
    Path(path).write_bytes(data)
    return repaired


def build(source, output, force=False, compressor=None, profile='modern'):
    profile = profile.lower()
    output_path = Path(output)
    linked_output = output_path.is_symlink()
    source, output = Path(source).resolve(), output_path.resolve()
    if profile != 'modern' or output.name != profile or linked_output or source == output or source in output.parents or output in source.parents:
        raise ValueError('Use a separate output folder named modern; Xbox is a retired selection.')
    if output.exists():
        marker = output / 'BUILD_INFO.txt'
        if not force or not marker.is_file() or ('Profile=' + profile.upper()) not in marker.read_text().splitlines():
            raise ValueError('Refusing to replace a folder without --force and its generated profile marker.')
    _, files = source_root(source)
    progress('Source verified. Preparing the ' + profile.upper() + ' overlay...')
    compressor = str(compressor or compressor_path())
    output.parent.mkdir(parents=True, exist_ok=True)
    token = uuid.uuid4().hex
    stage = output.parent / ('.xbox.build-' + token)
    work = output.parent / ('.xbox.source-' + token)
    backup = output.parent / ('.xbox.previous-' + token)
    stage.mkdir()
    work.mkdir()
    try:
        # Later CDIMAGE packs supersede the base archive; choose one authored
        # DFF/TXD per name before converting textures for the mobile GPU.
        selected = {}
        for archive in PACK['archives']:
            progress('Reading archive directory: ' + archive)
            img = files['models/' + archive + '.img']
            for name, sector, count in archive_entries(img, files['models/' + archive + '.dir'], allow_empty=True):
                selected[name] = (img, sector, count)
        handles = {}
        try:
            for index, (name, (img, sector, count)) in enumerate(sorted(selected.items()), 1):
                report_item(index, len(selected), 'Staging model and texture entries', name)
                if img not in handles:
                    handles[img] = img.open('rb')
                stream = handles[img]
                stream.seek(sector * 2048)
                (work / name).write_bytes(stream.read(count * 2048))
        finally:
            for stream in handles.values():
                stream.close()
        for rel, file in files.items():
            if file.suffix.lower() in ('.img', '.dir'):
                continue
            target = stage / rel
            target.parent.mkdir(parents=True, exist_ok=True)
            shutil.copyfile(file, target)
        wheels = stage / 'models/generic/wheels.dff'
        if wheels.is_file():
            repaired = repair_wheel_texture_references(wheels)
            progress(f'Repaired {repaired} missing shared wheel texture references.')
        txds = sorted(list(work.glob('*.txd')) + list(stage.rglob('*.txd')))
        for index, txd in enumerate(txds, 1):
            report_item(index, len(txds), 'Converting textures', txd.name)
            result = subprocess.run([compressor, '--cap', '1024', str(txd)], stdout=subprocess.PIPE, stderr=subprocess.STDOUT)
            if result.returncode:
                raise ValueError('Texture conversion failed: ' + txd.name)
        models = stage / 'models'
        models.mkdir(exist_ok=True)
        with (models / 'gta3.img').open('wb') as img, (models / 'gta3.dir').open('wb') as directory:
            sector = 0
            entries = sorted(work.iterdir())
            for index, file in enumerate(entries, 1):
                report_item(index, len(entries), 'Writing merged IMG', file.name)
                data = file.read_bytes()
                size = (len(data) + 2047) // 2048
                directory.write(struct.pack('<II24s', sector, size, file.name.encode('ascii')))
                img.write(data)
                img.write(b'\0' * (size * 2048 - len(data)))
                sector += size
        # These authored IDE dictionaries identify vegetation, including model
        # names without the word "tree". The default remains Classic vegetation.
        vegetation = set()
        for rel, file in files.items():
            if rel.endswith('.ide'):
                for line in file.read_text(encoding='cp1252').splitlines():
                    fields = [x.strip().lower() for x in line.split(',')]
                    if len(fields) >= 4 and fields[0].isdigit() and fields[2] in ('trees', 'trees2', 'tree1', 'tree2'):
                        vegetation.add(fields[1])
        vehicles = {name[:-4] for name, (img, _, _) in selected.items() if img.stem.lower() == 'xbox_vehicles' and name.endswith('.dff')}
        for name, values in [('vegetation', vegetation), ('vehicle', vehicles)]:
            (stage / (name + '_models.txt')).write_text('\n'.join(sorted(values)) + '\n')
        categories = {'archives': PACK['archives'], 'entries': len(selected), 'vehicles': len(vehicles), 'vegetation': len(vegetation),
                      'world': 'World models/textures, map IDE/IPL/COL, HUD/fonts/particles and splash textures',
                      'peds': 'Player and pedestrian models/textures, including the matching default Claude skin bitmap',
                      'weapons': 'GTA III weapon model IDs and their texture dictionaries',
                      'excluded': 'PC binaries, scripts, settings, saves, audio, skins, neo renderer configuration; retail vehicle collisions retained'}
        (stage / 'asset_categories.json').write_text(json.dumps(categories, indent=2) + '\n')
        lines = ['Profile=' + profile.upper(), 'BuilderVersion=' + BUILDER_VERSION, 'SourceSHA256=' + PACK['archiveSha256']]
        output_files = sorted(p for p in stage.rglob('*') if p.is_file())
        for index, file in enumerate(output_files, 1):
            rel = file.relative_to(stage).as_posix()
            report_item(index, len(output_files), 'Recording output checksums', rel)
            lines.append('SHA256 ' + rel + '=' + sha(file, 'Hashing ' + rel if file.stat().st_size >= 64 * 1024 * 1024 else None))
        (stage / 'BUILD_INFO.txt').write_text('\n'.join(lines) + '\n')
        if not valid_overlay(stage, profile, report=True):
            raise ValueError('Completed overlay failed validation.')
        progress('Verification passed. Activating the completed local profile...')
        replace_directory(stage, output, backup)
        print(f'{profile.upper()} profile built and verified: {len(selected)} archive entries, {len(vehicles)} vehicles, {len(vegetation)} vegetation models.')
    finally:
        remove_temporary(stage, output.parent)
        remove_temporary(work, output.parent)


def download(destination):
    """Resolve fresh official mirrors; never silently substitute an older pack."""
    destination = Path(destination)
    if destination.is_file():
        assert_archive(destination)
        return
    progress('Requesting an official ModDB download mirror (timeout: 30 seconds)...')
    with urllib.request.urlopen(PACK['downloadPage'], timeout=30) as response:
        page = response.read(2 * 1024 * 1024).decode('utf-8', errors='replace')
    mirrors = re.findall(r'''href=["']([^"']*/downloads/mirror/224588/[^"']+)''', page)
    if not mirrors:
        raise ValueError('ModDB did not provide a download mirror. Download from ' + PACK['page'] + ' and pass --archive.')
    partial = destination.with_name(destination.name + '.partial')
    url = urllib.parse.urljoin(PACK['downloadPage'], html.unescape(mirrors[0]))
    if urllib.parse.urlparse(url).hostname not in ('www.moddb.com', 'moddb.com'):
        raise ValueError('Unexpected ModDB mirror link.')
    progress('Downloading the 1.45 GB re3 pack from ModDB...')
    with urllib.request.urlopen(url, timeout=60) as response, partial.open('wb') as stream:
        copy_with_progress(response, stream, PACK['archiveBytes'], 'Downloading archive')
    assert_archive(partial)
    partial.replace(destination)


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('command', choices=('build', 'prepare', 'validate'))
    parser.add_argument('--source')
    parser.add_argument('--archive')
    parser.add_argument('--out', required=True)
    parser.add_argument('--profile', choices=('xbox', 'modern'), default='modern')
    parser.add_argument('--work-dir')
    parser.add_argument('--force', action='store_true')
    parser.add_argument('--accept-downloads', action='store_true')
    parser.add_argument('--non-interactive', action='store_true')
    args = parser.parse_args()
    if args.profile == 'xbox':
        args.profile = 'modern'  # Backward-compatible command alias, one output.

    if args.command == 'validate':
        return 0 if valid_overlay(args.out, args.profile) else 1
    progress('Asset preparation started: ' + args.profile.upper())
    if args.command == 'build':
        if not args.source:
            parser.error('--source is required to build')
        build(args.source, args.out, args.force, profile=args.profile)
        return 0
    explicit = bool(args.source or args.archive)
    if not explicit:
        progress('Checking for an existing verified local profile...')
    if not explicit and valid_overlay(args.out, args.profile, report=True):
        print('Reusing the complete verified ' + args.profile.upper() + ' profile.')
        return 0
    if not args.work_dir:
        parser.error('--work-dir is required to prepare')
    work = Path(args.work_dir).resolve()
    downloads = work / 'downloads'
    downloads.mkdir(parents=True, exist_ok=True)
    source = args.source
    if not source:
        archive = Path(args.archive).resolve() if args.archive else downloads / PACK['archiveName']
        progress('Looking for source archive: ' + str(archive))
        if not archive.exists():
            accept = args.accept_downloads
            if not accept and not args.non_interactive:
                accept = prompt('Download Xbox Version HD (re3), 1.45 GB, from ModDB? [y/N]').lower() == 'y'
            if accept:
                try:
                    download(archive)
                except (OSError, ValueError) as error:
                    raise ValueError('Automatic download unavailable. Use --archive with the release from ' + PACK['page']) from error
            elif not args.non_interactive:
                archive = Path(prompt('Path to ' + PACK['archiveName'] + ':').strip().strip('"'))
        assert_archive(archive)
        source = work / 'sources' / PACK['archiveSha256'][:16]
        try:
            source_root(source)
        except (OSError, ValueError):
            extract_archive(archive, source)
    build(source, args.out, True, profile=args.profile)
    return 0


if __name__ == '__main__':
    try:
        sys.exit(main())
    except (OSError, ValueError, subprocess.CalledProcessError) as error:
        print('ERROR: ' + str(error), file=sys.stderr)
        sys.exit(1)

# Prepare and optionally install Xbox/Modern from the pinned ModDB re3 release.
[CmdletBinding()]
param(
    [string]$GameDir,
    [string]$WorkDir = 'C:\LCVRBuild\modern-assets',
    [string]$OutputDir,
    [ValidateSet('Xbox', 'Modern', 'Both')][string]$Profile = 'Modern',
    [string]$AndroidSdk,
    [string]$Serial,
    [string]$XboxArchive,
    [string]$XboxSource,
    [string]$HdArchive,
    [string]$ModsArchive,
    [string]$ModernArchive,
    [switch]$SkipXbox,
    [switch]$XboxOnly,
    [switch]$ModernOnly,
    [switch]$BuildOnly,
    [switch]$AcceptDownloads,
    [switch]$NonInteractive,
    [string]$LogPath = (Join-Path $env:TEMP 'LibertyCityVR-Prepare-Modern-Models.log')
)
$ErrorActionPreference = 'Stop'
. (Join-Path $PSScriptRoot 'device-diagnostics.ps1')
. (Join-Path $PSScriptRoot 'modelsets/xbox-modelset.ps1')
try {
    Initialize-PrivateDiagnosticLog
    if ($ModsArchive) { throw 'The old two-pack Modern workflow is retired. Supply the re3 pack using -XboxArchive or -ModernArchive.' }
    if ($XboxOnly) { $Profile = 'Modern' }
    if ($ModernOnly -or $SkipXbox) { $Profile = 'Modern' }
    if ($Profile -ne 'Modern') { Write-Host 'Xbox/Both are legacy aliases; preparing the single Modern (Xbox HD) profile.' }
    $Profile = 'Modern'
    if (-not $GameDir) {
        if ($NonInteractive) { throw '-GameDir is required in non-interactive mode.' }
        $GameDir = Read-Host 'Original GTA III PC folder'
    }
    $game = (Resolve-Path -LiteralPath $GameDir).Path
    foreach ($rel in @('models/gta3.img', 'models/gta3.dir')) {
        if (-not (Test-Path -LiteralPath (Join-Path $game $rel) -PathType Leaf)) { throw "Original GTA III installation is missing $rel" }
    }
    $archive = $XboxArchive
    if (-not $archive) { $archive = $ModernArchive }
    if (-not $archive) { $archive = $HdArchive }
    $profiles = @('Modern')
    Write-Host "Preparing $Profile assets. Existing headset profiles stay in place until a verified replacement is ready."
    Write-Host "Work folder: $WorkDir"
    Write-Host "Diagnostic log: $LogPath"
    # Finish and validate all requested builds before contacting a device.
    $outputs = @{}
    foreach ($target in $profiles) {
        $name = $target.ToLowerInvariant()
        $out = if ($OutputDir) { [IO.Path]::GetFullPath($OutputDir) } else { Join-Path $game "modelsets/$name" }
        Write-Host "==> Preparing $target profile: $out"
        $arguments = @('prepare', '--profile', $name, '--out', $out, '--work-dir', $WorkDir)
        if ($XboxSource) { $arguments += @('--source', $XboxSource) }
        if ($archive) { $arguments += @('--archive', $archive) }
        if ($AcceptDownloads) { $arguments += '--accept-downloads' }
        if ($NonInteractive) { $arguments += '--non-interactive' }
        Invoke-ModelsetPython -Arguments $arguments
        $outputs[$target] = $out
    }
    if (-not $BuildOnly) {
        foreach ($target in $profiles) {
            $options = @{ ModernDir = $outputs[$target]; Profile = $target; NonInteractive = $NonInteractive }
            if ($AndroidSdk) { $options.AndroidSdk = $AndroidSdk }
            if ($Serial) { $options.Serial = $Serial }
            & (Join-Path $PSScriptRoot 'install-modern-models.ps1') @options
            if (-not $?) { throw "$target installation failed." }
        }
        Write-Host 'Requested profiles installed. Select Classic or Modern in MODEL ASSETS, then fully restart. Saved selections were preserved.'
    } else {
        Write-Host 'Requested profiles built and verified; no device commands were sent.'
    }
} catch {
    Write-Host ("ERROR: " + (Protect-DeviceDiagnostic $_.Exception.Message)) -ForegroundColor Red
    exit 1
} finally {
    $script:diagnosticLogEnabled = $false
}

#!/usr/bin/env bash
# Prepare the same pinned GTA III re3 pack for either runtime profile.
set -euo pipefail
SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
GAME_DIR=""; WORK_DIR="$HOME/LCVRBuild/modern-assets"; OUTPUT_DIR=""; PROFILE=modern
ARCHIVE=""; SOURCE=""; BUILD_ONLY=0; ACCEPT=0; NONINTERACTIVE=0; INSTALL_ARGS=()
LOG_PATH="${TMPDIR:-/tmp}/LibertyCityVR-Prepare-Modern-Models.log"
while [ "$#" -gt 0 ]; do
  case "$1" in
    --game-dir|-GameDir) GAME_DIR="$2"; shift 2 ;;
    --work-dir|-WorkDir) WORK_DIR="$2"; shift 2 ;;
    --output-dir|-OutputDir) OUTPUT_DIR="$2"; shift 2 ;;
    --profile|-Profile) PROFILE="${2,,}"; shift 2 ;;
    --xbox-archive|-XboxArchive|--modern-archive|-ModernArchive|--hd-archive|-HdArchive) ARCHIVE="$2"; shift 2 ;;
    --xbox-source|-XboxSource) SOURCE="$2"; shift 2 ;;
    --mods-archive|-ModsArchive) echo 'The old two-pack workflow is retired. Supply the re3 pack with --xbox-archive.' >&2; exit 1 ;;
    --xbox-only|-XboxOnly) PROFILE=modern; shift ;;
    --modern-only|-ModernOnly|--skip-xbox|-SkipXbox) PROFILE=modern; shift ;;
    --android-sdk|-AndroidSdk|--serial|-Serial) INSTALL_ARGS+=("$1" "$2"); shift 2 ;;
    --build-only|-BuildOnly) BUILD_ONLY=1; shift ;;
    --accept-downloads|-AcceptDownloads) ACCEPT=1; shift ;;
    --non-interactive|-NonInteractive) NONINTERACTIVE=1; INSTALL_ARGS+=(--non-interactive); shift ;;
    --log-path|-LogPath) LOG_PATH="$2"; shift 2 ;;
    --help|-h) echo 'Prepare Xbox Version HD (re3): --game-dir DIR [--profile modern] [--xbox-archive ZIP] [--build-only]'; exit 0 ;;
    *) echo "Unknown option: $1" >&2; exit 1 ;;
  esac
done
case "$PROFILE" in xbox|modern|both) ;; *) echo 'Profile must be xbox, modern or both.' >&2; exit 1 ;; esac
[ "$PROFILE" = modern ] || echo 'Xbox/Both are legacy aliases for the single Modern (Xbox HD) profile.'
PROFILE=modern
if [ -z "$GAME_DIR" ] && [ "$NONINTERACTIVE" -eq 0 ]; then read -r -p 'Original GTA III PC folder: ' GAME_DIR; fi
[ -n "$GAME_DIR" ] && [ -f "$GAME_DIR/models/gta3.img" ] && [ -f "$GAME_DIR/models/gta3.dir" ] || { echo 'Select an original GTA III installation with --game-dir.' >&2; exit 1; }
mkdir -p "$(dirname "$LOG_PATH")"
exec > >(tee "$LOG_PATH") 2>&1
PROFILES=("$PROFILE")

OUTPUTS=()
for target in "${PROFILES[@]}"; do
  out="${OUTPUT_DIR:-$GAME_DIR/modelsets/$target}"
  ARGS=(prepare --profile "$target" --out "$out" --work-dir "$WORK_DIR")
  [ -z "$ARCHIVE" ] || ARGS+=(--archive "$ARCHIVE")
  [ -z "$SOURCE" ] || ARGS+=(--source "$SOURCE")
  [ "$ACCEPT" -eq 0 ] || ARGS+=(--accept-downloads)
  [ "$NONINTERACTIVE" -eq 0 ] || ARGS+=(--non-interactive)
  python3 "$SCRIPT_DIR/modelsets/xbox-modelset.py" "${ARGS[@]}"
  OUTPUTS+=("$out")
done
if [ "$BUILD_ONLY" -eq 1 ]; then
  echo 'Requested profiles built and verified; no device commands were sent.'
else
  for i in "${!PROFILES[@]}"; do
    bash "$SCRIPT_DIR/install-modern-models.sh" --profile "${PROFILES[$i]}" --modern-dir "${OUTPUTS[$i]}" "${INSTALL_ARGS[@]}"
  done
  echo 'Requested profiles installed. Select Classic or Modern in MODEL ASSETS, then fully restart. Saved selections were preserved.'
fi

#!/usr/bin/env python3
"""Reject device identifiers and local private values without printing them."""

import argparse
from pathlib import Path
import re
import subprocess
import sys


RULES = (
    ("Quest device identifier", re.compile(rb"(?<![A-Za-z0-9])2G[A-Z0-9]{12}(?![A-Za-z0-9])", re.I)),
    ("private Tailscale hostname", re.compile(rb"\b[A-Za-z0-9.-]+\.ts\.net\b", re.I)),
)
OID = re.compile(r"[0-9a-f]{40}(?:[0-9a-f]{24})?\Z")


class PrivacyError(Exception):
    pass


def git(*args, data=None):
    result = subprocess.run(
        ["git", *args], input=data, stdout=subprocess.PIPE, stderr=subprocess.PIPE
    )
    if result.returncode:
        raise PrivacyError("Git operation failed; diagnostics suppressed for privacy.")
    return result.stdout


def denylist():
    path = Path(git("rev-parse", "--git-path", "info/privacy-denylist").decode().strip())
    if not path.exists():
        return ()
    return tuple(line for line in path.read_bytes().splitlines() if line)


def check(data, private_values):
    for label, pattern in RULES:
        if pattern.search(data):
            raise PrivacyError("Blocked sensitive data: " + label + ". Matched text suppressed.")
    if any(value.lower() in data.lower() for value in private_values):
        raise PrivacyError("Blocked a locally configured private value. Matched text suppressed.")


def scan_objects(object_ids, private_values):
    """Inspect complete blobs and commit/tag metadata, including binary blobs."""
    process = subprocess.Popen(
        ["git", "cat-file", "--batch"], stdin=subprocess.PIPE,
        stdout=subprocess.PIPE, stderr=subprocess.DEVNULL
    )
    try:
        for object_id in sorted(set(object_ids)):
            if not OID.fullmatch(object_id):
                raise PrivacyError("Invalid object reference; scan stopped.")
            process.stdin.write((object_id + "\n").encode())
            process.stdin.flush()
            header = process.stdout.readline().split()
            if len(header) != 3 or header[1] not in (b"blob", b"commit", b"tag", b"tree"):
                raise PrivacyError("Unable to read a Git object; scan stopped.")
            size = int(header[2])
            content = process.stdout.read(size)
            if len(content) != size or process.stdout.read(1) != b"\n":
                raise PrivacyError("Incomplete Git object; scan stopped.")
            # Tree data covers every historical filename, even when rev-list
            # deduplicates a blob reused under a different name.
            check(content, private_values)
    finally:
        process.stdin.close()
        process.stdout.close()
        if process.poll() is None:
            process.terminate()
        process.wait()


def staged(private_values):
    objects = []
    for record in git("ls-files", "--stage", "-z").split(b"\0"):
        if not record:
            continue
        metadata, path = record.split(b"\t", 1)
        mode, object_id, stage = metadata.split()
        if stage != b"0":
            raise PrivacyError("Unmerged index; privacy scan stopped.")
        check(path, private_values)
        if mode != b"160000":
            objects.append(object_id.decode())
    scan_objects(objects, private_values)


def history(private_values, tips=None):
    if tips is None:
        objects = git("rev-list", "--objects", "--all")
    elif not tips:
        return
    else:
        objects = git("rev-list", "--objects", "--stdin", data=("\n".join(tips) + "\n").encode())
    ids = []
    for line in objects.splitlines():
        object_id, _, path = line.partition(b" ")
        check(path, private_values)
        ids.append(object_id.decode())
    scan_objects(ids, private_values)


def pre_push(private_values, lines):
    tips = []
    for line in lines:
        fields = line.split()
        if len(fields) != 4:
            raise PrivacyError("Invalid push input; privacy scan stopped.")
        local_ref, local_oid, remote_ref, remote_oid = fields
        if not OID.fullmatch(local_oid) or not OID.fullmatch(remote_oid):
            raise PrivacyError("Invalid push object; privacy scan stopped.")
        if set(local_oid) == {"0"}:
            continue
        if not remote_ref.startswith(("refs/heads/", "refs/tags/")):
            raise PrivacyError("Publishing local checkpoint or other private refs is blocked.")
        check((local_ref + " " + remote_ref).encode(), private_values)
        tips.append(local_oid)
    history(private_values, tips)


def install_hooks():
    root = Path(git("rev-parse", "--show-toplevel").decode().strip())
    for hook in ("pre-commit", "commit-msg", "pre-push"):
        if not (root / ".githooks" / hook).is_file():
            raise PrivacyError("Tracked privacy hooks are missing; installation stopped.")
    existing = subprocess.run(
        ["git", "config", "--get", "core.hooksPath"],
        stdout=subprocess.PIPE, stderr=subprocess.PIPE
    )
    if existing.returncode not in (0, 1):
        raise PrivacyError("Unable to inspect hook configuration.")
    if existing.stdout.strip() not in (b"", b".githooks"):
        raise PrivacyError("An existing custom hook path requires review before installation.")
    git("config", "--local", "privacy.python", sys.executable)
    git("config", "--local", "core.hooksPath", ".githooks")


def main(argv=None):
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("mode", choices=("staged", "message", "history", "pre-push", "install-hooks"))
    parser.add_argument("message_file", nargs="?")
    args = parser.parse_args(argv)
    try:
        if args.mode == "install-hooks":
            install_hooks()
        else:
            values = denylist()
            if args.mode == "staged":
                staged(values)
            elif args.mode == "message":
                if not args.message_file:
                    raise PrivacyError("A commit message file is required.")
                check(Path(args.message_file).read_bytes(), values)
            elif args.mode == "history":
                history(values)
            else:
                pre_push(values, sys.stdin.read().splitlines())
    except (PrivacyError, OSError, ValueError):
        # Never include exception text: a filename, Git error or value may be private.
        print("Privacy check failed. Sensitive content and diagnostic values are suppressed.", file=sys.stderr)
        return 1
    print("Privacy check passed.")
    return 0


if __name__ == "__main__":
    sys.exit(main())

param(
 [Parameter(Mandatory=$true)][string]$GameDataRoot,
 [string[]]$Models = @('sentinel.dff','admiral.dff','stinger.dff','oceanic.dff'),
 [switch]$IncludeModern,
 [string]$OutJson = ''
)
# Read-only metadata inspector for the user's local GTA IMG/DIR archives.
# It emits counts, frame/material metadata and source offsets, never DFF/TXD
# files or vertex/index buffers. No game data is copied into a public kit.
$ErrorActionPreference='Stop'
function Get-RwChildren([byte[]]$Data,[int]$Start,[int]$End) {
 $cursor=$Start
 while($cursor+12 -le $End){
  $kind=[BitConverter]::ToUInt32($Data,$cursor)
  $length=[BitConverter]::ToUInt32($Data,$cursor+4)
  $body=$cursor+12
  $finish=$body+[long]$length
  if($finish -gt $End -or $finish -le $cursor){ throw "Invalid RenderWare chunk at$cursor" }
  [pscustomobject]@{Id=$kind;Start=$cursor;Body=$body;End=[int]$finish;Size=$length}
  $cursor=[int]$finish
 }
}
function Get-RwString([byte[]]$Data,$Chunk) {
 $value=[Text.Encoding]::ASCII.GetString($Data,$Chunk.Body,$Chunk.Size)
 $nul=$value.IndexOf([char]0)
 if($nul -ge 0){$value.Substring(0,$nul)}else{$value}
}
function Get-Material([byte[]]$Data,$Chunk) {
 $children=@(Get-RwChildren $Data $Chunk.Body $Chunk.End)
 $structure=@($children | Where-Object Id -eq 1)[0]
 if($structure.Size -lt 16){ throw 'Short material structure.' }
 $color=@($Data[($structure.Body+4)..($structure.Body+7)] | ForEach-Object {[int]$_})
 $textureName='';$maskName=''
 $texture=@($children | Where-Object Id -eq 6)
 if($texture.Count){
  $textureChildren=@(Get-RwChildren $Data $texture[0].Body $texture[0].End)
  $names=@($textureChildren | Where-Object Id -eq 2)
  if($names.Count -gt 0){$textureName=Get-RwString $Data $names[0]}
  if($names.Count -gt 1){$maskName=Get-RwString $Data $names[1]}
 }
 [pscustomobject]@{rgba=$color;texture=$textureName;mask=$maskName}
}
function Get-Geometry([byte[]]$Data,$Chunk,[int]$Index) {
 $children=@(Get-RwChildren $Data $Chunk.Body $Chunk.End)
 $structure=@($children | Where-Object Id -eq 1)[0]
 if($structure.Size -lt 16){ throw 'Short geometry structure.' }
 $materials=[Collections.Generic.List[object]]::new()
 $materialList=@($children | Where-Object Id -eq 8)
 if($materialList.Count){
  $materialChunks=@(Get-RwChildren $Data $materialList[0].Body $materialList[0].End)
  $materialHeader=@($materialChunks | Where-Object Id -eq 1)[0]
  $count=[BitConverter]::ToInt32($Data,$materialHeader.Body)
  if($count -lt 0 -or $count -gt 4096 -or $materialHeader.Size -lt 4+4*$count){throw 'Invalid material list.'}
  $unique=@($materialChunks | Where-Object Id -eq 7);$next=0
  for($m=0;$m -lt $count;++$m){
   $reference=[BitConverter]::ToInt32($Data,$materialHeader.Body+4+4*$m)
   if($reference -eq -1){$materials.Add((Get-Material $Data $unique[$next]));++$next}
   elseif($reference -ge 0 -and $reference -lt $materials.Count){$materials.Add($materials[$reference])}
   else{throw 'Invalid material reference.'}
  }
 }
 [pscustomobject]@{
  index=$Index;flags=[BitConverter]::ToUInt32($Data,$structure.Body)
  triangles=[BitConverter]::ToUInt32($Data,$structure.Body+4)
  vertices=[BitConverter]::ToUInt32($Data,$structure.Body+8)
  morphTargets=[BitConverter]::ToUInt32($Data,$structure.Body+12)
  materials=@($materials.ToArray())
 }
}
function Get-DffMetadata([byte[]]$Data) {
 if([BitConverter]::ToUInt32($Data,0) -ne 16){throw 'Expected a RenderWare clump.'}
 $end=12+[BitConverter]::ToUInt32($Data,4)
 if($end -gt $Data.Length){throw 'Clump exceeds IMG record.'}
 $children=@(Get-RwChildren $Data 12 $end)
 $frameChunk=@($children | Where-Object Id -eq 14)[0]
 $frameChildren=@(Get-RwChildren $Data $frameChunk.Body $frameChunk.End)
 $frameHeader=@($frameChildren | Where-Object Id -eq 1)[0]
 $frameCount=[BitConverter]::ToInt32($Data,$frameHeader.Body)
 if($frameCount -lt 0 -or $frameCount -gt 4096 -or $frameHeader.Size -lt 4+56*$frameCount){throw 'Invalid frame list.'}
 $extensions=@($frameChildren | Where-Object Id -eq 3)
 $frames=[Collections.Generic.List[object]]::new()
 for($f=0;$f -lt $frameCount;++$f){
  $base=$frameHeader.Body+4+56*$f;$name=''
  if($f -lt $extensions.Count){
   $plugins=@(Get-RwChildren $Data $extensions[$f].Body $extensions[$f].End)
   $nodeName=@($plugins | Where-Object Id -eq 0x0253F2FE)
   if($nodeName.Count){$name=Get-RwString $Data $nodeName[0]}
  }
  $transform=@(0..11 | ForEach-Object {[BitConverter]::ToSingle($Data,$base+4*$_)})
  $frames.Add([pscustomobject]@{index=$f;name=$name;parent=[BitConverter]::ToInt32($Data,$base+48);localTransform=$transform})
 }
 $geometryList=@($children | Where-Object Id -eq 26)[0]
 $geometryChildren=@(Get-RwChildren $Data $geometryList.Body $geometryList.End)
 $geometryChunks=@($geometryChildren | Where-Object Id -eq 15)
 $geometries=[Collections.Generic.List[object]]::new()
 for($g=0;$g -lt $geometryChunks.Count;++$g){$geometries.Add((Get-Geometry $Data $geometryChunks[$g] $g))}
 $atomics=[Collections.Generic.List[object]]::new()
 foreach($atomic in @($children | Where-Object Id -eq 20)){
  $atomicChildren=@(Get-RwChildren $Data $atomic.Body $atomic.End)
  $atomicHeader=@($atomicChildren | Where-Object Id -eq 1)[0]
  $frame=[BitConverter]::ToInt32($Data,$atomicHeader.Body)
  $geometry=[BitConverter]::ToInt32($Data,$atomicHeader.Body+4)
  if($frame -lt 0 -or $frame -ge $frames.Count -or $geometry -lt 0 -or $geometry -ge $geometries.Count){throw 'Invalid atomic frame/geometry reference.'}
  $atomics.Add([pscustomobject]@{index=$atomics.Count;frame=$frame;frameName=$frames[$frame].name;geometry=$geometry;flags=[BitConverter]::ToUInt32($Data,$atomicHeader.Body+8)})
 }
 [pscustomobject]@{
  clumpBytes=$end;totalVertices=($geometries | Measure-Object -Property vertices -Sum).Sum
  totalTriangles=($geometries | Measure-Object -Property triangles -Sum).Sum
  frames=@($frames.ToArray());geometries=@($geometries.ToArray());atomics=@($atomics.ToArray())
 }
}
$sets=[Collections.Generic.List[string]]::new();$sets.Add('models')
if($IncludeModern){$sets.Add('modelsets/modern/models')}
$results=[Collections.Generic.List[object]]::new()
foreach($set in $sets){
 $folder=Join-Path $GameDataRoot $set
 $archive=Join-Path $folder 'gta3.img'
 $directory=[IO.File]::ReadAllBytes((Join-Path $folder 'gta3.dir'))
 $stream=[IO.File]::OpenRead($archive);$reader=[IO.BinaryReader]::new($stream)
 try {
  for($entry=0;$entry+32 -le $directory.Length;$entry+=32){
   $name=[Text.Encoding]::ASCII.GetString($directory,$entry+8,24).TrimEnd([char]0)
   if($name -notin $Models){continue}
   $offset=[BitConverter]::ToUInt32($directory,$entry);$sectors=[BitConverter]::ToUInt32($directory,$entry+4)
   if($sectors -eq 0 -or $sectors -gt 32768){throw 'Unexpected DFF record size.'}
   [void]$stream.Seek([long]$offset*2048,[IO.SeekOrigin]::Begin)
   $data=$reader.ReadBytes($sectors*2048)
   $metadata=Get-DffMetadata $data
   $results.Add([pscustomobject]@{set=$set;archive=$archive;name=$name;sectorOffset=$offset;sectorCount=$sectors;mesh=$metadata})
  }
 } finally {$reader.Dispose();$stream.Dispose()}
}
if($results.Count -ne $Models.Count*$sets.Count){throw 'Not every requested local DFF was found.'}
$json=ConvertTo-Json -InputObject @($results.ToArray()) -Depth 12
if($OutJson){
 [IO.File]::WriteAllText([IO.Path]::GetFullPath($OutJson),$json,[Text.UTF8Encoding]::new($false))
 Write-Host ('Metadata-only JSON: '+[IO.Path]::GetFullPath($OutJson))
}else{$json}

param([string]$KitRoot = (Split-Path -Parent (Split-Path -Parent $PSScriptRoot)))
$ErrorActionPreference = 'Stop'
$source = Get-Content -Raw (Join-Path $KitRoot 'overlay/src/audio/sampman_android.cpp')
function Extract([string]$Pattern) {
    $match = [regex]::Match($source, $Pattern)
    if (-not $match.Success) { throw "Cannot extract production audio code: $Pattern" }
    $match.Value
}
$types = Extract '(?ms)^struct AndroidChannel \{.*?^};'
$code = ''
foreach ($name in @('clampSample', 'updateSpatialization', 'audioCallback')) {
    $code += (Extract ('(?ms)^static (?:int|void|aaudio_data_callback_result_t)\s+' + $name + '\(.*?^}')) + "`n"
}
$code += (Extract '(?ms)^void\s+QuestAudio::SetChannel2D\(.*?^}') + "`n"
foreach ($name in @('InitialiseChannel', 'SetChannelEmittingVolume', 'SetChannel3DPosition', 'SetChannel3DDistances', 'SetChannelVolume', 'SetChannelPan', 'SetChannelFrequency', 'SetChannelLoopPoints', 'SetChannelLoopCount', 'StartChannel')) {
    $code += (Extract ('(?ms)^(?:bool8|void)\s+cSampleManager::' + $name + '\(.*?^}')) + "`n"
}
[IO.File]::WriteAllText((Join-Path $PSScriptRoot 'android-audio-types.inc'), $types)
[IO.File]::WriteAllText((Join-Path $PSScriptRoot 'android-audio-production.inc'), $code)
$view = Get-Content -Raw (Join-Path $KitRoot 'librw/src/vulkan/vkdevice.cpp')
$viewCode = ''
foreach ($pattern in @('(?ms)^static void\s+getFirstPersonPlayBasis\(.*?^}', '(?ms)^bool32\s+getFirstPersonViewFrame\(.*?^}')) {
    $match = [regex]::Match($view, $pattern)
    if (-not $match.Success) { throw 'Cannot extract production headset frame.' }
    $viewCode += $match.Value + "`n"
}
[IO.File]::WriteAllText((Join-Path $PSScriptRoot 'android-audio-view.inc'), $viewCode)
& (Join-Path $PSScriptRoot 'test-ragdoll.ps1') -KitRoot $KitRoot -Sources @('test-android-audio.cpp')
if ($LASTEXITCODE -ne 0) { throw 'Android audio regression failed.' }

param(
    [Parameter(Mandatory=$true)][string]$StageRoot,
    [string]$OutDir = (Join-Path ([IO.Path]::GetTempPath()) ('lcvr-drag-lift-' + [Guid]::NewGuid().ToString('N')))
)
$ErrorActionPreference = 'Stop'
function Extract-Block([string]$source, [string]$pattern) {
    $match = [regex]::Match($source, $pattern)
    if (-not $match.Success) { throw "Cannot extract production block: $pattern" }
    $end = $match.Index + $match.Length
    $depth = 1
    while ($depth -gt 0 -and $end -lt $source.Length) {
        if ($source[$end] -eq '{') { $depth++ }
        elseif ($source[$end] -eq '}') { $depth-- }
        $end++
    }
    if ($depth -ne 0) { throw 'Unterminated production block.' }
    return $source.Substring($match.Index, $end - $match.Index)
}
$physical = [IO.File]::ReadAllText((Join-Path $StageRoot 'src/entities/Physical.cpp'))
$floater = [IO.File]::ReadAllText((Join-Path $StageRoot 'src/vehicles/Floater.cpp'))
$boat = [IO.File]::ReadAllText((Join-Path $StageRoot 'src/vehicles/Boat.cpp'))
$lift = Extract-Block $boat 'if\(!onLand && bBoatInWater && GetUp\(\).z > 0.0f\)\s*\{'
$gravity = [regex]::Match([IO.File]::ReadAllText((Join-Path $StageRoot 'src/entities/Physical.h')), '(?m)^#define GRAVITY[^\r\n]+')
if (-not $gravity.Success) { throw 'Missing production gravity constant.' }
$output = $gravity.Value + "`n" + (Extract-Block $physical '(?m)^void\s+CPhysical::ApplyAirResistance\(void\)\s*\{') + "`n" +
    (Extract-Block $floater '(?m)^bool\s+cBuoyancy::CalcBuoyancyForce\([^)]*\)\s*\{') + "`n" +
    "void CBoat::ExtractedLift(bool onLand, const CVector &buoyancePoint, const CVector &buoyanceImpulse) {`n" + $lift + "`n}`n"
[IO.File]::WriteAllText((Join-Path $PSScriptRoot 'angular-drag-boat-lift-production.inc'), $output, [Text.UTF8Encoding]::new($false))
& (Join-Path $PSScriptRoot 'test-ragdoll.ps1') -KitRoot $StageRoot -OutDir $OutDir -Sources @('test-angular-drag-boat-lift.cpp')
if ($LASTEXITCODE -ne 0) { throw 'Angular drag / boat lift regression failed.' }

param(
    [Parameter(Mandatory=$true)][string]$Apk,
    [switch]$ExpectAsan
)
$ErrorActionPreference = 'Stop'
Add-Type -AssemblyName System.IO.Compression.FileSystem
$archive = [IO.Compression.ZipFile]::OpenRead([IO.Path]::GetFullPath($Apk))
try {
    $runtime = @($archive.Entries | Where-Object FullName -Like 'lib/*/libclang_rt.asan-*-android.so')
    $wrappers = @($archive.Entries | Where-Object FullName -Like 'lib/*/wrap.sh')
    if ($ExpectAsan) {
        if ($runtime.Count -ne 1 -or $runtime[0].FullName -ne 'lib/arm64-v8a/libclang_rt.asan-aarch64-android.so') {
            throw 'Diagnostic APK must contain exactly the arm64 ASan runtime.'
        }
        if ($wrappers.Count -ne 1 -or $wrappers[0].FullName -ne 'lib/arm64-v8a/wrap.sh') {
            throw 'Diagnostic APK must contain the arm64 Android launch wrapper.'
        }
        $reader = [IO.StreamReader]::new($wrappers[0].Open())
        try { $wrapper = $reader.ReadToEnd() } finally { $reader.Dispose() }
        if ($wrapper.Contains("`r") -or -not $wrapper.StartsWith("#!/system/bin/sh`n")) {
            throw 'The Android launch wrapper must use LF line endings and a valid shebang.'
        }
        if ($wrapper -notmatch 'LD_PRELOAD=.*libclang_rt\.asan-aarch64-android\.so .*libc\+\+_shared\.so' -or
            $wrapper -notmatch 'exec "\$@"') {
            throw 'The launch wrapper must preload ASan and the STL before executing the Android process.'
        }
    } elseif ($runtime.Count -or $wrappers.Count) {
        throw 'A player APK must exclude the diagnostic ASan runtime and wrapper.'
    }
    Write-Host "PASS: APK sanitizer packaging (expected ASan=$ExpectAsan): $Apk"
} finally { $archive.Dispose() }

param([Parameter(Mandatory=$true)][string]$StageRoot)
$ErrorActionPreference = 'Stop'
$source = Get-Content -Raw (Join-Path $StageRoot 'src/save/GenericGameStorage.cpp')
$header = Get-Content -Raw (Join-Path $StageRoot 'src/save/GenericGameStorage.h')
if ($header -notmatch '#define SLOT_COUNT \(8\)' -or $header -notmatch 'AUTOSAVE_SLOT = -1') {
    throw 'Keep eight manual slots and a distinct autosave load target.'
}
if ($source -notmatch 'AutosaveTransaction::Save\(operations, ValidSaveName\)') {
    throw 'The engine must use the tested autosave transaction.'
}
$functions = @('GetSaveFileName', 'CheckSaveFile', 'CheckDataNotCorrupt')
$extracted = foreach ($name in $functions) {
    $match = [regex]::Match($source, ('(?ms)^(?:static )?bool\s+' + $name + '\(.*?^}'))
    if (-not $match.Success) { throw "Cannot extract production function $name" }
    $match.Value
}
[IO.File]::WriteAllText((Join-Path $PSScriptRoot 'autosave-production.inc'), ($extracted -join "`n"))
$frontend = Get-Content -Raw (Join-Path $StageRoot 'src/core/Frontend.cpp')
if ($frontend -notmatch 'case MENUACTION_LOADAUTOSAVE:\s+m_nCurrSaveSlot = AUTOSAVE_SLOT;\s+ChangeScreen\(MENUPAGE_LOAD_SLOT_CONFIRM') {
    throw 'Autosave menu action must select the dedicated slot and load confirmation.'
}
if ($source -match 'PcSaveHelper.SaveSlot\(0\)') { throw 'Autosave must not overwrite manual slot 1.' }
foreach ($menu in @('MenuScreens.cpp', 'MenuScreensCustom.cpp')) {
    $text = Get-Content -Raw (Join-Path $StageRoot ('src/core/' + $menu))
    if ([regex]::Matches($text, 'MENUACTION_LOADAUTOSAVE').Count -ne 1) { throw "Missing dedicated load action: $menu" }
}
& (Join-Path $PSScriptRoot 'test-ragdoll.ps1') -KitRoot $StageRoot -Sources @('test-autosave.cpp')

param(
    [Parameter(Mandatory=$true)][string]$StageRoot,
    [string]$OutDir = (Join-Path ([IO.Path]::GetTempPath()) ('lcvr-boat-input-' + [Guid]::NewGuid().ToString('N')))
)
