$wrappers=''
foreach($entry in @(@('Fixed',$weapon),@('OriginalTracked',$old))){
    $wrappers+="static void Run$($entry[0])(CEntity *shooter,CVector *fireSource,CWeaponInfo *info,eWeaponType m_eWeaponType) {`n"+
        "CVector source,target,vrTraceSource; CVector2D ahead; CColPoint point; CEntity *victim=nil;`n"+
        "CVector vrFireSource=gAimSource,vrFireDirection=gAimDirection; bool useVrAim=true;`n"+
        (Get-TrackedBranch $entry[1])+"`n gResultVictim=victim; gResultTarget=target; gResultTraceSource=vrTraceSource; }`n"
}
# The original first-person branch's special test is also compiled: its M60
# damage remains 20, while ordinary FireInstantHit intentionally remains 4.
$m16=Get-Method $weapon 'CWeapon::FireM16_1stPerson'
$start=$m16.IndexOf('CVector bulletPos;')
$block=Get-Block $m16 ($m16.IndexOf('if ( CHeli::TestBulletCollision',$start))
$wrappers+="static void RunM16Special(CVector source,CVector target,eWeaponType m_eWeaponType){ CVector bulletPos;`n"+$block+"`n}`n"
# Native shotgun and sniper methods must still match the pre-fix source: this
# regression fix must not silently add special damage once per pellet.
foreach($name in @('CWeapon::FireShotgun','CWeapon::FireSniper','CWeapon::FireM16_1stPerson')){
    if((Get-Method $weapon $name).Replace("`r",'') -cne (Get-Method $old $name).Replace("`r",'')){
        throw "Unrelated fire path changed: $name"
    }
}
if((Get-Method $baseWeapon 'CWeapon::FireShotgun').Contains('TestBulletCollision')){throw 'Original shotgun audit assumption changed.'}
$fire=Get-Method $weapon 'CWeapon::Fire'
$start=$fire.IndexOf('case WEAPONTYPE_SHOTGUN:')
$end=$fire.IndexOf('case WEAPONTYPE_ROCKETLAUNCHER:',$start)
$dispatch=$fire.Substring($start,$end-$start)
$wrappers+="bool CWeapon::Dispatch(CEntity *shooter,CVector *source){ bool fired=false,addFireRateAsDelay=false; switch(m_eWeaponType){`n"+
    $dispatch+"`n default:break; } (void)addFireRateAsDelay;return fired;}`n"
[IO.File]::WriteAllText((Join-Path $PSScriptRoot 'heli-weapon-production.inc'),$wrappers,[Text.UTF8Encoding]::new($false))
Write-Host ('Weapon SHA256: '+(Get-FileHash -LiteralPath (Join-Path $StageRoot 'src/weapons/Weapon.cpp')).Hash)
Write-Host 'Original CHeli bullet/sniper/rocket implementations match base 026cd10.'
& (Join-Path $PSScriptRoot 'test-ragdoll.ps1') -KitRoot $StageRoot -OutDir $OutDir -Sources @('test-heli-bullets.cpp')
if($VehiclesCol){
    Write-Host ('Local COL SHA256: '+(Get-FileHash -LiteralPath $VehiclesCol).Hash)
    & (Join-Path $OutDir 'test-heli-bullets.exe') $VehiclesCol
    if($LASTEXITCODE -ne 0){throw 'Actual local helicopter COL regression failed.'}
}

param(
    [Parameter(Mandatory=$true)][string]$StageRoot,
    [string]$OutDir = (Join-Path ([IO.Path]::GetTempPath()) ('lcvr-heli-' + [Guid]::NewGuid().ToString('N')))
)
$ErrorActionPreference='Stop'
function Extract([string]$s,[string]$pattern){
    $m=[regex]::Match($s,$pattern);if(-not$m.Success){throw "Missing production code: $pattern"}
    $end=$m.Index+$m.Length;$depth=1
    while($depth-gt0-and$end-lt$s.Length){if($s[$end]-eq'{'){$depth++}elseif($s[$end]-eq'}'){$depth--};$end++}
    if($depth-ne0){throw 'Unterminated production block.'}
    $s.Substring($m.Index,$end-$m.Index)
}
$heli=[IO.File]::ReadAllText((Join-Path $StageRoot 'src/vehicles/Heli.cpp'))
$clock=[IO.File]::ReadAllText((Join-Path $StageRoot 'src/core/QuestGameTime.h')).Replace('#include "Timer.h"','// Fixture timer.')
if($heli-match'CHeli::ProcessAvoidance\('){
    $avoid=Extract $heli '(?m)^void\s+CHeli::ProcessAvoidance\([^)]*\)\s*\{'
}else{
    $old=[regex]::Match($heli,'(?s)(\tif\(m_heliStatus == HELI_STATUS_HOVER2 \|\| m_heliStatus == HELI_STATUS_SHOT_DOWN\)\{.*?)\s*if\(m_heliType == HELI_TYPE_CATALINA\)')
    if(-not$old.Success){throw 'Missing legacy helicopter avoidance.'}
    $avoid='void CHeli::ProcessAvoidance(CVector2D &targetSpeed,const CVector2D &vTargetDist){'+$old.Groups[1].Value+'}'
}
$landing='void CHeli::Landing(CVector target){'+(Extract $heli 'if\(m_pathState == 6\)\s*\{')+'}'
[IO.File]::WriteAllText((Join-Path $PSScriptRoot 'heli-control-timing-production.inc'),$clock+"`n"+$avoid+"`n"+$landing,[Text.UTF8Encoding]::new($false))
& (Join-Path $PSScriptRoot 'test-ragdoll.ps1') -KitRoot $StageRoot -OutDir $OutDir -Sources @('test-heli-control-timing.cpp')
if($LASTEXITCODE-ne0){throw 'Helicopter control timing regression failed.'}
if($heli-notmatch'ProcessAvoidance\(targetSpeed, vTargetDist\);'-or$heli-notmatch'm_fAvoidanceSideSpeed = 0.0f;'){
    throw 'Missing control integration or constructor initialization.'
}

param( [Parameter(Mandatory=$true)][string]$StageRoot, [string]$OutDir = (Join-Path $env:TEMP ('lc-holster-' + [guid]::NewGuid().ToString('N'))) ) $ErrorActionPreference = 'Stop' $StageRoot = [IO.Path]::GetFullPath($StageRoot) $pad = [IO.File]::ReadAllText((Join-Path $StageRoot 'src/core/Pad.cpp')) $quest = [IO.File]::ReadAllText((Join-Path $StageRoot 'src/vr/QuestWeaponVR.cpp')) $parts = @('#include "' + ((Join-Path $StageRoot 'src/weapons/WeaponType.h') -replace '\','/') + '"') foreach ($name in @('GetWeaponTypeForSlot', 'GetVrHolsterSlotName', 'GetVrWeaponTypeForSlot', 'IsVrWeaponSlotOwned', 'WeaponCheat')) { $match = [regex]::Match($pad, '(?ms)^(?:static )?[^
]+[ *]' + $name + '\([^
]*\)?
\{.*?^\}') if (-not $match.Success) { throw "Missing production function $name" } $parts += $match.Value } foreach ($pattern in @( '(?m)^static const float kHolsterGrabRadii[^
]+', '(?m)^static int gHolsterGrabDistance[^
]+', '(?ms)^static bool?
IsHolsterWithinGrabDistance\(.*?^\}', '(?ms)^static bool?
IsPhysicalGun\(.*?^\}', '(?ms)^static bool?
IsPhysicalMelee\(.*?^\}', '(?ms)^static bool?
IsPhysicalThrowable\(.*?^\}', '(?m)^bool IsPhysicalWeaponType[^
