NormalizeDualWieldHolsters\(.*?^\}', '(?ms)^static int?
HolsterCopy\(.*?^\}', '(?ms)^static bool?
DualWieldSlot\(.*?^\}', '(?ms)^static bool?
CopyInUse\(.*?^\}', '(?ms)^bool IsQuestDualWieldEligible\(.*?^\}', '(?ms)^bool IsQuestDualWieldEnabled\(.*?^\}', '(?ms)^void ToggleQuestDualWield\(.*?^\}', '(?ms)^void?
CycleQuestHolsterPointSlot\(.*?^\}' )) { $match = [regex]::Match($quest, $pattern) if (-not $match.Success) { throw "Missing production code $pattern" } $parts += $match.Value } $generated = Join-Path $PSScriptRoot 'holster-inventory-production.inc' $normalization = [regex]::Match($quest, '(?ms)^	// Keep the centre dedicated.*?(?=^	gSettingsLoaded = true;)') if (-not $normalization.Success) { throw 'Missing centre holster settings normalization.' } $parts += "void NormalizeLoadedCentre() {`n" + $normalization.Value + "`n}" [IO.File]::WriteAllText($generated, ($parts -join "`n`n"), [Text.UTF8Encoding]::new($false)) & (Join-Path $PSScriptRoot 'test-ragdoll.ps1') -KitRoot $StageRoot -OutDir $OutDir -Sources @('test-holster-inventory.cpp')

#!/usr/bin/env python3 import contextlib import importlib.util import io import json from pathlib import Path import subprocess import tempfile import unittest from unittest.mock import patch
root=Path(__file__).resolve().parents[2] spec=importlib.util.spec_from_file_location('import_music',root/'tools/import-music.py') module=importlib.util.module_from_spec(spec); spec.loader.exec_module(module)
class ImportTests(unittest.TestCase): def setUp(self): self.temp=tempfile.TemporaryDirectory(); self.addCleanup(self.temp.cleanup) self.path=Path(self.temp.name)/'_Tést & song.mp3'; self.path.write_bytes(b'generated test audio placeholder') def test_safe_name_and_content_hash(self): sha=module.digest(self.path); name=module.safe_name(self.path,sha) self.assertRegex(name,r'^[A-Za-z0-9][A-Za-z0-9_.-]{0,119}\.mp3$') self.assertNotIn('&',name); self.assertIn(sha[:16],name) self.assertEqual(sha,module.digest(self.path)) def test_probe_rejects_unsupported_streams(self): good={'streams':[{'codec_type':'audio','codec_name':'mp3','channels':2,'sample_rate':'44100'}], 'format':{'duration':'10.2'}} with patch.object(module,'run',return_value=subprocess.CompletedProcess([],0,json.dumps(good))): self.assertEqual(module.probe(self.path,'ffprobe')[1],10200) good['streams'][0]['channels']=6 with patch.object(module,'run',return_value=subprocess.CompletedProcess([],0,json.dumps(good))): with self.assertRaisesRegex(ValueError,'mono/stereo'): module.probe(self.path,'ffprobe') def test_dry_run_never_touches_headset(self): with patch.object(module,'probe',return_value=(32,10000)),patch.object(module.shutil,'which',return_value='ffprobe'),patch.object(module,'find_adb',side_effect=AssertionError('ADB lookup attempted')),patch.object(module,'choose_device',side_effect=AssertionError('Headset accessed')),contextlib.redirect_stdout(io.StringIO()): self.assertEqual(module.main(['--dry-run',str(self.path)]),0) def test_adb_on_path_has_priority(self): with patch.object(module.shutil,'which',return_value='/tools/adb'): self.assertEqual(module.find_adb(),'/tools/adb') def test_explicit_adb_is_respected(self): with patch.object(module.shutil,'which',return_value='/custom/adb') as which: self.assertEqual(module.find_adb('/custom/adb'),'/custom/adb') which.assert_called_once_with('/custom/adb') with patch.object(module.shutil,'which',return_value=None): with self.assertRaisesRegex(RuntimeError,'Check --adb'): module.find_adb('/missing/adb') def test_adb_from_sdk_environment(self): sdk=Path(self.temp.name)/'Android SDK' executable='adb.exe' if module.sys.platform=='win32' else 'adb' adb=sdk/'platform-tools'/executable adb.parent.mkdir(parents=True); adb.touch() for key in ('ANDROID_HOME','ANDROID_SDK_ROOT'): with self.subTest(key=key),patch.dict(module.os.environ,{key:str(sdk)},clear=True),patch.object(module.shutil,'which',return_value=None): self.assertEqual(module.find_adb(),str(adb.resolve())) def test_windows_adb_fallbacks(self): local=Path(self.temp.name) standard=local/'Android'/'Sdk'/'platform-tools'/'adb.exe' builder=Path('C:/LCVRBuild/.android-sdk/platform-tools/adb.exe') for expected in (standard,builder): with self.subTest(expected=expected),patch.dict(module.os.environ,{'LOCALAPPDATA':str(local)},clear=True),patch.object(module.sys,'platform','win32'),patch.object(module.shutil,'which',return_value=None),patch.object(Path,'is_file',autospec=True,side_effect=lambda p:p==expected): self.assertEqual(module.find_adb(),str(expected.resolve())) def test_missing_adb_fails_before_audio_validation(self): with patch.object(module,'find_adb',side_effect=RuntimeError('ADB was not found')),patch.object(module,'probe') as probe: with self.assertRaisesRegex(RuntimeError,'ADB was not found'): module.main([str(self.path)]) probe.assert_not_called() def test_missing_adb_has_actionable_error(self): with patch.object(module.shutil,'which',return_value=None),patch.dict(module.os.environ,{},clear=True),patch.object(Path,'is_file',return_value=False): with self.assertRaisesRegex(RuntimeError,'Install Android Platform Tools.*--adb'): module.find_adb() def test_missing_executable_names_failed_tool(self): with patch.object(module.subprocess,'run',side_effect=FileNotFoundError(2,'missing')): with self.assertRaisesRegex(RuntimeError,"Cannot launch 'missing-adb'"): module.run(['missing-adb','devices','-l']) def test_upload_uses_sync_and_device_local_input(self): adb=['adb','-s','TEST'] with patch.object(module,'run') as run: module.upload(adb,self.path,'song.mp3') calls=run.call_args_list self.assertEqual(len(calls),3) push=calls[0].args[0] self.assertEqual(push[:4],adb+['push']) self.assertEqual(push[4],str(self.path)) remote=push[5] self.assertRegex(remote,r'^/data/local/tmp/lcvr-music-[a-f0-9]{32}\.tmp$') self.assertEqual(calls[1].args[0],adb+['shell',f'content write --uri {module.URI}/upload/song.mp3 < {remote}']) self.assertEqual(calls[1].kwargs['stdin'],subprocess.DEVNULL) self.assertEqual(calls[2].args[0],adb+['shell','rm','-f',remote]) def test_upload_failure_cleans_temporary_file(self): for failure in (0,1): calls=[] def run(args,**kwargs): calls.append(args) if len(calls)==failure+1: raise RuntimeError('Upload failed') with self.subTest(failure=failure),patch.object(module,'run',side_effect=run): with self.assertRaisesRegex(RuntimeError,'Upload failed'): module.upload(['adb','-s','TEST'],self.path,'song.mp3') self.assertEqual(calls[-1][3:6],['shell','rm','-f']) def workflow(self,fail=False,remote=None): calls=[]; sha=module.digest(self.path); name=module.safe_name(self.path,sha) def provider(adb,method,arg=None): calls.append((method,arg)) if method=='info': return remote or {'count':0,'free':10*module.RESERVE,'duration':0,'names':[]} if method=='check': return {'exists':True} if method=='commit': if fail: raise RuntimeError('Transfer checksum mismatch') return {'bytes':self.path.stat().st_size} return {'ok':True} with patch.object(module,'probe',return_value=(self.path.stat().st_size,10000)),patch.object(module.shutil,'which',return_value='ffprobe'),patch.object(module,'choose_device',return_value=['adb','-s','TEST']),patch.object(module,'provider',side_effect=provider),patch.object(module,'run',return_value=subprocess.CompletedProcess([],0,b'')),contextlib.redirect_stdout(io.StringIO()): if fail: with self.assertRaisesRegex(RuntimeError,'checksum'): module.main([str(self.path)]) else: self.assertEqual(module.main([str(self.path)]),0) return calls,name def test_success_checks_commit_size_and_digest(self): calls,name=self.workflow() self.assertIn(('commit',name+':'+module.digest(self.path)),calls) self.assertNotIn(('abort',name),calls) def test_failed_upload_is_aborted(self): calls,name=self.workflow(fail=True); self.assertIn(('abort',name),calls) def test_full_library_can_be_reimported_without_upload(self): sha=module.digest(self.path); name=module.safe_name(self.path,sha) calls,_=self.workflow(remote={'count':1000,'free':10*module.RESERVE,'duration':module.MAX_DURATION,'names':[name]}) self.assertEqual([c[0] for c in calls],['info','check']) def test_reject_wrong_device(self): results=[subprocess.CompletedProcess([],0,'List of devices attached\nTEST device model:Phone\n'),subprocess.CompletedProcess([],0,'Phone')] with patch.object(module,'run',side_effect=results): with self.assertRaisesRegex(RuntimeError,'Quest'): module.choose_device('adb',None)
if __name__=='__main__': unittest.main()

param([string]$OutDir=(Join-Path $PSScriptRoot '../../.cache/installer-native-tests'))
$ErrorActionPreference='Stop'
$root=Split-Path (Split-Path $PSScriptRoot -Parent) -Parent
New-Item -ItemType Directory -Force -Path $OutDir | Out-Null
function Import-Function([string]$File,[string]$Name) {
    $tokens=$null; $errors=$null
    $ast=[Management.Automation.Language.Parser]::ParseFile($File,[ref]$tokens,[ref]$errors)
    if($errors){throw 'Production script parse failed.'}
    $node=$ast.Find({param($n) $n -is [Management.Automation.Language.FunctionDefinitionAst] -and $n.Name -eq $Name},$true)
    if($null -eq $node){throw "Missing production function: $Name"}
    . ([scriptblock]::Create($node.Extent.Text))
    Set-Item -Path "function:script:$Name" -Value (Get-Item "function:$Name").ScriptBlock
}
Import-Function (Join-Path $root 'tools/build-and-install.ps1') 'Invoke-Checked'
$script:adb=$null
$fake=Join-Path ([IO.Path]::GetFullPath($OutDir)) 'native-warning.cmd'
[IO.File]::WriteAllText($fake,"@echo off`r`necho Warning: SDK processing. XML version warning fixture 1>&2`r`necho native command completed`r`nif `"%~1`"==`"fail`" exit /b 7`r`nexit /b 0`r`n",[Text.Encoding]::ASCII)
Invoke-Checked -FilePath $fake -Arguments @('ok')
if($ErrorActionPreference -ne 'Stop'){throw 'Caller preference was not restored.'}
$failed=$false
try { Invoke-Checked -FilePath $fake -Arguments @('fail') -FailureMessage 'Expected native failure' }
catch { if($_.Exception.Message -notmatch 'exit code 7'){throw};$failed=$true }
if(-not $failed){throw 'Nonzero exit was accepted.'}
$failed=$false
try { Invoke-Checked -FilePath (Join-Path $OutDir 'missing.exe') -Arguments @('ok') }
catch {$failed=$true}
if(-not $failed){throw 'Missing tool was accepted.'}
if($ErrorActionPreference -ne 'Stop'){throw 'Caller preference was not restored after failure.'}

Import-Function (Join-Path $root 'tools/install-modern-models.ps1') 'Find-Adb'
# Isolate discovery from installed tools/devices; these virtual candidates
# deliberately include both the current and legacy default SDK locations.
$AndroidSdk='';$env:ANDROID_HOME='';$env:ANDROID_SDK_ROOT='';$env:LOCALAPPDATA=''
$script:existing=@('C:\LCVRBuild\.android-sdk\platform-tools\adb.exe','C:\VCVRBuild\.android-sdk\platform-tools\adb.exe')
function Test-Path { param([string]$LiteralPath,[string]$PathType) return $script:existing -contains $LiteralPath }
function Resolve-Path { param([string]$LiteralPath) return [pscustomobject]@{Path=$LiteralPath} }
function Get-Command { param([string]$Name,[string]$ErrorAction) return $null }
if((Find-Adb) -ne 'C:\LCVRBuild\.android-sdk\platform-tools\adb.exe'){throw 'Default Liberty City SDK not preferred.'}
$AndroidSdk='C:\explicit-sdk';$script:existing+=Join-Path $AndroidSdk 'platform-tools\adb.exe'
if((Find-Adb) -ne (Join-Path $AndroidSdk 'platform-tools\adb.exe')){throw 'Explicit SDK override was ignored.'}
$AndroidSdk='';$script:existing=@();$failed=$false
try { Find-Adb } catch {$failed=$true}
if(-not $failed){throw 'Missing SDK was accepted.'}
Write-Host 'PASS native stderr warning/exit status/preference restoration and isolated ADB SDK discovery'

param(
    [string]$KitRoot = (Split-Path -Parent (Split-Path -Parent $PSScriptRoot)),
    [string]$OutDir = (Join-Path ([IO.Path]::GetTempPath()) ('vice-city-laser-cache-' + [Guid]::NewGuid().ToString('N')))
)
$ErrorActionPreference = 'Stop'
Set-StrictMode -Version 2.0

function Assert-PlainPath([string]$Path) {
    $probe = [IO.Path]::GetFullPath($Path)
    if (-not [IO.Path]::IsPathRooted($Path) -or $probe -cne $Path) {
        throw "An absolute canonical path is required: $Path"
    }
    while ($probe) {
        if (Test-Path -LiteralPath $probe) {
            if (((Get-Item -LiteralPath $probe -Force).Attributes -band [IO.FileAttributes]::ReparsePoint) -ne 0) {
                throw "Reparse points are not supported by this test: $probe"
            }
        }
        $parent = [IO.Directory]::GetParent($probe)
        if ($null -eq $parent) { break }
        $probe = $parent.FullName
    }
}

$KitRoot = [IO.Path]::GetFullPath($KitRoot)
$OutDir = [IO.Path]::GetFullPath($OutDir)
Assert-PlainPath $KitRoot
Assert-PlainPath $OutDir
if (Test-Path -LiteralPath $OutDir) { throw 'Test output already exists; choose a new output directory.' }
$source = Join-Path $KitRoot 'overlay\src\vr\QuestWeaponVR.cpp'
$fixtureTemplate = Join-Path $PSScriptRoot 'laser-cache-fixture.cpp.in'
Assert-PlainPath $source
Assert-PlainPath $fixtureTemplate
$text = [IO.File]::ReadAllText($source)
$template = [IO.File]::ReadAllText($fixtureTemplate)
$parts = [ordered]@{
    '@@PRODUCTION_CACHE@@' = '(?s)struct WeaponLaserOverride\s*\{.*?static WeaponLaserOverride gWeaponLaserOverrides\[2\]\[WEAPONTYPE_TOTALWEAPONS\];'
    '@@PRODUCTION_READ_WRITE@@' = '(?s)static void\s+WeaponLaserSection\(.*?(?=static bool\s+CalibrationConfigured\()'
    '@@PRODUCTION_INVALIDATION@@' = '(?s)void\s+InvalidateQuestWeaponLaserOverrides\(\)\s*\{.*?\n\}'
    '@@PRODUCTION_PUBLIC_API@@' = '(?s)bool\s+IsTrackedWeaponLaserEnabledForType\(.*?(?=bool IsTrackedScopeActive\()'
}
foreach ($part in $parts.GetEnumerator()) {
    $matches = [regex]::Matches($text, $part.Value)
    if ($matches.Count -ne 1) { throw "Expected exactly one production region: $($part.Key)" }
    $template = $template.Replace($part.Key, $matches[0].Value)
}
if ($template.Contains('@@PRODUCTION_')) { throw 'Unexpanded production fixture marker.' }
foreach ($hook in @('LoadSettings', 'PrepareForGameShutdown')) {
    if ($text -notmatch ('(?s)' + $hook + '\(\)\s*\{.{0,100}InvalidateQuestWeaponLaserOverrides\(\);')) {
        throw "Missing cache lifecycle hook: $hook"
    }
}
$menuPath = Join-Path $KitRoot 'overlay\src\skel\android\vrdebug.cpp'
Assert-PlainPath $menuPath
$menu = [IO.File]::ReadAllText($menuPath)
if ($menu -notmatch 'OculusVR::InvalidateQuestWeaponLaserOverrides\(\);') {
    throw 'The VR menu must invalidate cached overrides when it opens.'
}

$programFilesX86 = [Environment]::GetFolderPath('ProgramFilesX86')
$vswhere = Join-Path $programFilesX86 'Microsoft Visual Studio\Installer\vswhere.exe'
if (-not (Test-Path -LiteralPath $vswhere -PathType Leaf)) {
    throw 'Visual Studio 2022 or Build Tools with the Desktop development with C++ workload is required.'
}
$install = @(& $vswhere -latest -products '*' -requires Microsoft.VisualStudio.Component.VC.Tools.x86.x64 -property installationPath)
if ($LASTEXITCODE -ne 0 -or $install.Count -ne 1 -or [string]::IsNullOrWhiteSpace($install[0])) {
    throw 'Cannot locate a Visual Studio installation with the x64 C++ tools.'
}
$toolchainRoot = Join-Path $install[0] 'VC\Tools\MSVC'
$versions = @(Get-ChildItem -LiteralPath $toolchainRoot -Directory | Where-Object {
    Test-Path -LiteralPath (Join-Path $_.FullName 'bin\Hostx64\x64\cl.exe') -PathType Leaf
} | Sort-Object { [version]$_.Name } -Descending)
if ($versions.Count -eq 0) { throw 'No x64-hosted MSVC compiler was found.' }
$vc = $versions[0].FullName
$compiler = Join-Path $vc 'bin\Hostx64\x64\cl.exe'
$sdk = Join-Path $programFilesX86 'Windows Kits\10'
$sdkRegistry = Get-ItemProperty -LiteralPath 'HKLM:\SOFTWARE\Microsoft\Windows Kits\Installed Roots' -ErrorAction SilentlyContinue
if ($sdkRegistry -and $sdkRegistry.PSObject.Properties.Name -contains 'KitsRoot10') {
    $sdk = $sdkRegistry.KitsRoot10.TrimEnd('\')
}
$sdkVersions = @(Get-ChildItem -LiteralPath (Join-Path $sdk 'Include') -Directory | Where-Object {
    (Test-Path -LiteralPath (Join-Path $_.FullName 'ucrt\stdlib.h') -PathType Leaf) -and
    (Test-Path -LiteralPath (Join-Path $sdk ('Lib\' + $_.Name + '\um\x64\kernel32.lib')) -PathType Leaf)
} | Sort-Object { [version]$_.Name } -Descending)
if ($sdkVersions.Count -eq 0) { throw 'Windows 10/11 SDK headers and x64 libraries are required.' }
$sdkVersion = $sdkVersions[0].Name

[void][IO.Directory]::CreateDirectory($OutDir)
Assert-PlainPath $OutDir
$fixture = Join-Path $OutDir 'laser_cache_test.cpp'
[IO.File]::WriteAllText($fixture, $template, (New-Object Text.UTF8Encoding($false)))
$exe = Join-Path $OutDir 'laser_cache_test.exe'
$obj = Join-Path $OutDir 'laser_cache_test.obj'
$compileOutput = & $compiler /nologo /EHsc /W4 /WX /std:c++17 /MT /O2 `
    ('/I' + (Join-Path $vc 'include')) `
    ('/I' + (Join-Path $sdk ('Include\' + $sdkVersion + '\ucrt'))) `
    $fixture ('/Fo' + $obj) ('/Fe' + $exe) /link `
    ('/LIBPATH:' + (Join-Path $vc 'lib\x64')) `
    ('/LIBPATH:' + (Join-Path $sdk ('Lib\' + $sdkVersion + '\ucrt\x64'))) `
    ('/LIBPATH:' + (Join-Path $sdk ('Lib\' + $sdkVersion + '\um\x64'))) 2>&1
$compileCode = $LASTEXITCODE
$compileOutput | ForEach-Object { Write-Host $_ }
if ($compileCode -ne 0) { throw "Host fixture compilation failed: $compileCode" }
& $exe
if ($LASTEXITCODE -ne 0) { throw "Host fixture failed: $LASTEXITCODE" }
Write-Host ('Production source SHA256: ' + (Get-FileHash -LiteralPath $source -Algorithm SHA256).Hash)
Write-Host "Test artifacts: $OutDir"
Write-Host 'Only the host fixture was compiled and run; no game, headset or shared build was changed.'

#!/usr/bin/env python3
"""Exercise production splash selection, layout and fades (no game data)."""
import argparse
import os
import pathlib
import subprocess
import tempfile

parser = argparse.ArgumentParser(description=__doc__)
parser.add_argument('stage_root', type=pathlib.Path)
parser.add_argument('--cxx', default='g++')
args = parser.parse_args()
source = (args.stage_root / 'src/core/main.cpp').read_text()
helper = source[source.index('static void\nDrawQuestLoadingArtwork('):source.index('\nvoid\nDoFade(void)')]
# Drop the Android guard's trailing #endif; the adapter defines that platform.
helper = helper[:helper.rindex('#endif')]
loader = source[source.index('CSprite2d*\nLoadSplash('):source.index('\nvoid\nDestroySplashScreen(')]
im = (args.stage_root / 'vendor/librw/src/vulkan/vkim.cpp').read_text()
