#!/usr/bin/env python3
"""Exercise production radio input with deterministic poses and clock."""
from pathlib import Path
import re
import subprocess
import tempfile
root=Path(__file__).resolve().parents[2]
source=(root/'overlay/src/vr/QuestRadio.cpp').read_text()
production=[]
for name in ['Update','SuppressDriving']:
    match=re.search(r'(?ms)^bool Update\(.*?^}',source) if name=='Update' else re.search(r'(?m)^void SuppressDriving[^\n]+',source)
    assert match, name
    production.append(match.group())
with tempfile.TemporaryDirectory(prefix='radio-input-') as d:
    work=Path(d)
    (work/'production.inc').write_text('\n'.join(production))
    (work/'main.cpp').write_text(r'''
#include "RadioBoardLayout.h"
#include <cassert>
#include <cstdio>
#include <cstring>
#include <cstdint>
struct CVector { float x,y,z; CVector(float a=0,float b=0,float c=0):x(a),y(b),z(c){} CVector operator-(CVector b) const{return {x-b.x,y-b.y,z-b.z};} };
float DotProduct(CVector a,CVector b){return a.x*b.x+a.y*b.y+a.z*b.z;}
namespace androidgame {
struct PadInput { struct Pose {float position[3],orientation[4];bool valid=false;}; Pose aimPose[2]; bool x=false; float leftTrigger=0,rightTrigger=0; } input;
const PadInput &GetPadInput(){return input;}
}
namespace OculusVR { bool weapon=false; bool IsTrackedWeaponHeld(int){return weapon;} bool GetTrackedIndexTip(int,CVector*){return false;} }
namespace rw { namespace vulkan {
bool playPoseToFirstPersonWorld(const float *pos,const float*,float*,float*,float *forward,float *origin){memcpy(origin,pos,12);forward[0]=forward[1]=0;forward[2]=-1;return true;}
} }
struct CControllerState { int acceleration=255; void Clear(){acceleration=0;} };
namespace QuestRadio {
struct Plane{CVector origin,right={1,0,0},up={0,1,0},normal={0,0,1};float width=.4f;};
bool available=true,vehicle=true,interacting=false,xDown=false,triggerDown[2]={true,true};
bool touchMode=false; RadioBoard::Touch touch[2];
int hover=-1,activations=0,last=-1;double now=0,xSince=0;
void Load(){} bool BuildPlane(Plane &){return available;} bool Vehicle(){return vehicle;} double Now(){return now;}
void Activate(int hit){++activations;last=hit;}
#include "production.inc"
}
int main(){
 using namespace QuestRadio; auto &in=androidgame::input;
 assert(!Update(false)); in.x=true; now=.01; assert(!Update(false));
 in.x=false; now=.1; assert(Update(false)); // ordinary short station tap
 in.x=true; now=1; assert(!Update(false)); now=1.31; assert(!Update(false) && interacting);
 // Aim at NEXT, but a trigger already held for driving must not click.
 in.aimPose[0].valid=true;in.aimPose[0].position[0]=(422-256)*.4f/512;in.aimPose[0].position[1]=(128-159)*.4f/512;in.aimPose[0].position[2]=1;
 in.leftTrigger=1; Update(true); now=2; Update(false); now=2.31; Update(false); assert(activations==0);
 in.leftTrigger=0; Update(false);in.leftTrigger=1;Update(false);assert(activations==1 && last==6);
 Update(false);assert(activations==1); // no repeat while held
 CControllerState pad;SuppressDriving(&pad);assert(pad.acceleration==0);
 in.x=false;now=2.5;assert(!Update(false));assert(!interacting);
 pad.acceleration=255;SuppressDriving(&pad);assert(pad.acceleration==255);
 // Invalid tracking, weapon ownership and blocked/menu frames never activate.
 in.x=true;now=3;Update(false);now=3.4;Update(false);
 in.leftTrigger=0;Update(false);in.aimPose[0].valid=false;in.leftTrigger=1;Update(false);assert(activations==1);
 in.aimPose[0].valid=true;in.leftTrigger=0;Update(false);OculusVR::weapon=true;in.leftTrigger=1;Update(false);assert(activations==1);
 Update(true);assert(!interacting);
 puts("Production radio input: tap/hold, pointer click, held-trigger gating, tracking, weapon exclusion and driving capture passed.");
}
''')
    exe=work/'test'
    subprocess.run(['c++','-std=c++17','-I'+str(root/'overlay/src/vr'),str(work/'main.cpp'),'-o',str(exe)],check=True)
    subprocess.run([str(exe)],check=True)

param(
    [string]$KitRoot=(Split-Path -Parent (Split-Path -Parent $PSScriptRoot)),
    [string]$OutDir=(Join-Path ([IO.Path]::GetTempPath()) ('lcvr-radio-touch-'+[guid]::NewGuid().ToString('N')))
)
$ErrorActionPreference='Stop'
$radio=[IO.File]::ReadAllText((Join-Path $KitRoot 'overlay/src/vr/QuestRadio.cpp'))
$code='#include "'+((Join-Path ([IO.Path]::GetFullPath($KitRoot)) 'overlay/src/vr/RadioBoardLayout.h').Replace('\','/'))+'"'+"`n"
$code+="namespace QuestRadio {`n"
foreach($name in @('Update','SuppressDriving','MenuRow','MenuAction')) {
    $match=[regex]::Match($radio,'(?m)^(?:void|bool) '+$name+'\(')
    if(-not $match.Success){throw "Missing production function: $name"}
    $open=$radio.IndexOf('{',$match.Index);$depth=0
    for($i=$open;$i -lt $radio.Length;$i++) {
        if($radio[$i] -eq '{'){$depth++}
        if($radio[$i] -eq '}'){$depth--;if($depth -eq 0){break}}
    }
    if($depth -ne 0){throw "Unterminated production function: $name"}
    $code+=$radio.Substring($match.Index,$i-$match.Index+1)+"`n"
}
$code+="}`n"
$hand=[IO.File]::ReadAllText((Join-Path $KitRoot 'overlay/src/vr/VRHandModel.cpp'))
$code+="namespace VRHandModel {`n"
foreach($name in @('Clamp01','InterpolatePose','IndexTip')) {
    $match=[regex]::Match($hand,'(?ms)^(?:float|CVector|bool)\r?\n'+$name+'\(.*?^}')
    if(-not $match.Success){throw "Missing production hand function: $name"}
    $code+=$match.Value+"`n"
}
$code+="}`n"
[IO.File]::WriteAllText((Join-Path $PSScriptRoot 'radio-touch-production.inc'),$code,[Text.UTF8Encoding]::new($false))
& (Join-Path $PSScriptRoot 'test-ragdoll.ps1') -KitRoot $KitRoot -OutDir $OutDir -Sources @('test-radio-touch.cpp')
if($LASTEXITCODE -ne 0){throw 'Radio touch regression failed'}

param(
    [string]$StageRoot = (Split-Path -Parent (Split-Path -Parent $PSScriptRoot)),
    [string]$OutDir = (Join-Path ([IO.Path]::GetTempPath()) ('vc-brake-hook-' + [Guid]::NewGuid().ToString('N')))
)
$ErrorActionPreference = 'Stop'
$sourcePath = Join-Path $StageRoot 'src\peds\VrRagdoll.cpp'
if (-not (Test-Path -LiteralPath $sourcePath)) {
    $sourcePath = Join-Path $StageRoot 'overlay\src\peds\VrRagdoll.cpp'
}
$source = [IO.File]::ReadAllText($sourcePath)
$hookPath = Join-Path $StageRoot 'src\peds\PedFight.cpp'
if (-not (Test-Path -LiteralPath $hookPath)) {
    throw 'The brake hook fixture requires -StageRoot pointing to assembled source containing src\peds\PedFight.cpp.'
}
$hook = [IO.File]::ReadAllText($hookPath)
if (-not [regex]::IsMatch($hook, 'VrRagdoll::VehicleImpact\(this,\s*car,\s*incomingRagdollSpeed,\s*impulse,\s*contactPoint,\s*preCollisionTurn\);')) {
    throw 'KillPedWithCar does not pass its vehicle and confirmed collision impulse to the production callback.'
}
$callback = [regex]::Match($source, '(?ms)^void\s+VehicleImpact\(CPed \*ped,\s*CVehicle \*car,.*?^\}')
if (-not $callback.Success) { throw 'Cannot extract production vehicle brake callback.' }
$getter = [regex]::Match($source, '(?m)^int\s+GetBrakePercent\(void\)\s*\{[^\r\n]*\}')
if (-not $getter.Success) { throw 'Cannot extract production braking setting getter.' }
$generated = Join-Path $PSScriptRoot 'ragdoll-brake-hook-production.inc'
[IO.File]::WriteAllText($generated, $getter.Value + "`r`n" + $callback.Value + "`r`n", [Text.UTF8Encoding]::new($false))
Write-Host ('VrRagdoll.cpp SHA256: ' + (Get-FileHash -LiteralPath $sourcePath -Algorithm SHA256).Hash)
Write-Host ('PedFight.cpp hook SHA256: ' + (Get-FileHash -LiteralPath $hookPath -Algorithm SHA256).Hash)
& (Join-Path $PSScriptRoot 'test-ragdoll.ps1') -KitRoot $StageRoot -OutDir $OutDir -Sources @('test-ragdoll-brake-hook.cpp')

param(
    [string]$StageRoot=(Split-Path -Parent (Split-Path -Parent $PSScriptRoot)),
    [string]$OutDir=(Join-Path ([IO.Path]::GetTempPath()) ('vc-explosion-'+[Guid]::NewGuid().ToString('N'))),
    [switch]$Baseline,
    [switch]$DevTools
)
$ErrorActionPreference='Stop'
$sourceRoot=Join-Path $StageRoot 'src'
if($Baseline){
    $sourceRoot=Join-Path $StageRoot 'baseline/src'
    if(-not(Test-Path (Join-Path $sourceRoot 'peds/VrRagdoll.cpp'))){throw 'Baseline reproduction requires the preserved baseline/src tree.'}
}
if(-not(Test-Path (Join-Path $sourceRoot 'peds/VrRagdoll.cpp'))){$sourceRoot=Join-Path $StageRoot 'overlay/src'}
$source=[IO.File]::ReadAllText((Join-Path $sourceRoot 'peds/VrRagdoll.cpp'))
$world=[IO.File]::ReadAllText((Join-Path $sourceRoot 'core/World.cpp'))
$ped=[IO.File]::ReadAllText((Join-Path $sourceRoot 'peds/Ped.cpp'))
function Extract([string]$text,[string]$name){
    $m=[regex]::Match($text,'(?m)^(?:static\s+)?(?:const\s+)?(?:VrRagdollSupport::Transform|Slot\s*\*|bool|void)\s*'+[regex]::Escape($name)+'\([^;]*?\)\s*\{')
    if(-not $m.Success){throw "Missing production function $name"}
    $end=$m.Index+$m.Length;$depth=1
    while($depth -gt 0 -and $end -lt $text.Length){if($text[$end] -eq '{'){$depth++};if($text[$end] -eq '}'){$depth--};$end++}
    if($depth -ne 0){throw "Unterminated $name"}
    return $text.Substring($m.Index,$end-$m.Index)
}
$declStart=$source.IndexOf('enum {')
$declEnd=$source.IndexOf('static bool enabled;')
$code=$source.Substring($declStart,$declEnd-$declStart)
$code+="`nstatic bool enabled; static int active, taken;`nenum { DENY_OFF,DENY_KIND,DENY_RANGE,DENY_SLOTS,DENY_BONES,DENY_COUNT };`nstatic int denied[DENY_COUNT];`n"
$start=$source.IndexOf('static const float TAKE_RANGE_SQ')
$end=$source.IndexOf("void`nSetEnabled",$start)
if($end -lt 0){$end=$source.IndexOf("void`r`nSetEnabled",$start)}
$code+=$source.Substring($start,$end-$start)
$code+="`nstatic void SeedVelocity(Slot*,CPed*);`n"
foreach($name in @('SetEnabled','IsEnabled','FindSlot','Presentation','ApplyPresentation','RefreshBounds','AcquireSlot','Thaw','StartRagdoll','ObserveAnimatedPose','ForgetAnimatedPose','InheritAnimatedMotion','SeedVelocity','Begin','BeginFall')){$code+="`n"+(Extract $source $name)}
if(-not $Baseline){foreach($name in @('TryLateAdmission','ExplosionImpulse')){$code+="`n"+(Extract $source $name)}}
foreach($name in @('Apply','Release')){$code+="`n"+(Extract $source $name)}
$code=('#define MIAMIVR_DEV_TOOLS '+[int]$DevTools.IsPresent)+"`n"+('#define OLD_BASELINE '+[int]$Baseline.IsPresent)+"`nnamespace VrRagdoll {`n"+$code+"`n}`n"
[IO.File]::WriteAllText((Join-Path $PSScriptRoot 'ragdoll-explosion-production.inc'),$code)
[IO.File]::WriteAllText((Join-Path $PSScriptRoot 'ragdoll-explosion-bones.inc'),[IO.File]::ReadAllText((Join-Path $sourceRoot 'animation/Bones.h')))
[IO.File]::WriteAllText((Join-Path $PSScriptRoot 'ragdoll-explosion-world.inc'),(Extract $world 'CWorld::TriggerExplosion'))
$force=[regex]::Match($world,'float fDamageMultiplier = Min\(\(fRadius - fMagnitude\)[\s\S]*?pEntity->ApplyMoveForce\(vecForceDir\);')
if(-not $force.Success){throw 'Native explosion expression not found'}
$forceText=$force.Value
$lift=[regex]::Match($world,'pPed->ApplyMoveForce\(0\.0, 0\.0, 2\.0f\);').Value
if(-not $lift){throw 'Native ped explosion lift not found'}
$gate=[regex]::Match($ped,'SetPedState\(PED_DIE\);[\s\S]*?if \(VrRagdoll::Begin\(this\)\)\s*animId = ANIM_STD_NUM;').Value
if(-not $gate){throw 'Native SetDie gate not found'}
$gate=$gate.Replace('SetPedState(','ped.SetPedState(').Replace('Begin(this)','Begin(&ped)')
$native="static void NativeForce(CPed &ped,const CVector &vecDistance,float fMagnitude,float fRadius,float fPower){`nCPed*pEntity=&ped;CPed*pPed=&ped;`n"+$forceText+"`n"+$lift+"`n}`nstatic void NativeDie(CPed &ped){int animId=0;`n"+$gate+"`n(void)animId;}`n"
[IO.File]::WriteAllText((Join-Path $PSScriptRoot 'ragdoll-explosion-native.inc'),$native)
Write-Host ('Ragdoll source SHA256: '+(Get-FileHash (Join-Path $sourceRoot 'peds/VrRagdoll.cpp')).Hash)
Write-Host ('World source SHA256: '+(Get-FileHash (Join-Path $sourceRoot 'core/World.cpp')).Hash)
& (Join-Path $PSScriptRoot 'test-ragdoll.ps1') -KitRoot $StageRoot -OutDir $OutDir -Sources @('test-ragdoll-explosion.cpp')

param(
    [string]$StageRoot = (Split-Path -Parent (Split-Path -Parent $PSScriptRoot)),
    [string]$OutDir = (Join-Path ([IO.Path]::GetTempPath()) ('vc-lifecycle-' + [Guid]::NewGuid().ToString('N')))
)
$ErrorActionPreference = 'Stop'
$sourcePath = Join-Path $StageRoot 'src\peds\VrRagdoll.cpp'
$source = [IO.File]::ReadAllText($sourcePath)
$functions = [Collections.Generic.List[string]]::new()
foreach ($name in @('FindSlot','Owns','SetBulletTrace','SkipBulletCollision','AcquireSlot','Thaw','Release')) {
    # Select each lifecycle primitive explicitly. Bounds/render helpers may
    # live between them; they have their own fixtures and engine dependencies.
    $signature = [regex]::Match($source, '(?m)^(?:static\s+)?(?:Slot\s*\*|bool|void)\s*' + [regex]::Escape($name) + '\([^)]*\)\s*\{')
    if (-not $signature.Success) { throw "Cannot find production lifecycle function: $name" }
    $bodyStart = $signature.Index + $signature.Length - 1
    $depth = 1
    $end = $bodyStart + 1
    while ($end -lt $source.Length -and $depth -gt 0) {
        if ($source[$end] -eq '{') { $depth++ }
        elseif ($source[$end] -eq '}') { $depth-- }
        $end++
    }
    if ($depth -ne 0) { throw "Unterminated production lifecycle function: $name" }
    $functions.Add($source.Substring($signature.Index, $end-$signature.Index))
}
if (-not [regex]::IsMatch($source, 'MAX_POSES\s*=\s*NUMPEDS')) { throw 'Persistent body capacity must match the native ped pool.' }
if ([regex]::IsMatch($source, '\bSleepingSlot\s*\(')) { throw 'Admission must not depend on finding a sleeping simulation owner.' }
$generated = Join-Path $PSScriptRoot 'ragdoll-lifecycle-production.inc'
[IO.File]::WriteAllText($generated, ($functions -join "`r`n"), [Text.UTF8Encoding]::new($false))
Write-Host ('VrRagdoll.cpp SHA256: ' + (Get-FileHash -LiteralPath $sourcePath -Algorithm SHA256).Hash)
& (Join-Path $PSScriptRoot 'test-ragdoll.ps1') -KitRoot $StageRoot -OutDir $OutDir -Sources @('test-ragdoll-lifecycle.cpp')

