param(
 [string]$StageRoot = (Split-Path -Parent (Split-Path -Parent $PSScriptRoot)),
 [string]$OutDir = (Join-Path ([IO.Path]::GetTempPath()) ('vc-entry-' + [Guid]::NewGuid().ToString('N')))
)
$ErrorActionPreference='Stop'
$src=Join-Path $StageRoot 'src'
if(-not(Test-Path -LiteralPath $src)){$src=Join-Path $StageRoot 'overlay/src'}
$ped=[IO.File]::ReadAllText((Join-Path $src 'peds/Ped.cpp'))
$ai=[IO.File]::ReadAllText((Join-Path $src 'peds/PedAI.cpp'))
$prologue=[regex]::Match($ped,'(?ms)(?<=CPed::ProcessControl\(void\)\r?\n\{\r?\n).*?(?=\tCColPoint foundCol;)').Value
if($prologue -notmatch 'vrEntryCancelInput.Update'){throw 'Missing production Quest entry observer.'}
$cancel=[regex]::Match($ped,'(?ms)^#ifdef CANCELLABLE_CAR_ENTER\r?\n\s*static bool cancelJack.*?^#endif(?=\r?\n\r?\n\s*switch \(m_nPedState\))').Value
if(-not $cancel){throw 'Missing production cancellation block.'}
$production='void CPed::ProcessEntryCancellation() {'+"`n"+$prologue+$cancel+"`n}`n"
# The exact former block supplies an executable regression demonstration.
$baseline=Join-Path $StageRoot 'baseline-qbuild/src/peds/Ped.cpp'
if(Test-Path -LiteralPath $baseline){
 $baselineText=[IO.File]::ReadAllText($baseline)
 $old=[regex]::Match($baselineText,'(?ms)^#ifdef CANCELLABLE_CAR_ENTER\r?\n\s*static bool cancelJack.*?^#endif(?=\r?\n\r?\n\s*switch \(m_nPedState\))').Value
 if(-not $old){throw 'Missing baseline cancellation block.'}
 $production+='void CPed::ProcessBaselineCancellation() {'+"`n"+$old+"`n}`n"
 $preserved=$ped.Replace($prologue,'').Replace($cancel,$old)
 $preserved=$preserved -replace '(?m)^#if defined\(__ANDROID__\) && defined\(GTA_VR_WEAPONS\) && defined\(CANCELLABLE_CAR_ENTER\)\r?\n#include "VrVehicleEntry.h"\r?\n#endif\r?\n',''
 if(($preserved -replace '\s','') -cne ($baselineText -replace '\s','')){throw 'Unexpected edit outside the Quest entry input gate.'}
 Write-Host 'Native Ped/ragdoll source preservation: PASS after removing only the new input gate.'
}else{
 # Public kits have no prior checkout. Retain an explicit baseline predicate
 # only for the old-behaviour demonstration; all fixed assertions use source.
 $old=$cancel -replace '(?ms)^#if defined\(__ANDROID__\) && defined\(GTA_VR_WEAPONS\)\r?\n\s*if \(vrCancelEntryMovement\) \{\r?\n#else\r?\n(.*?)^#endif','$1'
 $production+='void CPed::ProcessBaselineCancellation() {'+"`n"+$old+"`n}`n"
}
foreach($name in @('PedAnimAlignCB','PedAnimDoorOpenCB','PedAnimGetInCB','PedAnimDoorCloseCB')){
 $method=[regex]::Match($ai,'(?ms)^void\r?\nCPed::'+$name+'\([^\n]*\)\r?\n\{.*?^\}').Value
 if(-not $method){throw ('Missing native callback '+$name)}
 $production+=$method+"`n"
}
$enumNames=[regex]::Matches($production,'\b(?:ANIM_\w+|ASSOCGRP_\w+|PEDTYPE_\w+|PED_\w+|OBJECTIVE_\w+|VEHICLE_APPEARANCE_\w+|DOOR_STATUS_\w+|CARLOCK_\w+|CAR_DOOR_\w+|CAR_WINDSCREEN|STATUS_\w+|MISSION_\w+|SOUND_\w+)\b') | ForEach-Object {$_.Value}
$enumNames=@($enumNames)+@('STATUS_ABANDONED','CARLOCK_UNLOCKED','PEDTYPE_PLAYER1','PED_IDLE','PED_ENTER_CAR','CARLOCK_LOCKED','STATUS_WRECKED','ANIM_STD_CAR_ALIGN_DOOR_LHS') | Sort-Object -Unique
[IO.File]::WriteAllText((Join-Path $PSScriptRoot 'vr-vehicle-entry-enums.inc'),('enum { '+($enumNames -join ',')+' };'),[Text.UTF8Encoding]::new($false))
$header=[IO.Path]::GetFullPath((Join-Path $src 'peds/VrVehicleEntry.h')).Replace('\','/')
[IO.File]::WriteAllText((Join-Path $PSScriptRoot 'vr-vehicle-entry-production.inc'),$production,[Text.UTF8Encoding]::new($false))
[IO.File]::WriteAllText((Join-Path $PSScriptRoot 'vr-vehicle-entry-helper.inc'),('#include "'+$header+'"'),[Text.UTF8Encoding]::new($false))
Write-Host ('Production Ped.cpp SHA256: '+(Get-FileHash -LiteralPath (Join-Path $src 'peds/Ped.cpp')).Hash)
Write-Host ('Production callbacks SHA256: '+(Get-FileHash -LiteralPath (Join-Path $src 'peds/PedAI.cpp')).Hash)
Write-Host ('Production input latch SHA256: '+(Get-FileHash -LiteralPath $header).Hash)
& (Join-Path $PSScriptRoot 'test-ragdoll.ps1') -KitRoot $StageRoot -OutDir $OutDir -Sources @('test-vr-vehicle-entry.cpp')
if($LASTEXITCODE -ne 0){throw 'Quest vehicle entry test failed.'}

param(
    [Parameter(Mandatory=$true)][string]$StageRoot,
    [string]$OutDir = (Join-Path ([IO.Path]::GetTempPath()) ('lcvr-wheel-fps-' + [Guid]::NewGuid().ToString('N')))
)
$ErrorActionPreference = 'Stop'
$StageRoot = [IO.Path]::GetFullPath($StageRoot)
$OutDir = [IO.Path]::GetFullPath($OutDir)
function Extract-Block([string]$text, [string]$pattern) {
    $match = [regex]::Match($text, $pattern)
    if (-not $match.Success) { throw "Missing production definition: $pattern" }
    $end = $match.Index + $match.Length; $depth = 1
    while ($depth -gt 0 -and $end -lt $text.Length) {
        if ($text[$end] -eq '{') { $depth++ }
        elseif ($text[$end] -eq '}') { $depth-- }
        $end++
    }
    if ($depth -ne 0) { throw 'Unterminated production definition.' }
    $text.Substring($match.Index, $end - $match.Index)
}
$physical = [IO.File]::ReadAllText((Join-Path $StageRoot 'src/entities/Physical.cpp'))
$header = [IO.File]::ReadAllText((Join-Path $StageRoot 'src/entities/Physical.h'))
$vehicle = [IO.File]::ReadAllText((Join-Path $StageRoot 'src/vehicles/Vehicle.cpp'))
$auto = [IO.File]::ReadAllText((Join-Path $StageRoot 'src/vehicles/Automobile.cpp'))
$config = [IO.File]::ReadAllText((Join-Path $StageRoot 'src/core/config.h'))
$output = [regex]::Match($header, '(?m)^#define GRAVITY[^\r\n]+').Value + "`n"
if ([regex]::IsMatch($config, '(?m)^\s*#\s*define FIX_SIGNIFICANT_BUGS\b')) { $output += "#define FIX_SIGNIFICANT_BUGS`n" }
foreach ($name in @('GetSpeed','ApplyMoveSpeed','ApplyMoveForce','ApplyTurnForce','ApplySpringCollision','ApplySpringDampening','ApplyGravity','ApplyAirResistance')) {
    $output += (Extract-Block $physical ('(?m)^(?:CVector|void|bool)\s+CPhysical::' + $name + '\([^)]*\)\s*\{')) + "`n"
}
$mass = Extract-Block $header 'float GetMass\([^)]*\)\s*\{'
$output += $mass.Replace('float GetMass', 'float CPhysical::GetMass') + "`n"
$constants = [regex]::Match($vehicle, '(?m)^float fBurstSpeedMax[^;]+;\s*float fBurstTyreMod[^;]+;')
if (-not $constants.Success) { throw 'Missing burst tyre constants.' }
$output += $constants.Value + "`n" + (Extract-Block $vehicle '(?m)^void\s+CVehicle::ProcessWheel\([^)]*\)\s*\{') + "`n"
$timer = [regex]::Match($auto, '(?s)if\(m_aSuspensionSpringRatio\[i\] < 1.0f\)\s*m_aWheelTimer\[i\] = 4.0f;\s*else\s*m_aWheelTimer\[i\] = Max\([^;]+;')
if (-not $timer.Success) { throw 'Missing wheel contact grace period.' }
$output += "static void ProductionContactTimer(float ratio, float &timer) { int i=0; float m_aSuspensionSpringRatio[1]={ratio}; float m_aWheelTimer[1]={timer};`n" + $timer.Value + "`ntimer=m_aWheelTimer[0]; }`n"
[IO.File]::WriteAllText((Join-Path $PSScriptRoot 'wheel-suspension-fps-production.inc'), $output, [Text.UTF8Encoding]::new($false))
& (Join-Path $PSScriptRoot 'test-ragdoll.ps1') -KitRoot $StageRoot -OutDir $OutDir -Sources @('test-wheel-suspension-fps.cpp')
if ($LASTEXITCODE -ne 0) { throw 'Wheel fixture compilation/smoke checks failed.' }
$exe = Join-Path $OutDir 'test-wheel-suspension-fps.exe'
$rows = [Collections.Generic.List[string]]::new()
$rows.Add('scenario,fps,pacing,wall_s,sim_s,stop_s,distance_m,forward_mps,lateral_mps,heading_deg,min_height_m,max_height_m,peak_vertical_mps,skid_fraction,locked_fraction,sign_reversals,contact_grace_ms,final_height_m,residual_vertical_span_m')
foreach ($scenario in @('brake','coast','lateral','steer','drop','bump','grace','history-clean','history-primed')) {
    foreach ($fps in @(15,18,20,30,36,60,72,80,90,120,144)) {
        foreach ($pacing in @('steady','jitter','stall')) {
            # Fresh process: native ProcessWheel statics must not leak between
            # scenarios/frame rates. The history pair intentionally probes them.
            $line = & $exe $scenario $fps $pacing
            if ($LASTEXITCODE -ne 0) { throw "Failed: $scenario $fps $pacing" }
            $rows.Add(($line -join ''))
        }
    }
}
[IO.File]::WriteAllLines((Join-Path $OutDir 'measurements.csv'), $rows)
$hashes = @('src/entities/Physical.cpp','src/entities/Physical.h','src/vehicles/Vehicle.cpp','src/vehicles/Automobile.cpp','src/core/config.h') | ForEach-Object {
    Get-FileHash -LiteralPath (Join-Path $StageRoot $_) | Select-Object Path,Hash
}
$hashes | ConvertTo-Json | Set-Content -LiteralPath (Join-Path $OutDir 'source-hashes.json')
Write-Host ('PASS: ' + ($rows.Count-1) + ' isolated controlled-rate scenarios; measurements: ' + (Join-Path $OutDir 'measurements.csv'))

param(
    [Parameter(Mandatory=$true)][string]$StageRoot,
    [string]$OutDir = (Join-Path $env:TEMP ('lcvr-billboards-' + [guid]::NewGuid().ToString('N')))
)
$ErrorActionPreference='Stop'
$kitRoot=Split-Path (Split-Path $PSScriptRoot -Parent) -Parent
$kitHeader=Join-Path $kitRoot 'overlay/src/renderer/QuestBillboard.h'
$stageHeader=Join-Path $StageRoot 'src/renderer/QuestBillboard.h'
if((Get-FileHash $kitHeader).Hash -ne (Get-FileHash $stageHeader).Hash){
    throw 'Assembled billboard helper differs from the production header under test.'
}
$sprite=Get-Content -Raw (Join-Path $StageRoot 'src/renderer/Sprite.cpp')
$world=$sprite.Substring(0,$sprite.IndexOf('CSprite::Set6Vertices2D'))
if($world -notmatch 'window->x, window->y, worldUp, worldEast' -or
   $world -notmatch 'worldUp\[3\] = \{ -camera->right.z, camera->up.z, camera->at.z \}'){
    throw 'Billboards must receive world axes expressed in the actual render camera frame.'
}
if(([regex]::Matches($world,'FaceQuestWorldSprite\((?:vert|verts), [46], x, y\);')).Count -ne 6){
    throw 'All six world sprite routines must orient the complete quad.'
}
if(([regex]::Matches($world,'if\(!QuestWorldBillboardsEnabled\(\)\)')).Count -ne 6){
    throw 'Legacy mono clipping must be bypassed before stereo reorientation.'
}
if($sprite.Substring($sprite.IndexOf('CSprite::Set6Vertices2D')) -match 'FaceQuestWorldSprite'){
    throw 'Screen-space sprites must retain their original geometry.'
}
if($world -notmatch 'return !androidgame::VrShouldUseTheaterMode\(\);'){
    throw 'The mono theater path must retain its existing projection.'
}
$shader=Get-Content -Raw (Join-Path $StageRoot 'vendor/librw/src/vulkan/shaders/rw_im2d.vert')
$clouds=Get-Content -Raw (Join-Path $StageRoot 'src/renderer/Clouds.cpp')
if($clouds -notmatch '(?s)if\(!androidgame::VrShouldUseTheaterMode\(\)\)\{\s*CClouds::ms_cameraRoll = 0.0f;\s*return;'){
    throw 'Clouds must not apply the old camera-roll correction over the world-oriented billboard.'
}
if($shader -notmatch 'worldBillboard \? inPosition.w : max\(inPosition.w, panel\)'){
    throw 'Near world sprites must not be clamped to the HUD plane.'
}
& (Join-Path $PSScriptRoot 'test-ragdoll.ps1') -OutDir $OutDir -Sources @('test-world-billboards.cpp')
if($LASTEXITCODE -ne 0){ throw 'Billboard geometry tests failed.' }

param(
 [string]$KitRoot=(Split-Path -Parent (Split-Path -Parent $PSScriptRoot)),
 [Parameter(Mandatory=$true)][string]$ProfileRoot,
 [Parameter(Mandatory=$true)][string]$OutDir
)
$ErrorActionPreference="Stop"
if(Test-Path -LiteralPath $OutDir){throw 'Use a fresh output directory.'}
New-Item -ItemType Directory -Path $OutDir | Out-Null
$OutDir=(Resolve-Path -LiteralPath $OutDir).Path
$ProfileRoot=(Resolve-Path -LiteralPath $ProfileRoot).Path
$source=[IO.File]::ReadAllText((Join-Path $KitRoot 'tools/install-modern-models.ps1')).Replace("`r`n","`n")
$helper=(Join-Path $KitRoot 'tools/modelsets/xbox-modelset.ps1').Replace("'","''")
$source=$source.Replace('(Join-Path $PSScriptRoot "modelsets/xbox-modelset.ps1")',"'$helper'")
$marker='try {'+"`n"+'    Write-Host "Vice City VR - $Profile model installer'
$at=$source.IndexOf($marker)
if($at -lt 0){throw 'Production installer main block missing.'}
$mock=@'
function Find-Adb { return 'fixture-adb' }
function Invoke-NativeCapture {
 param([string]$FilePath,[string[]]$Arguments)
 if($FilePath -ne 'fixture-adb'){throw 'A real native command was attempted.'}
 [IO.File]::AppendAllText($env:XBOX_TEST_CALLS,(([pscustomobject]@{args=@($Arguments)} | ConvertTo-Json -Compress)+"`n"))
 $a=@($Arguments)
 if($a.Count -ge 2 -and $a[0] -eq '-s'){$a=@($a | Select-Object -Skip 2)}
 $code=0;$lines=@('ok')
 if($a[0] -eq 'devices'){$lines=@('List of devices attached','fixture-quest device product:test')}
 elseif($a[0] -eq 'shell' -and $a[1] -eq 'pm'){$lines=@('package:/data/app/fixture.apk')}
 elseif($a[0] -eq 'shell' -and ($a[1] -eq 'stat' -or $a[1] -eq 'sha256sum')){
   $remote=$a[-1]
   if($remote -notmatch '/\.xbox-incoming-[^/]+/(.+)$'){throw "Unexpected verification path: $remote"}
   $local=Join-Path $env:XBOX_TEST_PROFILE $Matches[1]
   if($a[1] -eq 'stat'){$lines=@([string](Get-Item -LiteralPath $local).Length)}
   else {
     $hash=(Get-FileHash -LiteralPath $local -Algorithm SHA256).Hash
     if($env:XBOX_TEST_FAIL -eq 'hash'){$hash='0'*64}
     $lines=@("$hash  $remote")
   }
 }
 elseif($a[0] -eq 'shell' -and $a[1] -eq 'chmod' -and $env:XBOX_TEST_FAIL -eq 'permissions'){$code=1;$lines=@('fixture permission failure')}
 elseif($a[0] -eq 'shell' -and $a[1] -eq 'mv' -and $a[2] -match '/\.xbox-incoming-' -and $env:XBOX_TEST_FAIL -eq 'commit'){$code=1;$lines=@('fixture rename failure')}
 return [pscustomobject]@{ExitCode=$code;Lines=$lines}
}
'@
$harness=$source.Substring(0,$at)+$mock+"`n"+$source.Substring($at)
$script=Join-Path $OutDir 'installer-production.ps1'
[IO.File]::WriteAllText($script,$harness,[Text.UTF8Encoding]::new($false))
$checks=0
function Check([bool]$Result,[string]$What){$script:checks++;if(-not $Result){throw $What}}
$saved=@{}
foreach($name in @('XBOX_TEST_PROFILE','XBOX_TEST_FAIL','XBOX_TEST_CALLS')){$saved[$name]=[Environment]::GetEnvironmentVariable($name)}
try {
 foreach($failure in @('none','hash','commit','permissions')) {
  $env:XBOX_TEST_PROFILE=$ProfileRoot;$env:XBOX_TEST_FAIL=$failure;$env:XBOX_TEST_CALLS=Join-Path $OutDir "$failure-calls.jsonl"
  & powershell.exe -NoProfile -ExecutionPolicy Bypass -File $script -ModernDir $ProfileRoot -Profile Xbox -NonInteractive -LogPath (Join-Path $OutDir "$failure-transcript.log") *> (Join-Path $OutDir "$failure-output.log")
  $result=$LASTEXITCODE
  Check (($result -eq 0) -eq ($failure -eq 'none')) "Wrong installer result for $failure"
  $calls=@([IO.File]::ReadAllLines($env:XBOX_TEST_CALLS) | ForEach-Object {($_ | ConvertFrom-Json).args -join ' '})
  Check (@($calls | Where-Object {$_ -match 'uninstall|shell am start|vr_settings|gta_vc\.set|/modelsets/modern'}).Count -eq 0) 'Xbox path touched another profile, settings, uninstall or launch'
  Check (@($calls | Where-Object {$_ -match ' push '}).Count -eq 7) 'Not exactly seven profile files transferred'
  Check (@($calls | Where-Object {$_ -match 'shell sha256sum'}).Count -eq $(if($failure -eq 'hash'){1}elseif($failure -eq 'permissions'){0}else{7})) 'Unexpected profile hash checks'
  $grant=@($calls | Where-Object {$_ -match 'shell chmod -R a\+rX .*/\.xbox-incoming-[^/ ]+$'})
  Check ($grant.Count -eq 1) 'Missing application read/traverse access for staged profile'
  $moves=@($calls | Where-Object {$_ -match 'shell mv'})
  if($moves.Count) { Check ([array]::IndexOf($calls,$grant[0]) -lt [array]::IndexOf($calls,$moves[0])) 'Permissions granted after activation' }
  if($failure -eq 'hash' -or $failure -eq 'permissions') { Check ($moves.Count -eq 0) 'Hash mismatch moved active profile' }
  elseif($failure -eq 'commit') {
   Check ($moves.Count -eq 3) 'Commit failure did not restore old profile'
   Check ($moves[-1] -match '/\.xbox-backup-[^ ]+ .*/xbox$') 'Wrong rollback destination'
  } else {
   Check ($moves.Count -eq 2) 'Atomic replacement did not stage/backup old profile'
   Check ($moves[1] -match '/\.xbox-incoming-[^ ]+ .*/xbox$') 'Wrong committed profile'
  }
 }
} finally {foreach($name in $saved.Keys){[Environment]::SetEnvironmentVariable($name,$saved[$name])}}
@{checks=$checks;deviceCommands=0;production=(Get-FileHash -LiteralPath (Join-Path $KitRoot 'tools/install-modern-models.ps1') -Algorithm SHA256).Hash} | ConvertTo-Json | Set-Content -LiteralPath (Join-Path $OutDir 'results.json')
Write-Host "PASS $checks production Xbox installer routing/verification/rollback checks; mocked ADB only."

# Updates this source kit, then builds and installs only its APK.
[CmdletBinding()]
param(
    [string]$WorkDir = "C:\LCVRBuild",
    [string]$AndroidSdk,
    [string]$JavaHome,
    [string]$Serial,
    [switch]$BuildOnly,
    [switch]$Release,
    [switch]$NonInteractive,
    [switch]$DryRun
)
$ErrorActionPreference = "Stop"
$ProgressPreference = "SilentlyContinue"

function Invoke-UpdateGit {
    param([string]$Directory, [string[]]$Arguments)
    $previousPreference = $ErrorActionPreference
    $ErrorActionPreference = "Continue"
    try {
        $output = @(& $script:UpdateGit -C $Directory @Arguments 2>&1)
        $code = $LASTEXITCODE
    } finally { $ErrorActionPreference = $previousPreference }
    if ($code -ne 0) {
        throw "Git $($Arguments[0]) failed (exit $code). $($output -join [Environment]::NewLine)"
    }
    # Git progress and warnings on stderr are not command results.
    $stdout = @($output | Where-Object { $_ -isnot [Management.Automation.ErrorRecord] })
    $output | Where-Object { $_ -is [Management.Automation.ErrorRecord] } | ForEach-Object { Write-Host $_ }
    return ($stdout -join [Environment]::NewLine).Trim()
}

function Find-UpdateGit {
    param([string]$CacheRoot, [switch]$ReadOnly)
    $installed = Get-Command git.exe -ErrorAction SilentlyContinue
    if ($null -ne $installed) { return $installed.Source }
    $version = "2.55.0.3"
    $gitDirectory = Join-Path $CacheRoot ".tools/MinGit-$version"
    $gitExecutable = Join-Path $gitDirectory "cmd/git.exe"
    if (Test-Path -LiteralPath $gitExecutable -PathType Leaf) { return $gitExecutable }
    if ($ReadOnly) { return $null }
    $downloadDirectory = Join-Path $CacheRoot ".downloads"
    $archive = Join-Path $downloadDirectory "MinGit-$version-64-bit.zip"
    New-Item -ItemType Directory -Path $downloadDirectory -Force | Out-Null
    if (-not (Test-Path -LiteralPath $archive -PathType Leaf)) {
        Write-Host "Downloading portable Git once; it will share the build tool cache."
        [Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12
        Invoke-WebRequest -UseBasicParsing -Uri "https://github.com/git-for-windows/git/releases/download/v2.55.0.windows.3/MinGit-2.55.0.3-64-bit.zip" -OutFile $archive
    }
    $expected = "F48E2D2DC74A24454ADC6D8FD0AC25BF9C2386F19CFB06202B9465AAAD4F9F05"
    if ((Get-FileHash -Algorithm SHA256 -LiteralPath $archive).Hash -ne $expected) {
        throw "Portable Git archive checksum failed: $archive. No update was attempted."
    }
    Expand-Archive -LiteralPath $archive -DestinationPath $gitDirectory -Force
    if (-not (Test-Path -LiteralPath $gitExecutable -PathType Leaf)) { throw "Portable Git extraction failed." }
    return $gitExecutable
}

function Get-UpdateVersion {
    param([string]$GradleText)
    $versions = [regex]::Matches($GradleText, '(?m)^\s*versionCode\s*=\s*(\d+)\s*$')
    if ($versions.Count -ne 1) { throw "Cannot verify the source kit versionCode; no build or installation will run." }
    return [int]$versions[0].Groups[1].Value
}

function Get-LocalUpdateVersion {
    param([string]$Directory)
    $file = Join-Path $Directory "overlay/android/app/build.gradle.kts"
    if (-not (Test-Path -LiteralPath $file -PathType Leaf)) { throw "Incomplete source kit: $file is missing." }
    return Get-UpdateVersion (Get-Content -Raw -LiteralPath $file)
}

function Assert-UpdateCheckout {
    param([string]$Directory)
    $top = Invoke-UpdateGit $Directory @("rev-parse", "--show-toplevel")
    if ([IO.Path]::GetFullPath($top).TrimEnd('\','/') -ne [IO.Path]::GetFullPath($Directory).TrimEnd('\','/')) {
        throw "The update directory belongs to a different enclosing Git repository. It was left untouched."
    }
    $remote = Invoke-UpdateGit $Directory @("remote", "get-url", "origin")
    $allowedRemotes = @(
        "https://github.com/kornacious/liberty-city-vr-quest.git",
        "https://github.com/kornacious/liberty-city-vr-quest"
    )
    if ($remote -cnotin $allowedRemotes) {
        Write-Host "Note: Origin remote is $remote"
    }
    $branch = Invoke-UpdateGit $Directory @("symbolic-ref", "--short", "HEAD")
    if ($branch -cne "master") { throw "UPDATE requires the master branch. Your current branch was left untouched." }
    $changes = Invoke-UpdateGit $Directory @("status", "--porcelain", "--untracked-files=no")
    if ($changes) { throw "Local source changes were found. Commit or back them up yourself before updating; UPDATE does not reset or stash them." }
    return Invoke-UpdateGit $Directory @("rev-parse", "HEAD")
}

function Update-SourceKit {
    param([string]$LocalKit, [string]$CacheRoot, [switch]$ReadOnly)
    $minimumVersion = [Math]::Max(520, (Get-LocalUpdateVersion $LocalKit))
    $source = $LocalKit
    if (-not (Test-Path -LiteralPath (Join-Path $source ".git"))) {
        $source = Join-Path $CacheRoot "source-kit"
        Write-Host "ZIP source kit: updates use the persistent Git copy at $source"
        Write-Host "This ZIP folder and its private files stay unchanged."
        if (Test-Path -LiteralPath $source) {
            if (-not (Test-Path -LiteralPath (Join-Path $source ".git"))) {
                throw "The managed source-kit directory already exists without Git. It was left untouched: $source"
            }
        } elseif ($ReadOnly) {
            Write-Host "DRY RUN: would clone the official master branch once, then verify versionCode >= $minimumVersion."
            return $null
        } else {
            New-Item -ItemType Directory -Force -Path $CacheRoot | Out-Null
            Invoke-UpdateGit $CacheRoot @("clone", "--single-branch", "--branch", "master", "https://github.com/kornacious/liberty-city-vr-quest.git", $source) | Out-Host
        }
    }
    $before = Assert-UpdateCheckout $source
    $minimumVersion = [Math]::Max($minimumVersion, (Get-LocalUpdateVersion $source))
    if ($ReadOnly) {
        Write-Host "DRY RUN: would fetch master, require a fast-forward and versionCode >= $minimumVersion, then build using $CacheRoot."
        Write-Host "DRY RUN: APK update only; no commands were sent to a Quest."
        return $null
    }
    Write-Host "Fetching source changes..."
    Invoke-UpdateGit $source @("fetch", "origin", "master") | Out-Host
    $revision = Invoke-UpdateGit $source @("rev-parse", "FETCH_HEAD")
    $version = Get-UpdateVersion (Invoke-UpdateGit $source @("show", "${revision}:overlay/android/app/build.gradle.kts"))
    if ($version -lt $minimumVersion) {
        throw "The published source is versionCode $version; this kit requires at least $minimumVersion. The new version may not be published yet, or your local kit is newer. No build or installation was started."
    }
    $assetsMarker = Invoke-UpdateGit $source @("ls-tree", "--name-only", $revision, "--", "tools/update-required-assets.txt")
    if ($assetsMarker) {
        throw "This source version requires updated bundled assets. UPDATE leaves game data unchanged. Download that release and run its normal BUILD_AND_INSTALL separately after reading its asset instructions."
    }
    $base = Invoke-UpdateGit $source @("merge-base", $before, $revision)
    if ($base -ne $before) { throw "Local commits diverge from the published version. No merge, reset, build or installation was attempted." }
    $checkedHead = Assert-UpdateCheckout $source
    if ($checkedHead -ne $before) { throw "The source checkout changed during the update. Retry after the other Git operation finishes." }
    Invoke-UpdateGit $source @("-c", "merge.autostash=false", "merge", "--ff-only", "--no-overwrite-ignore", $revision) | Out-Host
    if ((Assert-UpdateCheckout $source) -ne $revision) {
        throw "The source checkout changed after the merge. No build or installation was started."
    }
    if ((Get-LocalUpdateVersion $source) -ne $version) { throw "Updated version verification failed; no build will run." }
    Write-Host "Source ready: versionCode $version. Reusing downloaded build tools and the clean re3 base."
    return $source
}

function Invoke-UpdatedBuild {
    param([string]$Source, [hashtable]$Options)
    $builder = Join-Path $Source "tools/build-and-install.ps1"
    if (-not (Test-Path -LiteralPath $builder -PathType Leaf)) { throw "The updated kit is missing its build script." }
    $command = Get-Command -Name $builder -ErrorAction Stop
    if (-not $command.Parameters.ContainsKey("UpdateOnly")) {
        throw "The published builder does not support safe APK-only updates yet. No installation was attempted."
    }
    if ($Options.ContainsKey("Release") -and $Options.Release -and -not $command.Parameters.ContainsKey("Release")) {
        throw "The published builder does not support release signing yet. No installation was attempted."
    }
    & $builder @Options -UpdateOnly
    if (-not $?) { throw "The build/update script failed. Read its diagnostic log." }
}

try {
    $cache = [IO.Path]::GetFullPath($WorkDir)
    $localKit = Split-Path $PSScriptRoot -Parent
    $script:UpdateGit = Find-UpdateGit -CacheRoot $cache -ReadOnly:$DryRun
    if ($DryRun -and -not $script:UpdateGit) {
        Write-Host "DRY RUN: Git is not installed. An actual run would download and verify portable Git once in $cache."
        return
    }
    $source = Update-SourceKit -LocalKit $localKit -CacheRoot $cache -ReadOnly:$DryRun
    if ($DryRun) { return }
    $options = @{ WorkDir = $cache; BuildOnly = $BuildOnly; NonInteractive = $NonInteractive }
    if ($Release) { $options.Release = $true }
    if ($AndroidSdk) { $options.AndroidSdk = $AndroidSdk }
    if ($JavaHome) { $options.JavaHome = $JavaHome }
    if ($Serial) { $options.Serial = $Serial }
    Invoke-UpdatedBuild -Source $source -Options $options
} catch {
    Write-Host "ERROR: $($_.Exception.Message)" -ForegroundColor Red
    exit 1
}

param(
    [Parameter(Mandatory=$true)][ValidateSet('Record','Replay','Stop','Status','Pull')][string]$Action,
    [Parameter(Mandatory=$true)][string]$Serial,
    [ValidatePattern('^[A-Za-z0-9_-]{1,32}$')][string]$Label='trial',
    [ValidateRange(1,120)][int]$Seconds=30,
    [string]$OutDir,
    [string]$Adb='adb'
)
$ErrorActionPreference='Stop'
$remote='/sdcard/Android/data/com.libertyvr.quest/files/vehicle-capture'
function Invoke-Adb([string[]]$Arguments){
    $result=& $Adb -s $Serial @Arguments
    if($LASTEXITCODE-ne0){throw "ADB command failed: $($Arguments[0])"}
    $result
}
$model=(Invoke-Adb -Arguments @('shell','getprop','ro.product.model') | Out-String).Trim()
if($model-ne'Quest 3'){throw "Expected a verified Quest 3; $Serial reports '$model'."}
if($Action-eq'Status'){Invoke-Adb -Arguments @('shell','cat',"$remote/status.txt");exit}
if($Action-eq'Pull'){$command='stop'}
elseif($Action-eq'Record'){$command="record $Label $Seconds"}
elseif($Action-eq'Replay'){$command="replay $Label"}
else{$command='stop'}
Invoke-Adb -Arguments @('shell','mkdir','-p',$remote) | Out-Null
$taskRoot=Split-Path $PSScriptRoot -Parent
$scratch=Join-Path $taskRoot '.cache/vehicle-capture-commands'
[void][IO.Directory]::CreateDirectory($scratch)
$local=Join-Path $scratch ([Guid]::NewGuid().ToString('N')+'.txt')
[IO.File]::WriteAllText($local,$command+"`n",[Text.UTF8Encoding]::new($false))
Invoke-Adb -Arguments @('push',$local,"$remote/control.pending") | Out-Null
Invoke-Adb -Arguments @('shell','mv',"$remote/control.pending","$remote/control.txt") | Out-Null
$deadline=[DateTime]::UtcNow.AddSeconds(6)
do{
    & $Adb -s $Serial shell test -e "$remote/control.txt"
    if($LASTEXITCODE-ne0){break}
    Start-Sleep -Milliseconds 250
}while([DateTime]::UtcNow-lt$deadline)
if([DateTime]::UtcNow-ge$deadline){throw 'Command remains pending: run a capture-enabled APK in unpaused gameplay. No input replay has been confirmed.'}
$status=(Invoke-Adb -Arguments @('shell','cat',"$remote/status.txt") | Out-String).Trim()
Write-Host $status
if($Action-eq'Pull'){
    if($status-ne'stopped'){throw 'Capture did not close cleanly; inspect status before pulling.'}
    if(-not$OutDir){$OutDir=Join-Path $taskRoot ('.cache/vehicle-traces/'+[DateTime]::Now.ToString('yyyyMMdd-HHmmss'))}
    if(Test-Path -LiteralPath $OutDir){throw 'Choose a new output directory.'}
    [void][IO.Directory]::CreateDirectory($OutDir)
    Invoke-Adb -Arguments @('pull',"$remote/.",[IO.Path]::GetFullPath($OutDir))
}elseif(($Action-eq'Record'-and$status-notin@('recording','duration complete'))-or($Action-eq'Replay'-and$status-notlike'replaying:*'-and$status-ne'replay complete')){
    throw "Requested $Action did not start: $status"
}

[CmdletBinding()]
param(
    [string]$BuildDir = '',
    [string]$OutputDir = '',
    [string]$CMake = '',
    [string]$PythonRuntime = '',
    [switch]$Package
)
$ErrorActionPreference = 'Stop'
# Windows PowerShell can evaluate parameter defaults before PSScriptRoot is set.
# Resolve script-relative defaults after binding; explicit paths remain supported.
if (-not $BuildDir) { $BuildDir = Join-Path $PSScriptRoot '../../out/vehicle-editor-build' }
if (-not $OutputDir) { $OutputDir = Join-Path $PSScriptRoot '../../out/vehicle-editor' }
if (-not $CMake) {
    $found = Get-Command cmake -ErrorAction SilentlyContinue
    if ($found) { $CMake = $found.Source }
    elseif (Test-Path C:/LCVRBuild/.android-sdk/cmake/3.22.1/bin/cmake.exe) {
        $CMake = 'C:/LCVRBuild/.android-sdk/cmake/3.22.1/bin/cmake.exe'
    } else { throw 'Install CMake 3.22+ or pass -CMake.' }
}
$vswhere = Join-Path ${env:ProgramFiles(x86)} 'Microsoft Visual Studio/Installer/vswhere.exe'
if (-not (Get-Command cl -ErrorAction SilentlyContinue)) {
    $vs = & $vswhere -latest -products '*' -requires Microsoft.VisualStudio.Component.VC.Tools.x86.x64 -property installationPath
    if (-not $vs) { throw 'Visual Studio C++ tools are required.' }
    [void][IO.Directory]::CreateDirectory([IO.Path]::GetFullPath($BuildDir))
    $envScript = Join-Path ([IO.Path]::GetFullPath($BuildDir)) 'compiler-env.cmd'
    Set-Content -LiteralPath $envScript -Value ('@call "' + $vs + '\VC\Auxiliary\Build\vcvars64.bat" >nul'), '@set'
    $compilerEnvironment = & $env:ComSpec /d /c $envScript
    foreach ($line in $compilerEnvironment) {
        if ($line -match '^([^=]+)=(.*)$') { [Environment]::SetEnvironmentVariable($matches[1], $matches[2], 'Process') }
    }
}
$cmakeDir = Split-Path $CMake
$ninja = Join-Path $cmakeDir 'ninja.exe'
$options = @('-S', $PSScriptRoot, '-B', $BuildDir, '-G', 'Ninja', '-DCMAKE_BUILD_TYPE=Release')
if (Test-Path $ninja) { $options += "-DCMAKE_MAKE_PROGRAM=$ninja" }
if ($PythonRuntime) {
    $PythonRuntime = [IO.Path]::GetFullPath($PythonRuntime)
    $runtimePython = Join-Path $PythonRuntime python.exe
    if (-not (Test-Path -LiteralPath $runtimePython)) { throw 'The Python runtime folder must contain python.exe.' }
    $options += "-DVEHICLE_EDITOR_PYTHON_RUNTIME=$PythonRuntime"
    $options += "-DPython3_EXECUTABLE=$runtimePython"
}
& $CMake @options
if ($LASTEXITCODE) { throw 'Editor configuration failed.' }
& $CMake --build $BuildDir --target liberty-vehicle-editor placement-tests placement-runtime-tests placement-process-tests --parallel
if ($LASTEXITCODE) { throw 'Editor compilation failed.' }
& (Join-Path $cmakeDir ctest.exe) --test-dir $BuildDir --output-on-failure
if ($LASTEXITCODE) { throw 'Placement tests failed.' }
& $CMake --install $BuildDir --prefix $OutputDir
if ($LASTEXITCODE) { throw 'Editor installation failed.' }
if ($Package) {
    Push-Location $BuildDir
    try { & (Join-Path $cmakeDir cpack.exe) -G ZIP; if ($LASTEXITCODE) { throw 'Packaging failed.' } }
    finally { Pop-Location }
}
Write-Host "Editor: $OutputDir/liberty-vehicle-editor.exe"

#!/usr/bin/env python3
"""Local-only placement transfer. Never prints device identifiers or ADB output."""
import argparse
import configparser
import datetime
import math
import os
from pathlib import Path
import re
import shutil
import subprocess
import sys
import tempfile
import time
import uuid

ROOT = '/sdcard/Android/data/com.libertyvr.quest/files/gamedata'
PACKAGE = 'com.libertyvr.quest'
FILES = {kind: f'vehicle_placements.{kind}.ini' for kind in ('bundled', 'template', 'personal')}
EMPTY = '[Placement]\nVersion=1\n'


class BridgeError(Exception):
    pass


def limits(key):
    if key == 'WheelRadius':
        return 8, 40
    if key in ('WheelVisible', 'DashFollowWheel'):
        return 0, 1
    if re.fullmatch(r'(Dash|Map|Status|Clock|Ammo|Radio|Speedometer)Size', key):
        return 40, 250
    if re.fullmatch(r'(Wheel|Dash|Map|Status|Clock|Ammo|Radio|Speedometer)(X|Y|Z)', key):
        return -200, 200
    if re.fullmatch(r'(Wheel|Dash|Map|Status|Clock|Ammo|Radio|Speedometer)(Pitch|Yaw|Roll)', key):
        return (-90, 90) if key.startswith('Wheel') else (-180, 180)
    if re.fullmatch(r'(Default)?Seat(Height|Distance)', key):
        return (-200, 250) if key.endswith('Height') else (-200, 200)
    raise BridgeError('Unknown placement field')


def parse(text):
    if len(text) > 4 * 1024 * 1024:
        raise BridgeError('Placement pack exceeds limits')
    c = configparser.ConfigParser(interpolation=None, strict=True)
    c.optionxform = str
    try:
        c.read_string(text)
        if c.defaults() or c.get('Placement', 'Version') != '1' or set(c['Placement']) != {'Version'}:
            raise BridgeError('Unsupported placement version')
        result = {}
        for section in c.sections():
            if section == 'Placement':
                continue
            if not re.fullmatch(r'(classic|modern|xbox):[0-9]{1,5}', section):
                raise BridgeError('Invalid placement section')
            result[section] = {}
            for k, v in c[section].items():
                n = float(v)
                lo, hi = limits(k)
                if not math.isfinite(n) or not lo <= n <= hi or (k in ('WheelVisible', 'DashFollowWheel') and n not in (0, 1)):
                    raise BridgeError('Invalid placement value')
                result[section][k] = n
        return result
    except (ValueError, configparser.Error) as exc:
        raise BridgeError('Malformed placement pack') from exc


def serialize(entries):
    out = [EMPTY]
    for section, values in sorted(entries.items()):
        if values:
            out.append(f'\n[{section}]\n')
            out.extend(f'{k}={v:.9g}\n' for k, v in sorted(values.items()))
    text = ''.join(out)
    parse(text)
    return text


def merge(base, remote, local, sections, preference=None):
    # Missing local fields are deliberate reset-to-template operations, but only
    # within selected sections. Remote-only changes survive the three-way merge.
    out = {s: dict(v) for s, v in remote.items()}
    conflicts = []
    for s in sections:
        b, r, l = base.get(s, {}), remote.get(s, {}), local.get(s, {})
        target = out.setdefault(s, {})
        for k in set(b) | set(l):
            bv, rv, lv = b.get(k), r.get(k), l.get(k)
            if lv == bv:
                continue
            if rv != bv and rv != lv:
                conflicts.append(f'{s}/{k}')
                if preference != 'local':
                    continue
            if lv is None:
                target.pop(k, None)
            else:
                target[k] = lv
    if conflicts and preference is None:
        raise BridgeError('Conflicting entries: ' + ', '.join(sorted(conflicts)))
    return out, conflicts


class Device:
    def __init__(self, adb, index=None):
        self.adb = adb
        try:
            p = subprocess.run([adb, 'devices', '-l'], capture_output=True, timeout=15)
        except (OSError, subprocess.TimeoutExpired) as exc:
            raise BridgeError('ADB unavailable or unresponsive') from exc
        if p.returncode:
            raise BridgeError('ADB discovery failed')
        candidates = []
        for line in p.stdout.decode(errors='replace').splitlines()[1:]:
            fields = line.split()
            if len(fields) < 2 or fields[1] != 'device':
                continue
            serial = fields[0]
            try:
                model = subprocess.run([adb, '-s', serial, 'shell', 'getprop', 'ro.product.model'], capture_output=True, timeout=10)
            except (OSError, subprocess.TimeoutExpired):
                continue
            if model.returncode == 0 and model.stdout.strip().lower() == b'quest 3':
                candidates.append(serial)
        if not candidates:
            raise BridgeError('No authorized, responsive Quest 3 is connected')
        if index is None and len(candidates) > 1:
            raise BridgeError(f'{len(candidates)} eligible headsets; choose a device index (1 through {len(candidates)})')
        choice = 0 if index is None else index - 1
        if not 0 <= choice < len(candidates):
            raise BridgeError('Invalid device index')
        self.serial = candidates[choice]  # local memory only; never returned
        self.count = len(candidates)

    def run(self, *args, check=True):
        try:
            p = subprocess.run([self.adb, '-s', self.serial, *args], capture_output=True, timeout=30)
        except (OSError, subprocess.TimeoutExpired) as exc:
            raise BridgeError('Device command failed or timed out') from exc
        if check and p.returncode:
            raise BridgeError('Device operation failed; existing game data was preserved')
        return p

    def is_running(self):
        # pidof's nonzero status alone could mean a shell/transport failure.
        p = self.run('shell', f'if pidof {PACKAGE} >/dev/null; then echo RUNNING; else echo STOPPED; fi')
        if p.stdout.strip() not in (b'STOPPED', b'RUNNING'):
            raise BridgeError('Cannot determine game state')
        return p.stdout.strip() == b'RUNNING'

    def stopped(self):
        if self.is_running():
            raise BridgeError('Close Liberty City VR on the headset before transfer')

    def read(self, name):
        path = f'{ROOT}/../{name}' if name == 'radio_board_defaults.ini' else f'{ROOT}/{name}'
        p = self.run('shell', f'if [ -f {path} ]; then echo PRESENT; else echo ABSENT; fi')
        if p.stdout.strip() == b'ABSENT':
            return None
        if p.stdout.strip() != b'PRESENT':
            raise BridgeError('Cannot inspect headset placement files')
        with tempfile.TemporaryDirectory(prefix='lcvr-placement-') as directory:
            local = Path(directory) / 'pack.ini'
            self.run('pull', path, str(local))
            if local.stat().st_size > 4 * 1024 * 1024:
                raise BridgeError('Device configuration exceeds limits')
            return local.read_bytes()

    def install(self, name, text, expected, live=False):
        if not live:
            self.stopped()
        if self.read(name) != expected:
            raise BridgeError('Destination changed during preview; import and preview again')
        tmp_name = name + '.upload'
        try:
            with tempfile.TemporaryDirectory(prefix='lcvr-placement-') as directory:
                local = Path(directory) / 'pack.ini'
                content = text.encode('utf-8')
                local.write_bytes(content)
                self.run('push', str(local), f'{ROOT}/{tmp_name}')
                if self.read(tmp_name) != content:
                    raise BridgeError('Upload verification failed; destination preserved')
            if not live:
                self.stopped()
            if self.read(name) != expected:
                raise BridgeError('Destination changed during upload; import again')
            stamp = datetime.datetime.now(datetime.timezone.utc).strftime('%Y%m%dT%H%M%S%fZ')
            path = f'{ROOT}/{name}'
            if expected is not None:
                self.run('shell', f'cp {path} {path}.backup-{stamp}')
            self.run('shell', f'mv {ROOT}/{tmp_name} {path}')
            return name + '.backup-' + stamp if expected is not None else None
        finally:
            self.run('shell', f'rm -f {ROOT}/{tmp_name}', check=False)


    def acknowledge(self, kind, text):
        if not self.is_running():
            return False
        nonce = uuid.uuid4().hex
        with tempfile.TemporaryDirectory(prefix='lcvr-reload-') as folder:
            local = Path(folder) / 'request.txt'
            local.write_text(nonce, encoding='ascii')
            self.run('push', str(local), f'{ROOT}/vehicle_placements.reload')
        expected = str(content_hash(text.encode('utf-8')))
        deadline = time.monotonic() + 10
        while time.monotonic() < deadline:
            raw = self.read('vehicle_placements.live.ini')
            if raw:
                try:
                    status = configparser.ConfigParser()
                    status.read_string(raw.decode('ascii'))
                    if status.get('LivePlacement', 'Version', fallback='') == '1' and status.get('LivePlacement', 'Request', fallback='') == nonce and status.get('LivePlacement', kind, fallback='') == expected:
                        return True
                except (UnicodeError, configparser.Error):
                    pass
            time.sleep(.15)
        raise BridgeError('Pack installed, but the running game did not acknowledge it. Update the APK or resume the game; live sync has stopped.')


def content_hash(data):
    value = 14695981039346656037
    for byte in data:
        value = ((value ^ byte) * 1099511628211) & ((1 << 64) - 1)
    return value


def main(argv=None):
    p = argparse.ArgumentParser(description=__doc__)
    p.add_argument('action', choices=['status', 'import', 'preview', 'deploy', 'restore'])
    p.add_argument('--workspace', type=Path, required=True)
    p.add_argument('--adb', default='adb')
    p.add_argument('--device-index', type=int)
    p.add_argument('--kind', choices=['template', 'personal'], default='personal')
    p.add_argument('--pack', type=Path)
    p.add_argument('--sections', default='')
    p.add_argument('--prefer', choices=['local', 'remote'])
    p.add_argument('--live', action='store_true', help='Allow atomic deployment while the updated game runs and verify reload acknowledgement')
    p.add_argument('--backup', help='Exact configuration backup filename returned by deployment')
    a = p.parse_args(argv)
    try:
        d = Device(a.adb, a.device_index)
        if a.action == 'status':
            print(f'personal Quest 3 device: authorized and responsive; eligible headsets: {d.count}')
            return 0
        baseline = a.workspace / '.device-baseline'
        if a.action == 'restore':
            d.stopped()
            name = FILES[a.kind]
            if not a.backup or not re.fullmatch(re.escape(name) + r'\.backup-[0-9]{8}T[0-9]{12}Z', a.backup):
                raise BridgeError('Choose a valid backup filename for this placement layer')
            raw = d.read(a.backup)
            if raw is None:
                raise BridgeError('Configuration backup is unavailable')
            text = serialize(parse(raw.decode('utf-8-sig')))
            backup = d.install(name, text, d.read(name))
            print('Restored configuration on personal Quest 3 device. Import again before further edits. Restart the game to apply.')
            if backup:
                print('Previous configuration backup: ' + backup)
            return 0
        if a.action == 'import':
            # Stage all reads and validation before replacing any local file.
            staged = {}
            for name in [*FILES.values(), 'vr_settings.ini', 'radio_board.ini', 'radio_board_defaults.ini']:
                content = d.read(name)
                if content is not None and name in FILES.values():
                    parse(content.decode('utf-8-sig'))
                staged[name] = content
            baseline.mkdir(parents=True, exist_ok=True)
            for name, content in staged.items():
                if name in FILES.values():
                    content = content or EMPTY.encode()
                else:
                    content = content or b''
                dest = a.workspace / name
                if dest.exists():
                    shutil.copy2(dest, dest.with_suffix(dest.suffix + '.before-import'))
                dest.write_bytes(content)
                (baseline / name).write_bytes(content)
            print('Imported placement layers and legacy settings from personal Quest 3 device. Classic/Modern legacy values remain shared fallbacks.')
            return 0
        if a.pack is None:
            raise BridgeError('Choose a saved placement pack')
        name = FILES[a.kind]
        base_path = baseline / name
        if not base_path.exists():
            raise BridgeError('Import the headset configuration before previewing or deploying')
        base = parse(base_path.read_text(encoding='utf-8-sig'))
        local = parse(a.pack.read_text(encoding='utf-8-sig'))
        raw = d.read(name)
        remote = parse(raw.decode('utf-8-sig')) if raw is not None else {}
        sections = a.sections.split(',') if a.sections else sorted(set(base) | set(local))
        if any(not re.fullmatch(r'(classic|modern|xbox):[0-9]{1,5}', s) for s in sections):
            raise BridgeError('Invalid selected entries')
        merged, conflicts = merge(base, remote, local, sections, a.prefer)
        text = serialize(merged)
        changed = sum(remote.get(s, {}).get(k) != merged.get(s, {}).get(k)
                      for s in set(remote) | set(merged)
                      for k in set(remote.get(s, {})) | set(merged.get(s, {})))
        print(f'{a.kind}: {len(sections)} selected entries, {changed} changed fields, {len(conflicts)} resolved conflicts.')
        for s in sections:
            for k in sorted(set(remote.get(s, {})) | set(merged.get(s, {}))):
                before, after = remote.get(s, {}).get(k), merged.get(s, {}).get(k)
                if before != after:
                    print(f'{s}/{k}: {before} -> {after}')
        if a.kind == 'template':
            personal_raw = d.read(FILES['personal'])
            personal = parse(personal_raw.decode('utf-8-sig')) if personal_raw else {}
            masked = [f'{s}/{k}' for s in sections for k in merged.get(s, {}) if k in personal.get(s, {})]
            if masked:
                print('Personal overrides mask template fields: ' + ', '.join(masked))
        if a.action == 'deploy':
            backup = d.install(name, text, raw, live=a.live)
            (baseline / name).write_text(text, encoding='utf-8')
            if a.live and d.acknowledge(a.kind, text):
                print('Live reload acknowledged by the running game.')
            else:
                print('The installed pack will load when the game starts.')
            print('Installed on personal Quest 3 device with backup and verified upload. Transfer complete.')
            if backup:
                print('Previous configuration backup: ' + backup)
        return 0
    except (BridgeError, OSError, UnicodeError) as exc:
        # Only our deliberately sanitized messages are safe to display.
        print(str(exc) if isinstance(exc, BridgeError) else 'Local configuration operation failed', file=sys.stderr)
        return 1


if __name__ == '__main__':
    sys.exit(main())

import contextlib
import importlib.util
import io
from pathlib import Path
import subprocess
import tempfile
import unittest
from unittest.mock import patch

spec = importlib.util.spec_from_file_location('bridge', Path(__file__).with_name('device_bridge.py'))
b = importlib.util.module_from_spec(spec)
spec.loader.exec_module(b)


class PackTests(unittest.TestCase):
    def test_validation_and_roundtrip(self):
        entries = {'xbox:95': {'WheelX': 2, 'DashFollowWheel': 0, 'MapPitch': 33, 'RadioX': 35, 'RadioRoll': -180, 'RadioSize': 125, 'SpeedometerX': 4, 'SpeedometerY': 8, 'SpeedometerZ': 22, 'SpeedometerPitch': -15, 'SpeedometerYaw': 20, 'SpeedometerRoll': -180, 'SpeedometerSize': 125}}
        self.assertEqual(b.parse(b.serialize(entries)), entries)
        for text in ('[Placement]\nVersion=2', '[Placement]\nVersion=1\n[xbox:95]\nWheelX=nan',
                     '[Placement]\nVersion=1\n[xbox:95]\nWheelVisible=.3',
                     '[Placement]\nVersion=1\n[xbox:95]\nWheelRadius=1',
                     '[Placement]\nVersion=1\n[xbox:95]\nUnknown=3',
                     '[Placement]\nVersion=1\n[xbox:95]\nSpeedometerSize=0',
                     '[Placement]\nVersion=1\n[xbox:95]\nSpeedometerPitch=181',
                     '[Placement]\nVersion=1\n[xbox:95]\nWheelX=1\nWheelX=2'):
            with self.assertRaises(b.BridgeError):
                b.parse(text)

    def test_preserve_unrelated_remote_changes(self):
        base = {'classic:95': {'WheelX': 0, 'WheelY': 0}, 'xbox:95': {'WheelX': 1}}
        remote = {'classic:95': {'WheelX': 0, 'WheelY': 9}, 'xbox:95': {'WheelX': 8}}
        local = {'classic:95': {'WheelX': 3, 'WheelY': 0}, 'xbox:95': {'WheelX': 1}}
        result, conflicts = b.merge(base, remote, local, ['classic:95'])
        self.assertEqual(result, {'classic:95': {'WheelX': 3, 'WheelY': 9}, 'xbox:95': {'WheelX': 8}})
        self.assertEqual(conflicts, [])

    def test_conflicts_and_resolution(self):
        base = {'xbox:95': {'WheelX': 0}}
        remote = {'xbox:95': {'WheelX': 1}}
        local = {'xbox:95': {'WheelX': 2}}
        with self.assertRaises(b.BridgeError):
            b.merge(base, remote, local, ['xbox:95'])
        self.assertEqual(b.merge(base, remote, local, ['xbox:95'], 'local')[0], local)
        self.assertEqual(b.merge(base, remote, local, ['xbox:95'], 'remote')[0], remote)

    def test_reset_and_concurrent_new_field(self):
        base = {'xbox:95': {'WheelX': 0}}
        remote = {'xbox:95': {'WheelX': 0, 'MapX': 5}}
        self.assertEqual(b.merge(base, remote, {}, ['xbox:95'])[0], {'xbox:95': {'MapX': 5}})


class DiscoveryTests(unittest.TestCase):
    def discover(self, output, model=b'Quest 3', index=None):
        def run(args, **kwargs):
            return subprocess.CompletedProcess(args, 0, output if args[1:3] == ['devices', '-l'] else model, b'')
        with patch.object(b.subprocess, 'run', side_effect=run):
            return b.Device('adb', index)

    def test_no_eligible_device(self):
        for output, model in [(b'List of devices attached\n', b''),
                              (b'List of devices attached\ntest-target unauthorized\n', b'Quest 3'),
                              (b'List of devices attached\ntest-target device\n', b'Unrelated phone'),
                              (b'List of devices attached\ntest-target offline\n', b'Quest 3')]:
            with self.assertRaises(b.BridgeError) as error:
                self.discover(output, model)
            self.assertNotIn('test-target', str(error.exception))

    def test_multiple_devices_require_selection(self):
        output = b'List of devices attached\ntest-one device\ntest-two device\n'
        with self.assertRaises(b.BridgeError):
            self.discover(output)
        self.assertEqual(self.discover(output, index=2).serial, 'test-two')

    def test_missing_adb_sanitized(self):
        with patch.object(b.subprocess, 'run', side_effect=OSError('sensitive transport output')):
            with self.assertRaises(b.BridgeError) as error:
                b.Device('adb')
        self.assertNotIn('sensitive', str(error.exception))


class TransferTests(unittest.TestCase):
    def device(self, remote=b.EMPTY.encode()):
        d = object.__new__(b.Device)
        d.files = {b.FILES['personal']: remote}
        d.commands = []
        d.running = False
        d.corrupt = False
        def run(*args, check=True):
            d.commands.append(args)
            if args[0] == 'push':
                d.files[args[2].split('/')[-1]] = b'corrupt' if d.corrupt else Path(args[1]).read_bytes()
            elif args[:1] == ('shell',):
                cmd = args[1]
                if cmd.startswith('if pidof'):
                    return subprocess.CompletedProcess(args, 0, b'RUNNING' if d.running else b'STOPPED', b'')
                if cmd.startswith('cp '):
                    _, src, dst = cmd.split()
                    d.files[dst.split('/')[-1]] = d.files[src.split('/')[-1]]
                if cmd.startswith('mv '):
                    _, src, dst = cmd.split()
                    d.files[dst.split('/')[-1]] = d.files.pop(src.split('/')[-1])
                if cmd.startswith('rm -f '):
                    d.files.pop(cmd.split('/')[-1], None)
            return subprocess.CompletedProcess(args, 0, b'', b'')
        d.run = run
        d.read = lambda name: d.files.get(name)
        return d

    def test_verified_install_keeps_backup(self):
        d = self.device()
        text = b.serialize({'xbox:95': {'WheelX': 5}})
        d.install(b.FILES['personal'], text, b.EMPTY.encode())
        self.assertEqual(d.files[b.FILES['personal']], text.encode())
        backups = [v for k, v in d.files.items() if '.backup-' in k]
        self.assertEqual(backups, [b.EMPTY.encode()])
        self.assertFalse(any(k.endswith('.upload') for k in d.files))

    def test_live_install_and_acknowledgement(self):
        d = self.device()
        d.running = True
        text = b.serialize({'xbox:106': {'RadioRoll': 61.64}})
        d.install(b.FILES['personal'], text, b.EMPTY.encode(), live=True)
        self.assertEqual(d.files[b.FILES['personal']], text.encode())
        read = d.read
        def status(name):
            if name == 'vehicle_placements.live.ini':
                nonce = d.files.get('vehicle_placements.reload', b'').decode()
                return f'[LivePlacement]\nVersion=1\nRequest={nonce}\npersonal={b.content_hash(text.encode())}\n'.encode()
            return read(name)
        d.read = status
        self.assertTrue(d.acknowledge('personal', text))
        d.running = False
        self.assertFalse(d.acknowledge('personal', text))

    def test_missing_live_acknowledgement_is_failure(self):
        d = self.device(); d.running = True
        with patch.object(b.time, 'monotonic', side_effect=[0, 11]):
            with self.assertRaises(b.BridgeError):
                d.acknowledge('personal', b.EMPTY)

    def test_failed_upload_preserves_destination(self):
        d = self.device()
        d.corrupt = True
        with self.assertRaises(b.BridgeError):
            d.install(b.FILES['personal'], b.EMPTY, b.EMPTY.encode())
        self.assertEqual(d.files, {b.FILES['personal']: b.EMPTY.encode()})

    def test_running_game_and_changed_destination(self):
        d = self.device()
        d.running = True
        with self.assertRaises(b.BridgeError):
            d.install(b.FILES['personal'], b.EMPTY, b.EMPTY.encode())
        d.running = False
        with self.assertRaises(b.BridgeError):
            d.install(b.FILES['personal'], b.EMPTY, b'old contents')
        self.assertFalse(any(c[0] == 'push' for c in d.commands))

    def test_interrupted_upload(self):
        d = self.device()
        original = d.run
        def run(*args, **kwargs):
            if args[0] == 'push':
                raise b.BridgeError('Device operation failed')
            return original(*args, **kwargs)
        d.run = run
        with self.assertRaises(b.BridgeError):
            d.install(b.FILES['personal'], b.EMPTY, b.EMPTY.encode())
        self.assertEqual(d.files[b.FILES['personal']], b.EMPTY.encode())

    def test_restore_backup_and_preserve_current(self):
        d = self.device(b.serialize({'xbox:95': {'WheelX': 12}}).encode())
        name = b.FILES['personal'] + '.backup-20261024T120000123456Z'
        d.files[name] = b.serialize({'xbox:95': {'WheelX': 5}}).encode()
        with patch.object(b, 'Device', return_value=d), contextlib.redirect_stdout(io.StringIO()):
            self.assertEqual(b.main(['restore', '--workspace', '.', '--backup', name]), 0)
        self.assertEqual(b.parse(d.files[b.FILES['personal']].decode()), {'xbox:95': {'WheelX': 5}})
        self.assertTrue(any(b'WheelX=12' in v for k, v in d.files.items() if '.backup-' in k))


if __name__ == '__main__':
    unittest.main()

param(
 [Parameter(Mandatory=$true)][string]$StageRoot,
 [string]$OutDir = (Join-Path ([IO.Path]::GetTempPath()) ('garage-exit-' + [Guid]::NewGuid().ToString('N')))
)
$ErrorActionPreference='Stop'
$source=[IO.File]::ReadAllText((Join-Path $StageRoot 'src/control/Garages.cpp'))
$function=[regex]::Match($source,'(?ms)^bool CGarage::IsEntityEntirelyOutside\([^\n]*\)\r?\n\{.*?^\}').Value
if($function -notmatch 'VrGetViewBasis'){throw 'Missing production headset clearance check.'}
[IO.File]::WriteAllText((Join-Path $PSScriptRoot 'garage-exit-helper.inc'),$function)
$camera=[regex]::Match($source,'(?ms)^void CGarage::Update\(\)\r?\n\{(.*?)(?=\tif \(m_bDeactivated)').Groups[1].Value
if($camera -notmatch '#ifndef __ANDROID__'){throw 'Missing Quest garage camera bypass.'}
[IO.File]::WriteAllText((Join-Path $PSScriptRoot 'garage-camera-helper.inc'),('void CGarage::UpdateCamera() {'+"`n"+$camera+"`n}"))
$mission=[regex]::Match($source,'(?s)\tcase GARAGE_MISSION:\r?\n\t\tswitch.*?(?=\tcase GARAGE_COLLECTSPECIFICCARS:)').Value
$closing=[regex]::Match($mission,'(?s)case GS_CLOSING:\s*(.*?)(?=\t\t\tm_fDoorPos)').Groups[1].Value
if($closing -notmatch 'SetEnablePlayerControls'){throw 'Missing delivery closure interlock.'}
[IO.File]::WriteAllText((Join-Path $PSScriptRoot 'garage-closing-helper.inc'),('void CGarage::UpdateClosing() { do {'+"`n"+$closing+"`n advancedDoor=true; } while(false); }"))
& (Join-Path $PSScriptRoot 'test-ragdoll.ps1') -KitRoot (Split-Path -Parent (Split-Path -Parent $PSScriptRoot)) -OutDir $OutDir -Sources @('test-garage-exit.cpp')
if($LASTEXITCODE -ne 0){throw 'Garage exit regression failed.'}
$wrapper=Join-Path $PSScriptRoot 'test-garage-exit-desktop.cpp'
try {
 [IO.File]::WriteAllText($wrapper,('#define GARAGE_DESKTOP 1'+"`n"+'#include "test-garage-exit.cpp"'))
 & (Join-Path $PSScriptRoot 'test-ragdoll.ps1') -KitRoot (Split-Path -Parent (Split-Path -Parent $PSScriptRoot)) -OutDir ($OutDir+'-desktop') -Sources @('test-garage-exit-desktop.cpp')
 if($LASTEXITCODE -ne 0){throw 'Desktop garage exit regression failed.'}
} finally { Remove-Item -LiteralPath $wrapper -ErrorAction SilentlyContinue }

param(
    [Parameter(Mandatory=$true)][string]$StageRoot,
    [string]$OutDir = (Join-Path ([IO.Path]::GetTempPath()) ('lcvr-ped-damage-' + [Guid]::NewGuid().ToString('N')))
)
$ErrorActionPreference='Stop'
# Compile the actual patched damage-record function with small entity adapters.
$physical=[IO.File]::ReadAllText((Join-Path $StageRoot 'src/entities/Physical.cpp'))
$m=[regex]::Match($physical,'(?m)^void\s+CPhysical::SetDamagedPieceRecord\([^)]*\)\s*\{')
if(-not $m.Success){throw 'Missing production damage-record function.'}
$end=$m.Index+$m.Length;$depth=1
while($depth -gt 0 -and $end -lt $physical.Length){
    if($physical[$end]-eq'{'){$depth++}elseif($physical[$end]-eq'}'){$depth--};$end++
}
if($depth-ne0){throw 'Unterminated production function.'}
$function=$physical.Substring($m.Index,$end-$m.Index)
foreach($mode in @('fixed','legacy')){
    $prefix=if($mode-eq'fixed'){"#define FIX_BUGS`n"}else{''}
    [IO.File]::WriteAllText((Join-Path $PSScriptRoot 'ped-vehicle-damage-production.inc'),$prefix+$function,[Text.UTF8Encoding]::new($false))
    & (Join-Path $PSScriptRoot 'test-ragdoll.ps1') -KitRoot $StageRoot -OutDir ($OutDir+'-'+$mode) -Sources @('test-ped-vehicle-damage.cpp')
    if($LASTEXITCODE-ne0){throw "Pedestrian vehicle damage fixture failed: $mode"}
}

param(
    [Parameter(Mandatory=$true)][string]$StageRoot,
    [string]$OutDir = (Join-Path ([IO.Path]::GetTempPath()) ('lcvr-sun-' + [Guid]::NewGuid().ToString('N')))
)
$ErrorActionPreference = 'Stop'
$source = [IO.File]::ReadAllText((Join-Path $StageRoot 'src/renderer/Coronas.cpp'))
function Definition([string]$name, [string]$returnType) {
    $match = [regex]::Match($source, '(?m)^' + [regex]::Escape($name) + '\(')
    if (-not $match.Success) { throw "Missing production function: $name" }
    $brace = $source.IndexOf('{', $match.Index)
    $depth = 1; $end = $brace + 1
    while ($depth -gt 0 -and $end -lt $source.Length) {
        if ($source[$end] -eq '{') { $depth++ }
        if ($source[$end] -eq '}') { $depth-- }
        $end++
    }
    if ($depth -ne 0) { throw "Unclosed production function: $name" }
    return $returnType + "`n" + $source.Substring($match.Index, $end - $match.Index)
}
$parts = @((Definition 'QuestSunSightClear' 'static bool'), (Definition 'CCoronas::Render' 'void'), (Definition 'CRegisteredCorona::Update' 'void'))
[IO.File]::WriteAllText((Join-Path $PSScriptRoot 'sun-occlusion-production.inc'), ($parts -join "`n"), [Text.UTF8Encoding]::new($false))
& (Join-Path $PSScriptRoot 'test-ragdoll.ps1') -OutDir $OutDir -Sources @('test-sun-occlusion.cpp')
if ($LASTEXITCODE -ne 0) { throw 'Sun occlusion regression failed.' }
